void s2a_gpu_safe_stop(const char *why);   // graphics/nvn/host_adapt.m：安全停之后宿主那一侧（冻游戏线程、iOS 上出错误页 / Mac 收局）
static NSArray<NSString *> *quar_take(void); static void quar_fault(NSArray<NSString *> *sus, NSError *err);   // GPU error quarantine (defined with the pipeline user list)
typedef struct qf_set qf_set; static qf_set *qf_take(void); static void qf_report(const qf_set *q, const char *where, uint64_t seq);   // GPU error attribution: a commit's in-flight programs (defined after the quarantine)
// ---------- GPU 挂死安全停（11-07 Switch2 线 84，维护者「这种严重 bug 要避免，太吓人了」）----------
// 测试设备2 金刚第 2228 帧主命令缓冲报 kIOGPUCommandBufferCallbackErrorHang，宿主照常提交，之后全是 InnocentVictim / SubmissionsIgnored、连续挂死，整机卡死只能强制重启。
//   旧判法（host_adapt.m s2a_gpu_timeout_check）只在 localizedDescription 里找 Hang / Timeout：Metal 4 的错误把真实原因包在 NSMultipleUnderlyingErrorsKey 里，顶层
//   localizedDescription 是本地化的「未能完成操作。（MTL4CommandQueueErrorDomain错误1。）」，一次也没命中；命中了也只是派到别的线程收局，收局前各线程照常提交。
// 现在：所有命令缓冲报错都进 mtl_gpu_cb_error（唯一判定点），把错误连同各层 underlying 错误一起判；本进程的 Hang / Timeout / PageFault（不含被别人牵连的 InnocentVictim、
//   被系统拒收的 SubmissionsIgnored）→ mtl_gpu_halt 置 g_gpu_halt。此后一切往 GPU 的提交（主回放 / 分段 / 上传批 / 上屏 / 截图 / 回读 / 队列等待 / Vulkan 与 GL 前端）
//   在 gpu_go() 处直接不交，不再往驱动送任何东西；宿主侧（s2a_gpu_safe_stop）冻游戏线程、iOS 上用 UIKit 原生视图盖错误页（不经 Metal）
static _Atomic uint64_t g_cur_frame;   // defined with the frame statistics below (tentative definition)
static _Atomic int g_gpu_halt;
static _Atomic uint64_t g_gpu_commits, g_gpu_refused, g_gpu_err_after;   // 放行的提交数；安全停后拒交的次数；安全停后又回来的报错（连带错误，只计数不刷屏）
static void (*g_gpu_halt_notify)(const char *why) = s2a_gpu_safe_stop;   // 单测（t_nvn_gpu_halt.m 同 TU 包含本文件）换成自己的记录函数
int mtl_gpu_halted(void) { return atomic_load_explicit(&g_gpu_halt, memory_order_relaxed); }
// 每个真正往 GPU 交东西的地方先过它：安全停后返回 0，调用方不交、不等
static inline int gpu_go(void) {
    if (!atomic_load_explicit(&g_gpu_halt, memory_order_relaxed)) { atomic_fetch_add_explicit(&g_gpu_commits, 1, memory_order_relaxed); return 1; }
    atomic_fetch_add_explicit(&g_gpu_refused, 1, memory_order_relaxed); return 0;
}
int mtl_gpu_go(void) { return gpu_go(); }   // Vulkan / GL 前端（gfx/vk/hle_vk.m、gfx/gl/gl_draw.m）同一道门
// 判错误是不是本进程自己的 GPU 挂死 / 超时 / 缺页：1 = 是；0 = 连带错误（InnocentVictim / SubmissionsIgnored）或别的错误。各层 underlying 错误都看：
//   IOGPU 层的原因名（kIOGPUCommandBufferCallbackError*）不随系统语言翻译；Metal 3 旧队列的 MTLCommandBufferErrorDomain 另按错误码（Timeout 2 / PageFault 3）
static void gpu_err_walk(NSError *e, int depth, int *fatal, int *victim) {
    if (!e || depth > 6) return;
    NSString *d = [NSString stringWithFormat:@"%@ %@", e.localizedDescription ?: @"", e.userInfo[NSLocalizedDescriptionKey] ?: @""];
    if ([d containsString:@"InnocentVictim"] || [d containsString:@"SubmissionsIgnored"]) *victim = 1;
    if ([d containsString:@"CallbackErrorHang"] || [d containsString:@"CallbackErrorTimeout"] || [d containsString:@"PageFault"]) *fatal = 1;
    // GPU 内存用满（kIOGPUCommandBufferCallbackErrorOutOfMemory / Metal 3 错误码 8）：原先不算、照常继续交，越交越满。#327 D-DNWG（iPhone 15 Pro Max，空之轨迹 the 1st）：
    //   零拷贝池整块驻留 3669 MB、GPU 已分配 5127 MB，第一条之后 49 条、画面停在第 5364 帧再没动，整机卡死要硬重启。一出现就按本进程挂死安全停
    if ([d containsString:@"CallbackErrorOutOfMemory"]) *fatal = 1;
    if ([e.domain isEqualToString:MTLCommandBufferErrorDomain] && (e.code == MTLCommandBufferErrorTimeout || e.code == MTLCommandBufferErrorPageFault || e.code == MTLCommandBufferErrorOutOfMemory)) *fatal |= 2;   // 2 = 只有错误码（没有 IOGPU 原因名）
    id u = e.userInfo[NSUnderlyingErrorKey]; if ([u isKindOfClass:NSError.class]) gpu_err_walk(u, depth + 1, fatal, victim);
    id m = e.userInfo[@"NSMultipleUnderlyingErrorsKey"]; if ([m isKindOfClass:NSArray.class]) for (id x in (NSArray *)m) if ([x isKindOfClass:NSError.class]) gpu_err_walk(x, depth + 1, fatal, victim);
}
int mtl_gpu_err_fatal(NSError *e) {
    int fatal = 0, victim = 0; gpu_err_walk(e, 0, &fatal, &victim);
    if (fatal & 1) return 1;            // 有本进程的 Hang / Timeout / PageFault 原因名
    return fatal && !victim;            // 只有 Metal 3 错误码：被牵连 / 被拒收的那几种不算
}
// 这条错误是不是只有「GPU 内存用满」。链上有 IOGPU 原因名时以原因名为准（外层错误码可能是别的，如 Timeout），没有原因名才看错误码；
//   带挂死 / 超时 / 缺页、被牵连 / 被拒收的都不算。11-23 iPad 原文：MTLCommandBufferErrorDomain Code=8 "Insufficient Memory (…kIOGPUCommandBufferCallbackErrorOutOfMemory)"，里层 IOGPUCommandQueueErrorDomain Code=8
static void gpu_err_kinds(NSError *e, int depth, int *name_oom, int *name_other, int *code_oom, int *code_other) {
    if (!e || depth > 6) return;
    NSString *d = [NSString stringWithFormat:@"%@ %@", e.localizedDescription ?: @"", e.userInfo[NSLocalizedDescriptionKey] ?: @""];
    if ([d containsString:@"CallbackErrorOutOfMemory"]) *name_oom = 1;
    if ([d containsString:@"CallbackErrorHang"] || [d containsString:@"CallbackErrorTimeout"] || [d containsString:@"PageFault"] || [d containsString:@"InnocentVictim"] || [d containsString:@"SubmissionsIgnored"]) *name_other = 1;
    if ([e.domain isEqualToString:MTLCommandBufferErrorDomain]) { if (e.code == MTLCommandBufferErrorOutOfMemory) *code_oom = 1; else if (e.code == MTLCommandBufferErrorTimeout || e.code == MTLCommandBufferErrorPageFault) *code_other = 1; }
    id u = e.userInfo[NSUnderlyingErrorKey]; if ([u isKindOfClass:NSError.class]) gpu_err_kinds(u, depth + 1, name_oom, name_other, code_oom, code_other);
    id m = e.userInfo[@"NSMultipleUnderlyingErrorsKey"]; if ([m isKindOfClass:NSArray.class]) for (id x in (NSArray *)m) if ([x isKindOfClass:NSError.class]) gpu_err_kinds(x, depth + 1, name_oom, name_other, code_oom, code_other);
}
static int gpu_err_only_oom(NSError *e) { int no = 0, nx = 0, co = 0, cx = 0; gpu_err_kinds(e, 0, &no, &nx, &co, &cx); return no || nx ? no && !nx : co && !cx; }
static void res_drop_all(void);
// 安全停：唯一置位处。why = 第一条错误原文
void mtl_gpu_halt(const char *why) {
    if (atomic_exchange(&g_gpu_halt, 1)) return;
    MLOG("【红】 GPU 挂死安全停：%s；帧 %llu，最近提交栅栏 %llu，已放行提交 %llu 次；此后不再往 GPU 提交任何命令缓冲", why ? why : "-",
         (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)g_fence, (unsigned long long)atomic_load(&g_gpu_commits));
    // GPU 内存用满停下的：此后不再提交，驻留集里钉着的（iOS 上是全机共用的 wired 内存）当场整个放掉，手机缓过来、能退回主屏，不等进程退出
    if (why && strstr(why, "OutOfMemory")) res_drop_all();
    if (g_gpu_halt_notify) g_gpu_halt_notify(why);
}
// 所有命令缓冲报错的入口（where = 哪条队列 / 哪类提交，seq = 栅栏号或批号，0 = 没有）。返回 1 = 已在安全停（调用方别再刷红行）
// DM_NVN_FAULT_ENC=1（诊断，默认关，只在 Metal 3 后端有效，#770）：主命令缓冲带「逐编码器执行状态」建出来，各遍开头、每次换管线、每笔 task / mesh 绘制各插一条调试标记；
//   命令缓冲报错时把出事（faulted）与被牵连（affected）的编码器连同它的标记打出来，直接读出挂死落在哪一遍、那一遍画过哪些着色器。Metal 4 的提交回执没有逐编码器状态，不适用
static int fault_enc_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_NVN_FAULT_ENC"); v = g_m3 && e && *e == '1'; if (e && *e == '1') MLOG("DM_NVN_FAULT_ENC: %s", v ? "on (per-encoder execution status and debug signposts; diagnostic)" : "ignored (Metal 3 backend only)"); }
    return v;
}
// The converted arguments of the last indirect task / mesh draws (ixc_arrays: {workgroups, 1, 1, 0, first}), kept with their arena buffer so that the dump can read what the GPU was handed.
//   The arena buffers are shared storage and the ring retains them, so the read is of live memory
#define FAULT_RING 64
static id<MTLBuffer> g_fr_keep[FAULT_RING]; static const uint32_t *g_fr_arg[FAULT_RING]; static uint64_t g_fr_frame[FAULT_RING]; static char g_fr_key[FAULT_RING][40]; static uint32_t g_fr_n;
static os_unfair_lock g_fr_lock = OS_UNFAIR_LOCK_INIT;
static void fault_ring_put(id<MTLBuffer> b, NSUInteger o, const char *ts, const char *ms, uint64_t frame) {
    os_unfair_lock_lock(&g_fr_lock);
    uint32_t k = g_fr_n++ % FAULT_RING;
    g_fr_keep[k] = b; g_fr_arg[k] = (const uint32_t *)((const uint8_t *)b.contents + o); g_fr_frame[k] = frame; snprintf(g_fr_key[k], sizeof g_fr_key[k], "%.17s/%.17s", ts ? ts : "-", ms ? ms : "-");
    os_unfair_lock_unlock(&g_fr_lock);
}
static void fault_ring_dump(void) {
    os_unfair_lock_lock(&g_fr_lock);
    uint32_t n = g_fr_n < FAULT_RING ? g_fr_n : FAULT_RING;
    // Only the faulted frame's values are what the GPU was handed: an earlier frame's arena buffer has been reused since, a later frame's conversion has not run yet
    MLOG("【红】 DM_NVN_FAULT_ENC: indirect task / mesh draws so far %u; the converted arguments of the last %u follow, oldest first (read the faulted frame's only: earlier frames' buffers are reused, later frames' are not written yet)", g_fr_n, n);
    for (uint32_t i = 0; i < n; i++) { uint32_t k = (g_fr_n - n + i) % FAULT_RING; const uint32_t *a = g_fr_arg[k];
        MLOG("【红】 DM_NVN_FAULT_ENC:   frame %llu task/mesh %s: workgroups %u,%u,%u first %u", (unsigned long long)g_fr_frame[k], g_fr_key[k], a[0], a[1], a[2], a[4]); }
    os_unfair_lock_unlock(&g_fr_lock);
}
static void fault_enc_dump(NSError *e, const char *where, uint64_t seq) {
    static _Atomic int n;
    NSArray<id<MTLCommandBufferEncoderInfo>> *inf = e.userInfo[MTLCommandBufferEncoderInfoErrorKey];
    if (!inf || atomic_fetch_add(&n, 1) >= 2) return;
    static const char *const st[] = { "unknown", "completed", "affected", "pending", "faulted" };
    NSUInteger cnt[5] = {0}, i = 0;
    for (id<MTLCommandBufferEncoderInfo> x in inf) cnt[x.errorState <= 4 ? x.errorState : 0]++;
    MLOG("【红】 DM_NVN_FAULT_ENC: %s command buffer %llu has %lu encoders: completed %lu, faulted %lu, affected %lu, pending %lu, unknown %lu", where ? where : "-", (unsigned long long)seq,
         (unsigned long)inf.count, (unsigned long)cnt[1], (unsigned long)cnt[4], (unsigned long)cnt[2], (unsigned long)cnt[3], (unsigned long)cnt[0]);
    for (id<MTLCommandBufferEncoderInfo> x in inf) {
        NSUInteger k = i++; MTLCommandEncoderErrorState es = x.errorState;
        if (es != MTLCommandEncoderErrorStateFaulted && es != MTLCommandEncoderErrorStateAffected) continue;
        NSArray<NSString *> *sp = x.debugSignposts;
        MLOG("【红】 DM_NVN_FAULT_ENC: encoder %lu of %lu %s, %lu signposts", (unsigned long)k, (unsigned long)inf.count, st[es <= 4 ? es : 0], (unsigned long)sp.count);
        NSString *last = nil; NSUInteger rep = 0, shown = 0;
        for (NSString *m in sp) {
            if (last && [m isEqualToString:last]) { rep++; continue; }
            if (last && shown++ < 400) MLOG("【红】 DM_NVN_FAULT_ENC:   encoder %lu: %s%s", (unsigned long)k, last.UTF8String, rep ? [NSString stringWithFormat:@" (x%lu)", (unsigned long)rep + 1].UTF8String : "");
            last = m; rep = 0;
        }
        if (last) MLOG("【红】 DM_NVN_FAULT_ENC:   encoder %lu: %s%s", (unsigned long)k, last.UTF8String, rep ? [NSString stringWithFormat:@" (x%lu)", (unsigned long)rep + 1].UTF8String : "");
    }
    fault_ring_dump();
}
int mtl_gpu_cb_error(NSError *e, const char *where, uint64_t seq) {
    if (!e) return mtl_gpu_halted();
    if (fault_enc_on()) fault_enc_dump(e, where, seq);
    if (mtl_gpu_halted()) { atomic_fetch_add_explicit(&g_gpu_err_after, 1, memory_order_relaxed); return 1; }
    if (!mtl_gpu_err_fatal(e)) return 0;
    char w[1600]; snprintf(w, sizeof w, "%s 命令缓冲（序号 %llu）报 GPU 挂死 / 超时 / 缺页：%s", where ? where : "-", (unsigned long long)seq, e.description.UTF8String);
    mtl_gpu_halt(w);
    return 1;
}
static _Atomic int g_up_pending;

static pthread_mutex_t g_res_mu = PTHREAD_MUTEX_INITIALIZER;   // Dedicated lock for the residency set: res_add is called on paths that hold g_mu (arena_new), so it cannot share g_mu
#include "../../../../runtime/include/s2a_qos.h"   // 全进程线程调度档一张表（11-06 Switch2 线 71）
#include "../../../../runtime/include/s2a_docs.h"  // 文档根唯一取法（S2A_DOCS，否则 $HOME/Documents）
#include "nvn_rec.h"   // deferred encoding (DM_NVN_ENC_THREAD)
#include "nvn_warm.h"   // the prewarm's progress for the host's loading page (s2a_warm_progress)
#include "nvn_be.h"
// Commit feedback on both backends: fb_new makes the MTL4CommitOptions on Metal 4 and a list on Metal 3, fb_add adds a handler to either. On Metal 3 m3_commit makes each handler a
// completed handler and passes it the command buffer, which answers error / GPUStartTime / GPUEndTime as the commit feedback does (the only things the handlers read)
typedef void (^fb_fn)(id<MTL4CommitFeedback> f);
static inline id fb_new(void) { return g_m3 ? [NSMutableArray array] : [MTL4CommitOptions new]; }
static inline void fb_add(id o, fb_fn h) { if (g_m3) [(NSMutableArray *)o addObject:h]; else [(MTL4CommitOptions *)o addFeedbackHandler:h]; }
// Metal 3 commit: the feedback handlers become completed handlers and a fence signal is encoded at its end (Metal 4 signals on the queue after the commit, rec_signal).
// With the encode thread on this runs on that thread (rec_commit_m3 records it), which is why the handlers must be recorded with it
// A Metal 3 command buffer on g_q3. Unretained references as on Metal 4, where command buffers retain nothing: the replay already keeps what a command buffer uses alive until its fence
// has completed (defer_obj_release, g_done is advanced by the completion handler)
static id<MTLCommandBuffer> m3_cb(void) {
    if (!fault_enc_on()) return [g_q3 commandBufferWithUnretainedReferences];
    MTLCommandBufferDescriptor *d = [MTLCommandBufferDescriptor new]; d.retainedReferences = NO; d.errorOptions = MTLCommandBufferErrorOptionEncoderExecutionStatus;   // DM_NVN_FAULT_ENC
    return [g_q3 commandBufferWithDescriptor:d];
}
// DM_NVN_FAULT_ENC: one debug signpost on the encoder (recorded with the encode thread on: RO_SIGNPOST)
static inline void fault_enc_mark(id en, NSString *s) { if (fault_enc_on() && en && s) [(id<MTLCommandEncoder>)en insertDebugSignpost:s]; }
static void fault_enc_pass(id en, id d_) {
    if (!fault_enc_on()) return;
    MTLRenderPassDescriptor *d = d_; id<MTLTexture> t = d.colorAttachments[0].texture, z = d.depthAttachment.texture; if (!t) t = z;
    fault_enc_mark(en, [NSString stringWithFormat:@"pass frame %llu target %lux%lu format %lu%s", (unsigned long long)atomic_load_explicit(&g_cur_frame, memory_order_relaxed),
                        (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.pixelFormat, z ? " +depth" : ""]);
}
static void m3_commit(id<MTLCommandBuffer> cb, NSArray *fb, id<MTLSharedEvent> ev, uint64_t v) {
    if (!gpu_go()) return;   // GPU 安全停后不交（反馈处理也不挂：不会再有回调）
    for (fb_fn h in fb) [cb addCompletedHandler:^(id<MTLCommandBuffer> c) { h((id)c); }];
    if (ev) [cb encodeSignalEvent:ev value:v];
    [cb commit];
}
// 旧队列上「交了就等完」的几处（回读 / 截图 / 帧录放）：安全停后不交也不等（没交的命令缓冲 waitUntilCompleted 永远不返回），返回 0，调用方按没拿到结果处理
static int cb_run(id<MTLCommandBuffer> cb) { if (!gpu_go()) return 0; [cb commit]; [cb waitUntilCompleted]; return 1; }
static int cb_put(id<MTLCommandBuffer> cb) { if (!gpu_go()) return 0; [cb commit]; return 1; }
// Metal 3 encoders (#278 D3-2): the main command buffer's draw passes, compute and copy encoders are the old ones (MTLRenderCommandEncoder / MTLComputeCommandEncoder /
// MTLBlitCommandEncoder, whose state setters have the Metal 4 selectors), ordered by g_fence3 (m3_wait, m4_end). Argument binding is D3-3 (#279):
// enc_r_table / enc_c_table note each stage's DmTable3 and every draw and dispatch hands its slots to the encoder first (m3_bind_draw / m3_bind_dispatch)
// Metal 3: GPU address → buffer and offset. Old encoders take a buffer where Metal 4 takes a GPU address (index and indirect buffers here; vertex and constant buffers in D3-3).
// Every buffer the GPU reaches by address is in the residency set, so res_add / res_remove keep a table of them sorted by GPU address (under g_res_mu). The residency set holds each
// buffer until res_remove, so the table holds them unretained
typedef struct { uint64_t lo, hi; __unsafe_unretained id<MTLBuffer> b; } m3_span;
static m3_span *g_m3_buf; static int g_m3_nbuf, g_m3_cap;
static int m3_buf_find(uint64_t a) { int lo = 0, hi = g_m3_nbuf - 1, hit = -1; while (lo <= hi) { int m = (lo + hi) / 2; if (g_m3_buf[m].lo <= a) { hit = m; lo = m + 1; } else hi = m - 1; } return hit; }   // the last one starting at or before a
static void m3_buf_add(id<MTLBuffer> b) {
    uint64_t lo = b.gpuAddress; int i = m3_buf_find(lo) + 1;
    if (g_m3_nbuf == g_m3_cap) { int c = g_m3_cap ? g_m3_cap * 2 : 1024; if (!GROW(g_m3_buf, (size_t)c * sizeof *g_m3_buf, "metal3 buffer table")) return; g_m3_cap = c; }
    memmove(g_m3_buf + i + 1, g_m3_buf + i, (size_t)(g_m3_nbuf - i) * sizeof *g_m3_buf);
    g_m3_buf[i] = (m3_span){lo, lo + b.length, b}; g_m3_nbuf++;
}
static void m3_buf_del(id<MTLBuffer> b) {
    int i = m3_buf_find(b.gpuAddress); while (i >= 0 && g_m3_buf[i].b != b) i--;   // spans of no length may share a start
    if (i < 0) return;
    memmove(g_m3_buf + i, g_m3_buf + i + 1, (size_t)(g_m3_nbuf - i - 1) * sizeof *g_m3_buf); g_m3_nbuf--;
}
static int m3_buf_at(uint64_t gpu, id<MTLBuffer> __strong *buf, NSUInteger *off) {   // the interface agreed in #279; 0 = in no resident buffer (reported red)
    pthread_mutex_lock(&g_res_mu);
    int i = m3_buf_find(gpu); id<MTLBuffer> b = i >= 0 && gpu < g_m3_buf[i].hi ? g_m3_buf[i].b : nil; if (b) *off = (NSUInteger)(gpu - g_m3_buf[i].lo);
    pthread_mutex_unlock(&g_res_mu);
    if (!b) { static _Atomic int n; int k = atomic_fetch_add(&n, 1); if (k % 600 == 0) MLOG("【红】 Metal 3: GPU address %#llx is in no resident buffer; what uses it is skipped (%d so far)", (unsigned long long)gpu, k + 1); }
    *buf = b; return b != nil;
}
int mtl_m3_buf(uint64_t gpu, void **buf, uint64_t *off) { NSUInteger o = 0; id<MTLBuffer> b; int ok = m3_buf_at(gpu, &b, &o); *buf = (__bridge void *)b; *off = o; return ok; }   // for tests/t_nvn_m3.m
static NSHashTable *g_res_objects;
// Residency churn by call site (the power line every 300 frames, nvn_be_res_stats): each commit with changes is a kernel call whose cost grows with what was added or removed
enum { RS_SITES = 16 }; static struct { int line; uint64_t n, bytes; } g_rs_site[RS_SITES]; static uint64_t g_rs_rm, g_rs_commits, g_rs_commit_ns;
// S2Arm 11-15 (#1117: textures held only by the residency set grew by about 2 GB over 10,000 frames): each resource remembers the line that added it, so removals in the
//   window (g_rs_rmsite) and what is resident now (g_rs_live, kept across windows) are counted by that line too: a line whose resident count only grows adds without a removal
static struct { int line; uint64_t n; } g_rs_rmsite[RS_SITES]; static struct { int line; int64_t n, bytes; } g_rs_live[RS_SITES]; static char g_rs_line_key;
static void rs_live_bump(int line, int64_t n, int64_t bytes) {   // under g_res_mu
    int k = 0; while (k < RS_SITES - 1 && g_rs_live[k].line && g_rs_live[k].line != line) k++;
    g_rs_live[k].line = line; g_rs_live[k].n += n; g_rs_live[k].bytes += bytes;
}
#define res_add(r) res_add_at((r), __LINE__)
// 大贴图建立账（S2A_MEM_SPLIT=1，缺省关；11-05 时之笛第二十三版读档进场景：约 0.1 秒私有贴图 417 → 1708 MB，同期随包首传只有约 325 MB，要知道多出来的是哪些）：
//   进驻留集的私有贴图 ≥ 4 MB 各打一行（建它的源码行号定是哪条路：GPU 贴图 / 随包上传 / 升级 / 放宽 / 内部分辨率 / 临时图），带 Metal 侧尺寸、格式、级数、层数、用途与累计；
//   GPU 贴图另有 tex_big_note 一行补 NVN 侧描述（flags、池 flags、存储碰没碰过）。只按 ≥ 4 MB 打，前 400 行后按 2 的幂
static int big_tex_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("S2A_MEM_SPLIT"); on = e && *e && strcmp(e, "0"); } return on; }
static _Atomic uint64_t g_big_tex_n, g_big_tex_bytes;
static _Atomic uint64_t g_cur_frame;   // defined with the frame statistics below (tentative definition)
static void big_tex_res(id<MTLResource> r, int line) {
    if (![r conformsToProtocol:@protocol(MTLTexture)]) return;
    id<MTLTexture> t = (id<MTLTexture>)r; if (t.parentTexture || t.buffer || t.storageMode != MTLStorageModePrivate) return;
    uint64_t b = t.allocatedSize; if (b < (4u << 20)) return;
    uint64_t k = atomic_fetch_add(&g_big_tex_n, 1) + 1, tot = atomic_fetch_add(&g_big_tex_bytes, b) + b;
    if (k <= 400 || !(k & (k - 1))) MLOG("[大贴图] 第 %llu 张 源码行 %d：%lux%lux%lu 层 %lu 级 %lu 格式 %lu 类型 %lu 用途 %#lx 分配 %llu KB（累计 %llu MB，帧 %llu）", (unsigned long long)k, line,
        (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.depth, (unsigned long)t.arrayLength, (unsigned long)t.mipmapLevelCount, (unsigned long)t.pixelFormat, (unsigned long)t.textureType,
        (unsigned long)t.usage, (unsigned long long)(b >> 10), (unsigned long long)(tot >> 20), (unsigned long long)atomic_load(&g_cur_frame));
}
// 游戏线程上没有会清空的自动释放池（长寿命线程、没有 run loop），Metal / Foundation 内部把对象「强引用 + autorelease」一次（弱引用表查询 / 写入、
//   驻留集增删等）就永远放不掉。11-06 DOOM Eternal（c1106_rj13）：游戏释放的内存池 34 个 2720 MB 的零拷贝缓冲一直活着（「freed but alive」），
//   GPU 已分配 4645 MB；删池时线程自动释放池里挂着 36–56 个缓冲对象。池生命周期上这四处入口（建池 / 删池 / 进驻留集 / 出驻留集）各自带池：
//   改后同局 freed but alive 0、GPU 已分配 1920 MB
// Upload stall breakdown counters (nvn_be_stall_take, by g_up_total_ns)
enum { STL_CREATE, STL_TRACK, STL_HASH, STL_GENC, STL_CPU, STL_FLUSH, STL_WAIT, STL_RCOMMIT, STL_RADD, STL_GNEW, STL_FILL, STL_TEXMTL, STL_N };
static _Atomic uint64_t g_stl_ns[STL_N], g_stl_n[STL_N];
static inline uint64_t stl_now(void) { return clock_gettime_nsec_np(CLOCK_UPTIME_RAW); }
static inline void stl_add(int k, uint64_t t0) { atomic_fetch_add_explicit(&g_stl_ns[k], stl_now() - t0, memory_order_relaxed); atomic_fetch_add_explicit(&g_stl_n[k], 1, memory_order_relaxed); }
static _Atomic uint64_t g_stl_cpu_tex, g_stl_gpu_tex, g_stl_flush_tex;
static uint64_t g_stl_radd_b[3], g_stl_rc_b[3], g_stl_radd_n[3], g_stl_rm_n;   // residency bytes added (under g_res_mu) by kind: 0 texture, 1 private buffer (staging), 2 shared buffer (zero-copy sources, CPU staging); rc: of them, made resident by commits this frame   // pkg_upload_ textures that took the CPU path / the GPU path; up_flush calls that committed a batch
static char g_sp_heap_key;   // Metal 稀疏贴图 → 它的稀疏堆（nvn_sparse_tex.inc）
static char g_rh_owner_key;   // 回收堆里的贴图 → 它的堆主（NvRecycledHeap，rh_place）：驻留集收的是堆，贴图本身不进不出
static void res_add_at_body(id<MTLResource> r, int line);
static void res_add_at(id<MTLResource> r, int line) { uint64_t t0 = stl_now(); @autoreleasepool { res_add_at_body(r, line); } stl_add(STL_RADD, t0); }
static void res_add_at_body(id<MTLResource> r, int line) {
    if (!r) return;
    if (objc_getAssociatedObject(r, &g_rh_owner_key)) return;   // 回收堆里的贴图：堆从建起就常驻（rh_heap），到 rh_trim 才出
    pthread_mutex_lock(&g_res_mu);
    if (!g_res_objects) g_res_objects = [NSHashTable weakObjectsHashTable];
    if ([g_res_objects containsObject:r]) { pthread_mutex_unlock(&g_res_mu); return; }   // already resident (a shared texture resolved again): marking the set dirty would cost a commit that changes nothing
    if (big_tex_on()) big_tex_res(r, line);   // first time into the residency set only
    { int k = 0; while (k < RS_SITES - 1 && g_rs_site[k].line && g_rs_site[k].line != line) k++; g_rs_site[k].line = line; g_rs_site[k].n++; g_rs_site[k].bytes += r.allocatedSize; }
    rs_live_bump(line, 1, (int64_t)r.allocatedSize); objc_setAssociatedObject(r, &g_rs_line_key, @(line), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    { id<MTLHeap> sh = objc_getAssociatedObject(r, &g_sp_heap_key);   // Metal 稀疏贴图（nvn_sparse_tex.inc）：堆要驻留；老式稀疏堆的贴图驻留集不收（验证层断言），
      //   放置式（Metal 4）贴图本身另有元数据，也要驻留（只收堆时 Metal 4 队列上 GPU 缺页，本机实测）
      //   老式稀疏堆（Metal 3）连堆也不进驻留集：本机 NXGAL_BE=mtl3 实测，加进去后 [g_res commit] 在 AGX 驱动 enumResources 里 SIGSEGV
      if (sh && sh.type == MTLHeapTypePlacement) { res_q_put((id<MTLAllocation>)sh, 1); res_q_put((id<MTLAllocation>)r, 1); }
      else if (!sh) res_q_put((id<MTLAllocation>)r, 1); }
    { int k = [r conformsToProtocol:@protocol(MTLTexture)] ? 0 : r.storageMode == MTLStorageModePrivate ? 1 : 2; g_stl_radd_b[k] += r.allocatedSize; g_stl_radd_n[k]++; }
    [g_res_objects addObject:r];
    if (g_m3 && [r conformsToProtocol:@protocol(MTLBuffer)]) m3_buf_add((id<MTLBuffer>)r);
    g_res_dirty = 1;
    pthread_mutex_unlock(&g_res_mu);
}
static int pool_pin_retire(void *r);   // a pool table names it (pool_ent_put): it stays resident until no entry does
static void res_remove_body(id<MTLResource> r);
static void res_remove(id<MTLResource> r) { @autoreleasepool { res_remove_body(r); } }
static void res_remove_body(id<MTLResource> r) {
    if (!r) return;
    if (objc_getAssociatedObject(r, &g_rh_owner_key)) return;   // 同上：贴图放掉时堆回到等待表（rh_wait），仍常驻
    pthread_mutex_lock(&g_res_mu);
    if (![g_res_objects containsObject:r]) { pthread_mutex_unlock(&g_res_mu); return; }
    if (pool_pin_retire((__bridge void *)r)) { pthread_mutex_unlock(&g_res_mu); return; }
    { id<MTLHeap> sh = objc_getAssociatedObject(r, &g_sp_heap_key); if (sh && sh.type == MTLHeapTypePlacement) { res_q_put((id<MTLAllocation>)sh, 0); res_q_put((id<MTLAllocation>)r, 0); } else if (!sh) res_q_put((id<MTLAllocation>)r, 0); }
    [g_res_objects removeObject:r];
    if (g_m3 && [r conformsToProtocol:@protocol(MTLBuffer)]) m3_buf_del((id<MTLBuffer>)r);
    g_res_dirty = 1; g_rs_rm++; g_stl_rm_n++;
    { NSNumber *ln = objc_getAssociatedObject(r, &g_rs_line_key); int line = ln ? ln.intValue : 0;
      rs_live_bump(line, -1, -(int64_t)r.allocatedSize);
      int k = 0; while (k < RS_SITES - 1 && g_rs_rmsite[k].line && g_rs_rmsite[k].line != line) k++; g_rs_rmsite[k].line = line; g_rs_rmsite[k].n++; }
    pthread_mutex_unlock(&g_res_mu);
}
// ---------- 回收贴图堆（马车世界缺口 ③，照上游参考实现（MIT）707cac95 rh_*） ----------
// 动态分辨率每隔几帧就给渲染目标换个尺寸，每个新尺寸都是一张新 Metal 贴图、一次新分配、一次驻留集增删（上游读数：一场比赛每 300 帧上千张，驻留集加 5–6 GB）。
// Metal 的贴图布局与 NVN 不同，渲染目标不能像主机上那样共用池内存；能留下来的是宿主已经放掉的贴图的内存：GPU 专用池里、GPU 能画能写的贴图各建在自己的放置堆里（rh_texture），
// 贴图放掉时（延迟释放：用过它的提交都做完之后，defer_drain）堆进等待表、仍常驻，留给下一张装得下的贴图。新堆比第一张贴图大八分之一，等待的堆给不小于自己三分之二的贴图用
// （取装得下的最小那个），所以长大一档尺寸（2 MB 附近约 10%）的目标能放进它前一帧放掉的堆。新贴图照新分配一样填（tex_init_fill 或清零），读到什么与复用无关；
// 堆里那段内存只在旧贴图最后一次使用做完之前属于它，与 Metal 自己放掉再分出去的内存同理，不加别名冲刷。等了 RH_IDLE_NS 的堆、以及等待总量超过 RH_CAP 时最老的堆，
// 在提交开头出驻留集并放掉（rh_trim）。块压缩格式（游戏拷进来的素材，不带渲染目标用途）不进堆、照旧精确分配。只在 Metal 4：放置堆里的贴图没有自动冒险跟踪，Metal 3 路靠它。
// DM_NVN_RT_RECYCLE=0 回每张贴图自己一次分配（对照）
enum { RH_CAP = 256u << 20 }; static const uint64_t RH_IDLE_NS = 3000000000ull;
typedef struct { void *heap; uint64_t size, t; } rh_ent;   // heap：持有（CFBridgingRetain）；t：开始等待的时刻
static os_unfair_lock g_rh_lk = OS_UNFAIR_LOCK_INIT; static rh_ent *g_rh; static unsigned g_rh_n, g_rh_cap; static uint64_t g_rh_bytes;
static _Atomic uint64_t g_rh_made, g_rh_reused, g_rh_trimmed;   // 内存读数行
static int rh_on(void) { static int m = -1; if (m < 0) { const char *e = getenv("DM_NVN_RT_RECYCLE"); m = !(e && *e == '0'); } return m && !g_m3; }
static void rh_res(id<MTLHeap> h, int add) {   // 堆进 / 出驻留集（排队，下一次 res_commit 生效；出集的堆由队列持有到那次 commit）
    pthread_mutex_lock(&g_res_mu); res_q_put((id<MTLAllocation>)h, add); g_res_dirty = 1;
    if (add) { g_stl_radd_b[0] += h.size; g_stl_radd_n[0]++; } else g_stl_rm_n++;
    pthread_mutex_unlock(&g_res_mu);
}
// 贴图放掉了，它的堆等下一张装得下的贴图。在贴图最后一个引用消失处跑（defer_drain：提交线程或完成回调）
static void rh_wait(id<MTLHeap> heap) {
    if (!heap) return;
    rh_ent e = {(void *)CFBridgingRetain(heap), heap.size, clock_gettime_nsec_np(CLOCK_MONOTONIC)};
    os_unfair_lock_lock(&g_rh_lk);
    if (g_rh_n == g_rh_cap) { unsigned c = g_rh_cap ? 2 * g_rh_cap : 64; rh_ent *q = realloc(g_rh, c * sizeof *q); if (!q) { MLOG("FATAL recycled texture heaps: out of memory"); abort(); } g_rh = q; g_rh_cap = c; }
    g_rh[g_rh_n++] = e; g_rh_bytes += e.size;
    os_unfair_lock_unlock(&g_rh_lk);
}
@interface NvRecycledHeap : NSObject { @public id<MTLHeap> heap; } @end
@implementation NvRecycledHeap
- (void)dealloc { rh_wait(heap); }
@end
// 至少 size 字节的放置堆：等待表里不超过 1.5 倍的最小那个，没有就新建一个大八分之一的（建时进驻留集）。Metal 建不出来给 nil
static id<MTLHeap> rh_heap(uint64_t size, MTLStorageMode sm, MTLCPUCacheMode cm, MTLHazardTrackingMode hm, int *reused) {
    *reused = 0;
    if (!size) return nil;
    uint64_t top = size + size / 2; void *got = NULL;
    os_unfair_lock_lock(&g_rh_lk);
    unsigned best = g_rh_n;
    for (unsigned i = 0; i < g_rh_n; i++) {
        if (g_rh[i].size < size || g_rh[i].size > top || (best < g_rh_n && g_rh[i].size >= g_rh[best].size)) continue;
        id<MTLHeap> h = (__bridge id<MTLHeap>)g_rh[i].heap;
        if (h.storageMode != sm || h.cpuCacheMode != cm) continue;   // （放进去的贴图随堆的冒险跟踪：放置堆报不跟踪，与描述缺省一样）
        best = i;
    }
    if (best < g_rh_n) { got = g_rh[best].heap; g_rh_bytes -= g_rh[best].size; g_rh[best] = g_rh[--g_rh_n]; }
    os_unfair_lock_unlock(&g_rh_lk);
    if (got) { *reused = 1; atomic_fetch_add(&g_rh_reused, 1); return CFBridgingRelease(got); }
    MTLHeapDescriptor *hd = [MTLHeapDescriptor new]; hd.type = MTLHeapTypePlacement; hd.size = size + size / 8;
    hd.storageMode = sm; hd.cpuCacheMode = cm; hd.hazardTrackingMode = hm;
    id<MTLHeap> h = [g_dev newHeapWithDescriptor:hd];
    if (h) { atomic_fetch_add(&g_rh_made, 1); rh_res(h, 1); }
    return h;
}
// 这个描述的贴图放进回收内存（堆开头）。开关关 / 放不进去给 nil；从等待表取来的堆没用上就回去等，新建的没用上就出驻留集放掉
static id<MTLTexture> rh_place(MTLTextureDescriptor *d) {
    if (!rh_on() || d.storageMode != MTLStorageModePrivate || d.textureType == MTLTextureTypeTextureBuffer) return nil;
    MTLSizeAndAlign need = [g_dev heapTextureSizeAndAlignWithDescriptor:d];
    int reused = 0; id<MTLHeap> heap = rh_heap(need.size, d.storageMode, d.cpuCacheMode, d.hazardTrackingMode, &reused);
    id<MTLTexture> mt = heap ? [heap newTextureWithDescriptor:d offset:0] : nil;
    if (!mt) { if (heap) { if (reused) rh_wait(heap); else rh_res(heap, 0); } return nil; }
    NvRecycledHeap *owner = [NvRecycledHeap new]; owner->heap = heap;
    objc_setAssociatedObject(mt, &g_rh_owner_key, owner, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    return mt;
}
// GPU 专用池里、GPU 能画能写的贴图进回收内存：CPU 从不写它的存储，新贴图照新分配一样由宿主手里的内容填（tex_init_fill）或清零。NVN 不给渲染目标标志位
// （一款赛车游戏换尺寸的目标有的不带 COMPRESSIBLE），所以按宿主给它的 Metal 用途判：块压缩格式不带渲染目标用途，照旧自己精确分配
static id<MTLTexture> rh_texture(const tex_t *t, MTLTextureDescriptor *d) {
    if (!t->pool || !(t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS) || !(d.usage & (MTLTextureUsageRenderTarget | MTLTextureUsageShaderWrite))
        || (t->d.flags & (NVN_TEXTURE_FLAGS_DISPLAY | NVN_TEXTURE_FLAGS_VIDEO_DECODE | NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_SPARSE | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET))) return nil;
    return rh_place(d);
}
// 提交开头：等了 RH_IDLE_NS 的堆、等待总量超过 RH_CAP 时最老的堆，出驻留集并放掉（一次至多 64 个）
static void rh_trim(void) {
    if (!g_rh_n) return;
    uint64_t now = clock_gettime_nsec_np(CLOCK_MONOTONIC); void *drop[64]; unsigned nd = 0;
    os_unfair_lock_lock(&g_rh_lk);
    while (g_rh_n && nd < 64) {
        unsigned old = 0; for (unsigned i = 1; i < g_rh_n; i++) if (g_rh[i].t < g_rh[old].t) old = i;
        if (now - g_rh[old].t < RH_IDLE_NS && g_rh_bytes <= RH_CAP) break;
        drop[nd++] = g_rh[old].heap; g_rh_bytes -= g_rh[old].size; g_rh[old] = g_rh[--g_rh_n];
    }
    os_unfair_lock_unlock(&g_rh_lk);
    for (unsigned i = 0; i < nd; i++) { id<MTLHeap> h = CFBridgingRelease(drop[i]); rh_res(h, 0); }
    if (nd) atomic_fetch_add(&g_rh_trimmed, nd);
}
// ---------- Metal 3 argument tables (#279 D3-3) ----------
// Metal 4 binds a buffer by its GPU address (MTL4ArgumentTable setAddress) and a texture / sampler by its resource ID; the old encoders take the objects (setVertexBuffer:offset:atIndex: …).
// Addresses go back to buffer + offset through m3_buf_at; helper passes hold their objects and bind them directly (tab_buf / tab_tex / tab_samp). DmTable3 stands in for
// MTL4ArgumentTable on this path: it keeps the slots and, per stage, which changed since they last went to an encoder (m3_table_apply)
enum { M3T_BUF = 31, M3T_TEX = 4, M3T_SMP = 4 };
@interface DmTable3 : NSObject { @public __strong id<MTLBuffer> buf[M3T_BUF]; NSUInteger off[M3T_BUF]; __strong id<MTLTexture> tex[M3T_TEX]; __strong id<MTLSamplerState> smp[M3T_SMP];
    uint32_t dbuf[5], dtex[5], dsmp[5]; } @end   // per stage (0 vertex, 1 fragment, 2 compute, 3 object, 4 mesh: a task / mesh draw, nvn_geometry.inc mtk_encode): slots changed since they last went to that stage
@implementation DmTable3 @end
// Per stage, the encoder and the table whose slots went to it last (m3_table_apply). Held strongly: an ended encoder that is freed can hand its address to the next one, which
// then looked like the same encoder and got only the changed slots (Diablo II, forced Metal 3: the widen push at slot 13, set once and skipped by the vbuf cache, was never bound on the
// new encoder; the scene draws read nothing and the frame stayed black)
static __strong id g_m3_sent_enc[5], g_m3_sent_tab[5];
// A table on either path: Metal 4 makes the MTL4ArgumentTable, Metal 3 a DmTable3. nb / nt / ns: buffer / texture / sampler slots
static id tab_new(NSUInteger nb, NSUInteger nt, NSUInteger ns, NSError **e) {
    if (g_m3) { if (nb > M3T_BUF || nt > M3T_TEX || ns > M3T_SMP) { if (e) *e = [NSError errorWithDomain:@"DmTable3" code:1 userInfo:@{NSLocalizedDescriptionKey: @"too many slots"}]; return nil; } return [DmTable3 new]; }
    MTL4ArgumentTableDescriptor *d = [MTL4ArgumentTableDescriptor new]; d.maxBufferBindCount = nb; d.maxTextureBindCount = nt; d.maxSamplerStateBindCount = ns;
    return [g_dev newArgumentTableWithDescriptor:d error:e];
}
static inline void tab_buf(id t, id<MTLBuffer> b, NSUInteger off, NSUInteger i) {
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setAddress:b.gpuAddress + off atIndex:i]; return; }
    DmTable3 *x = t; if (i >= M3T_BUF) return; x->buf[i] = b; x->off[i] = off; for (int k = 0; k < 5; k++) x->dbuf[k] |= 1u << i;
}
static inline void tab_addr(id t, uint64_t gpu, NSUInteger i) {   // an address only (the main path's bindings): Metal 3 looks the buffer up
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setAddress:gpu atIndex:i]; return; }
    id<MTLBuffer> b; NSUInteger o = 0;
    if (!m3_buf_at(gpu, &b, &o)) { DmTable3 *x = t; if (i < M3T_BUF) { x->buf[i] = nil; for (int k = 0; k < 5; k++) x->dbuf[k] &= ~(1u << i); } return; }   // reported red there; the slot is left unbound
    tab_buf(t, b, o, i);
}
static inline void tab_tex(id t, id<MTLTexture> x, NSUInteger i) {
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setTexture:x.gpuResourceID atIndex:i]; return; }
    DmTable3 *y = t; if (i >= M3T_TEX) return; y->tex[i] = x; for (int k = 0; k < 5; k++) y->dtex[k] |= 1u << i;
}
static inline void tab_samp(id t, id<MTLSamplerState> s, NSUInteger i) {
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setSamplerState:s.gpuResourceID atIndex:i]; return; }
    DmTable3 *y = t; if (i >= M3T_SMP) return; y->smp[i] = s; for (int k = 0; k < 5; k++) y->dsmp[k] |= 1u << i;
}
// Metal 3 (the seam with #278: m3_bind_draw / m3_bind_dispatch call it before each draw / dispatch): the slots of table t that changed since they last went to this stage go to the encoder,
// all of them when this stage last got another encoder (a new one starts with nothing bound) or another table (a helper pass's table took over slots of this one on the same encoder,
// which Metal 4's setArgumentTable undoes as a whole). stage: 0 vertex, 1 fragment (render encoder), 2 compute, 3 object, 4 mesh (render encoder, a task / mesh draw)
static void m3_table_apply(id enc, int stage, id tab) {
    DmTable3 *t = tab; if (!t) return;
    int all = g_m3_sent_enc[stage] != enc || g_m3_sent_tab[stage] != t; g_m3_sent_enc[stage] = enc; g_m3_sent_tab[stage] = t;
    uint32_t mb = all ? ~0u : t->dbuf[stage], mt = all ? ~0u : t->dtex[stage], ms = all ? ~0u : t->dsmp[stage];
    for (NSUInteger i = 0; i < M3T_BUF; i++) if ((mb >> i & 1) && t->buf[i]) {
        if (stage == 0) [(id<MTLRenderCommandEncoder>)enc setVertexBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else if (stage == 1) [(id<MTLRenderCommandEncoder>)enc setFragmentBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else if (stage == 3) [(id<MTLRenderCommandEncoder>)enc setObjectBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else if (stage == 4) [(id<MTLRenderCommandEncoder>)enc setMeshBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else [(id<MTLComputeCommandEncoder>)enc setBuffer:t->buf[i] offset:t->off[i] atIndex:i];
    }
    for (NSUInteger i = 0; i < M3T_TEX; i++) if ((mt >> i & 1) && t->tex[i]) {
        if (stage == 0) [(id<MTLRenderCommandEncoder>)enc setVertexTexture:t->tex[i] atIndex:i];
        else if (stage == 1) [(id<MTLRenderCommandEncoder>)enc setFragmentTexture:t->tex[i] atIndex:i];
        else if (stage == 3) [(id<MTLRenderCommandEncoder>)enc setObjectTexture:t->tex[i] atIndex:i];
        else if (stage == 4) [(id<MTLRenderCommandEncoder>)enc setMeshTexture:t->tex[i] atIndex:i];
        else [(id<MTLComputeCommandEncoder>)enc setTexture:t->tex[i] atIndex:i];
    }
    for (NSUInteger i = 0; i < M3T_SMP; i++) if ((ms >> i & 1) && t->smp[i]) {
        if (stage == 0) [(id<MTLRenderCommandEncoder>)enc setVertexSamplerState:t->smp[i] atIndex:i];
        else if (stage == 1) [(id<MTLRenderCommandEncoder>)enc setFragmentSamplerState:t->smp[i] atIndex:i];
        else if (stage == 3) [(id<MTLRenderCommandEncoder>)enc setObjectSamplerState:t->smp[i] atIndex:i];
        else if (stage == 4) [(id<MTLRenderCommandEncoder>)enc setMeshSamplerState:t->smp[i] atIndex:i];
        else [(id<MTLComputeCommandEncoder>)enc setSamplerState:t->smp[i] atIndex:i];
    }
    t->dbuf[stage] = t->dtex[stage] = t->dsmp[stage] = 0;
}
// DM_RES_CHECK=1 (diagnostic): if textures / buffers the shader accesses through the argument block are not in the residency set, print the first 40 (textures are attributed to the actual allocation via parent texture / underlying buffer)
static int g_res_check_on;
static void res_check(id r, const char *what, int reg) {
    static int nbad;
    if (!g_res_check_on || !r || nbad >= 40) return;
    int is_tex = [r conformsToProtocol:@protocol(MTLTexture)], is_buf = [r conformsToProtocol:@protocol(MTLBuffer)];
    if (!is_tex && !is_buf) return;   // Samplers etc. are not allocations
    id<MTLResource> a = r; int hops = 0;
    if (is_tex) { id<MTLTexture> t = (id<MTLTexture>)a; while (t.parentTexture) { t = t.parentTexture; hops++; } a = t.buffer ? (id<MTLResource>)t.buffer : (id<MTLResource>)t; }
    pthread_mutex_lock(&g_res_mu); int ok = [g_res_objects containsObject:a]; pthread_mutex_unlock(&g_res_mu);
    if (!ok) { nbad++; id<MTLTexture> t = is_tex ? (id<MTLTexture>)r : nil;
        MLOG("【红】 missing residency #%d: %s slot %d %s %p (parent chain %d deep) allocated %lu B storage mode %lu%s", nbad, what, reg, is_tex ? "texture" : "buffer", (__bridge void *)a, hops, (unsigned long)a.allocatedSize, (unsigned long)a.storageMode,
             t ? [NSString stringWithFormat:@" format %lu %lux%lu type %lu usage %#lx", (unsigned long)t.pixelFormat, (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.textureType, (unsigned long)t.usage].UTF8String : ""); }
}
// 应用并提交调用之前的全部改动；被别的线程那次 commit 取走的改动，返回时同样已在集里（那次 commit 持着 g_res_commit_mu 直到做完）。移除的对象活到移出集的那次 commit
static void res_commit(void) { @autoreleasepool {
    pthread_mutex_lock(&g_res_commit_mu);
    pthread_mutex_lock(&g_res_mu);
    res_op *q = g_res_q; size_t nq = g_res_qn; g_res_q = NULL; g_res_qn = g_res_qcap = 0; int dirty = g_res_dirty; g_res_dirty = 0;
    pthread_mutex_unlock(&g_res_mu);
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    if (dirty || nq) { for (size_t i = 0; i < nq; i++) { if (q[i].add) [g_res addAllocation:(__bridge id<MTLAllocation>)q[i].o]; else [g_res removeAllocation:(__bridge id<MTLAllocation>)q[i].o]; } [g_res commit]; }
    pthread_mutex_lock(&g_res_mu);
    if (dirty || nq) { g_rs_commits++;
        // DM_NVN_RC_LOG=1 (diagnostic): every commit of 1 ms or more, with what changed since the last commit (objects / MB added by kind, objects removed); at most 3000 lines
        { static int lg = -1; static int nl; if (lg < 0) lg = getenv("DM_NVN_RC_LOG") != NULL; uint64_t dt = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0;
          if (lg && dt >= 1000000 && nl++ < 3000) MLOG("[rc] commit %.2f ms frame %llu: added tex %llu / %.1f MB, private %llu / %.1f MB, shared %llu / %.1f MB; removed %llu; set %lu objects", dt / 1e6, (unsigned long long)atomic_load(&g_cur_frame),
              (unsigned long long)g_stl_radd_n[0], g_stl_radd_b[0] / 1048576.0, (unsigned long long)g_stl_radd_n[1], g_stl_radd_b[1] / 1048576.0, (unsigned long long)g_stl_radd_n[2], g_stl_radd_b[2] / 1048576.0, (unsigned long long)g_stl_rm_n, (unsigned long)g_res_objects.count); }
        for (int k = 0; k < 3; k++) { g_stl_rc_b[k] += g_stl_radd_b[k]; g_stl_radd_b[k] = 0; g_stl_radd_n[k] = 0; } g_stl_rm_n = 0; g_rs_commit_ns += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0; stl_add(STL_RCOMMIT, t0); }
    pthread_mutex_unlock(&g_res_mu);
    pthread_mutex_unlock(&g_res_commit_mu);
    for (size_t i = 0; i < nq; i++) CFRelease(q[i].o);
    free(q);
} }
// GPU 内存用满安全停（mtl_gpu_halt）：驻留集整个清空并提交。安全停之后 gpu_go 一律不放行，不会再有命令缓冲用到这些资源
static void res_drop_all(void) { @autoreleasepool {
    if (!g_res) { MLOG("【红】 GPU 内存用满安全停：没有驻留集（Metal 3 后端），无可放"); return; }
    pthread_mutex_lock(&g_res_commit_mu);   // 同 res_commit 的加锁顺序：先提交锁、再记账锁
    pthread_mutex_lock(&g_res_mu);
    for (size_t i = 0; i < g_res_qn; i++) CFRelease(g_res_q[i].o);   // 还没提交的增删作废
    free(g_res_q); g_res_q = NULL; g_res_qn = g_res_qcap = 0; g_res_dirty = 0;
    [g_res_objects removeAllObjects];   // 记账与驻留集一致：之后再 res_add 同一个对象照常进
    pthread_mutex_unlock(&g_res_mu);
    uint64_t b = g_res.allocatedSize; NSUInteger n = g_res.allocationCount;
    [g_res removeAllAllocations]; [g_res commit];
    pthread_mutex_unlock(&g_res_commit_mu);
    MLOG("【红】 GPU 内存用满安全停：驻留集清空，放掉 %lu 个对象、%llu MB", (unsigned long)n, (unsigned long long)(b >> 20));
} }
// Since the last call: residency commits (count, time), additions by source line (count, MB; the four largest by bytes) and removals
void nvn_be_res_stats(char *out, size_t n) {
    pthread_mutex_lock(&g_res_mu);
    uint64_t tn = 0, tb = 0; for (int k = 0; k < RS_SITES; k++) { tn += g_rs_site[k].n; tb += g_rs_site[k].bytes; }
    size_t o = snprintf(out, n, "commits %llu / %.1f ms, added %llu, %.0f MB (", (unsigned long long)g_rs_commits, g_rs_commit_ns / 1e6, (unsigned long long)tn, tb / 1048576.0);
    for (int i = 0; i < 4 && o < n; i++) { int best = -1; for (int k = 0; k < RS_SITES; k++) if (g_rs_site[k].n && (best < 0 || g_rs_site[k].bytes > g_rs_site[best].bytes)) best = k;
        if (best < 0) break; o += snprintf(out + o, n - o, "%sline %d: %llu, %.0f MB", i ? ", " : "", g_rs_site[best].line, (unsigned long long)g_rs_site[best].n, g_rs_site[best].bytes / 1048576.0); g_rs_site[best].n = 0; }
    if (o < n) o += snprintf(out + o, n - o, "), removed %llu (", (unsigned long long)g_rs_rm);
    for (int i = 0; i < 4 && o < n; i++) { int best = -1; for (int k = 0; k < RS_SITES; k++) if (g_rs_rmsite[k].n && (best < 0 || g_rs_rmsite[k].n > g_rs_rmsite[best].n)) best = k;   // added by which line
        if (best < 0) break; o += snprintf(out + o, n - o, "%sline %d: %llu", i ? ", " : "", g_rs_rmsite[best].line, (unsigned long long)g_rs_rmsite[best].n); g_rs_rmsite[best].n = 0; }
    if (o < n) o += snprintf(out + o, n - o, "), resident by adding line (");
    { uint8_t used[RS_SITES] = {0};   // not reset: what is resident now, the largest four by bytes
      for (int i = 0; i < 4 && o < n; i++) { int best = -1; for (int k = 0; k < RS_SITES; k++) if (!used[k] && g_rs_live[k].line && g_rs_live[k].n > 0 && (best < 0 || g_rs_live[k].bytes > g_rs_live[best].bytes)) best = k;
          if (best < 0) break; used[best] = 1; o += snprintf(out + o, n - o, "%sline %d: %lld, %.0f MB", i ? ", " : "", g_rs_live[best].line, (long long)g_rs_live[best].n, g_rs_live[best].bytes / 1048576.0); } }
    // 同样是当前驻留，按对象个数取最多的四个来源：长局里 64 KB 的小共享缓冲一分钟涨约 25 个（404 → 855），按字节排进不了上面的前四，看不出是哪一处加的
    if (o < n) o += snprintf(out + o, n - o, "), most objects by adding line (");
    { uint8_t used[RS_SITES] = {0};
      for (int i = 0; i < 4 && o < n; i++) { int best = -1; for (int k = 0; k < RS_SITES; k++) if (!used[k] && g_rs_live[k].line && g_rs_live[k].n > 0 && (best < 0 || g_rs_live[k].n > g_rs_live[best].n)) best = k;
          if (best < 0) break; used[best] = 1; o += snprintf(out + o, n - o, "%sline %d: %lld, %.1f MB", i ? ", " : "", g_rs_live[best].line, (long long)g_rs_live[best].n, g_rs_live[best].bytes / 1048576.0); } }
    if (o < n) snprintf(out + o, n - o, ")");
    memset(g_rs_site, 0, sizeof g_rs_site); memset(g_rs_rmsite, 0, sizeof g_rs_rmsite); g_rs_rm = g_rs_commits = g_rs_commit_ns = 0;
    pthread_mutex_unlock(&g_res_mu);
}

static char g_atomic_root_key;   // associated object on an RGBA8 view: the R32 integer storage it was made over for image atomics (tex_upgrade)
static char g_twin_view_key;     // associated object on an sRGB / linear view tex_mtl_ / tex_upgrade made of an NVN texture's twin (srgb_twin_mark): only those are judged stale or remade.
                                 //   A view's shape alone is not ours: an external texture (mtl_ext_tex, e.g. a BGRA8_sRGB view of a linear swapchain image) has the same shape and no NVN twin
@interface NvDeferredRelease : NSObject { @public id object; uint64_t fence; int keep_resident; } @end
@implementation NvDeferredRelease @end
static NSMutableArray<NvDeferredRelease *> *g_deferred;
static pthread_mutex_t g_deferred_mu = PTHREAD_MUTEX_INITIALIZER;
// Deferred release has two meanings that must be kept apart (the root of the GPU memory fault on the first frame on entering Travincal):
//   defer_obj_release = this object is retired: drop the reference after the submissions that used it complete, and remove it from the residency set;
//   defer_obj_unref   = only the reference I hold is no longer wanted, the object itself may still be in use (the view cache of a texture ID may hold the base texture itself): only drop the reference, leave the residency set alone.
// Previously only the former existed: when the view cache was invalidated, a texture that 'is still the current storage of some serial' was also removed from the residency set. Invalidation used to happen only when the base texture was really replaced, so it was never hit;
// after the transparency chain's in-place composite swapped the storage of two textures, each of the two live textures was removed once this way, and afterwards they are used as attachments and sampled every frame as usual - the GPU accesses non-resident memory.
static void defer_obj_release_ex(id obj, int keep_resident) {
    if (!obj) return;
    NvDeferredRelease *d = [NvDeferredRelease new]; d->object = obj; d->fence = g_fence + 1; d->keep_resident = keep_resident;
    pthread_mutex_lock(&g_deferred_mu);
    if (!g_deferred) g_deferred = [NSMutableArray array];
    [g_deferred addObject:d];
    pthread_mutex_unlock(&g_deferred_mu);
}
static void defer_obj_release(id obj) { defer_obj_release_ex(obj, 0); }
static void defer_obj_unref(id obj) { defer_obj_release_ex(obj, 1); }
// Its own autorelease pool: nvn_be_sub_begin drains before it pushes the submission's pool, on the guest submit thread, whose implicit pool is never drained. The weak-table lookups and the residency-set removal
// autorelease the retired object, so whatever that thread drained (instead of the completion handler, which wins the race only when the CPU is idle) stayed alive for good: in Metroid Dread every
// re-upload of its map mask kept the old texture and its 32 MB upload staging block, and GPU memory grew by several GB within minutes under CPU load.
static void defer_drain(void) { @autoreleasepool {
    NSMutableArray<NvDeferredRelease *> *ready = [NSMutableArray array];
    pthread_mutex_lock(&g_deferred_mu);
    // One pass that keeps the rest: removing each from the middle moved the whole tail, quadratic in the queue, which a scene load fills (upstream reference implementation, MIT: minutes in memmove)
    uint64_t done = g_done;
    for (NvDeferredRelease *d in g_deferred) if (d->fence <= done) [ready addObject:d];
    if (ready.count) { NSMutableArray<NvDeferredRelease *> *keep = [NSMutableArray arrayWithCapacity:g_deferred.count - ready.count]; for (NvDeferredRelease *d in g_deferred) if (d->fence > done) [keep addObject:d]; g_deferred = keep; }
    pthread_mutex_unlock(&g_deferred_mu);
    for (NvDeferredRelease *d in ready) {
        id obj = d->object;
        if (!d->keep_resident && [obj conformsToProtocol:@protocol(MTLResource)]) {
            pthread_mutex_lock(&g_res_mu);
            int registered = [g_res_objects containsObject:obj];
            pthread_mutex_unlock(&g_res_mu);
            if (registered) res_remove((id<MTLResource>)obj);
            id root = objc_getAssociatedObject(obj, &g_atomic_root_key);   // an RGBA8 view of integer storage made for image atomics (tex_upgrade): the storage is what is resident
            if (root) res_remove((id<MTLResource>)root);
        }
        d->object = nil;
    }
} }

static pthread_mutex_t g_bf_want_mu = PTHREAD_MUTEX_INITIALIZER;
static char **g_bf_want_keys; static size_t g_bf_want_n, g_bf_want_cap; static int g_bf_want_loaded;
void bf_want_note(const char *key) {
    const char *path = getenv("DM_NVN_BF_WANT");
    if (!path || !key || strlen(key) != 16) return;
    for (int i = 0; i < 16; i++) if (!((key[i] >= '0' && key[i] <= '9') || (key[i] >= 'a' && key[i] <= 'f') || (key[i] >= 'A' && key[i] <= 'F'))) return;
    pthread_mutex_lock(&g_bf_want_mu);
    if (!g_bf_want_loaded) {
        FILE *f = fopen(path, "r"); char line[64];
        if (f) { while (fgets(line, sizeof line, f)) { char *e = strpbrk(line, "\r\n"); if (e) *e = 0; if (strlen(line) != 16) continue;
                if (g_bf_want_n == g_bf_want_cap) { size_t c = g_bf_want_cap ? g_bf_want_cap * 2 : 64; if (!GROW(g_bf_want_keys, c * sizeof *g_bf_want_keys, "bf want list")) break; g_bf_want_cap = c; }
                g_bf_want_keys[g_bf_want_n++] = strdup(line); } fclose(f); }
        g_bf_want_loaded = 1;
    }
    for (size_t i = 0; i < g_bf_want_n; i++) if (!strcmp(g_bf_want_keys[i], key)) { pthread_mutex_unlock(&g_bf_want_mu); return; }
    if (g_bf_want_n == g_bf_want_cap) { size_t c = g_bf_want_cap ? g_bf_want_cap * 2 : 64; if (!GROW(g_bf_want_keys, c * sizeof *g_bf_want_keys, "bf want list")) { pthread_mutex_unlock(&g_bf_want_mu); return; } g_bf_want_cap = c; }
    g_bf_want_keys[g_bf_want_n++] = strdup(key);
    FILE *f = fopen(path, "a"); if (f) { fprintf(f, "%s\n", key); fclose(f); }
    pthread_mutex_unlock(&g_bf_want_mu);
}

// ---------- Memory pools ----------
typedef struct { uintptr_t lo, hi; uintptr_t base; __unsafe_unretained id<MTLBuffer> buf; uint64_t gpu; const void *key; int res; uintptr_t host;
    int reg, gm, gslot, gout; uint64_t gseen, gfence; uint8_t alias, vpf; uint64_t dead; uint64_t rseen; int rout; } pool_ent;   // dead：游戏已释放，等到第 dead 次提交开始才真正注销（pool_reap；0 = 活着）   // res: already in the residency set (on demand, see pool_res); host: the CPU bytes of the pool (pool_host). The raw pool table's on-demand residency (gmem_scan):
    // reg: an address of it went to the GPU through a binding (pool_res): resident for good; gm: resident because a raw access reached it (1; 2 = for good, no access bit was free);
    // gslot: its bit in the access bitmap + 1 (0: none); gout: times it was taken out for not being reached; gseen: the frame its bit was last seen; gfence: the submission after which the last taking out lets it go
    // rseen: the frame an address of it last went out through pool_res; rout: times it was taken out of the residency set for not being addressed for long (pool_age)
static pool_ent *g_pools; static int g_npool, g_cap;
static int g_pidx_ok, g_plast = -1;   // whether the address→pool index is valid, the last hit (pool_find)
static int *g_pidx; static int g_pidx_cap;   // pool indices sorted by start address (pool_find)
static int pidx_cmp(const void *a, const void *b) { uintptr_t x = g_pools[*(const int *)a].lo, y = g_pools[*(const int *)b].lo; return x < y ? -1 : x > y; }
// The index follows one registration or one removal in place instead of being re-sorted whole at the next lookup: a game that keeps some 1,760 pools and makes or frees one or two
//   a frame re-sorted all of them each time (qsort under pool_find: 48 of the submit thread's 1,452 samples in 10 s). Both leave the index invalid (the next lookup re-sorts) when
//   it is not current or the entry is not where the order says. Caller holds g_mu
static int pidx_pos(uintptr_t lo, int n) { int a = 0, b = n; while (a < b) { int m = (a + b) / 2; if (g_pools[g_pidx[m]].lo < lo) a = m + 1; else b = m; } return a; }   // the first of n entries starting at lo or after
static int pidx_of(int pool, int n) { int p = pidx_pos(g_pools[pool].lo, n); while (p < n && g_pidx[p] != pool && g_pools[g_pidx[p]].lo == g_pools[pool].lo) p++; return p < n && g_pidx[p] == pool ? p : -1; }
static void pidx_added(void) {   // g_pools[g_npool - 1] is the new pool
    if (!g_pidx_ok) return;
    if (g_pidx_cap < g_npool) { g_pidx_ok = 0; return; }
    int n = g_npool - 1, p = pidx_pos(g_pools[n].lo, n);
    memmove(g_pidx + p + 1, g_pidx + p, (size_t)(n - p) * sizeof *g_pidx); g_pidx[p] = n;
}
static int g_nbig; static void big_index_move(int gone, int from);   // 大池（下面）：池表挪条目时块表跟着改
static void pidx_removing(int i) {   // before g_pools[i] = g_pools[--g_npool]: i's entry goes, the last pool's entry is renamed to i
    if (g_nbig) big_index_move(i, g_npool - 1);
    if (!g_pidx_ok) return;
    int n = g_npool, last = n - 1, p = pidx_of(i, n);
    if (p < 0) { g_pidx_ok = 0; return; }
    memmove(g_pidx + p, g_pidx + p + 1, (size_t)(n - 1 - p) * sizeof *g_pidx);
    if (i != last) { int q = pidx_of(last, n - 1); if (q < 0) { g_pidx_ok = 0; return; } g_pidx[q] = i; }
}
// 大内存池按块用到才包（马车世界缺口 ②，照上游参考实现（MIT）nvn_mtl.m big_pool / big_lookup）：Metal 把驻留集里的零拷贝缓冲整块锁页，一个缓冲包住大池就把整池锁住，
//   不管 GPU 读了多少。上游读数：一款大型赛车游戏 2,427 MB 的图形池，首场比赛 GPU 只碰过 1,111 MB；16 GB Mac 上驱动一半时间在锁页 / 解锁（6 秒里 3.2 秒），隔几帧就 100 ms 以上。
//   BIG_MIN 以上的池（近区、不是远端影子）不建自己的缓冲：查找按地址所在的 BIG_S 步长现建一块零拷贝缓冲，覆盖到这次要读的末尾（向上取步长再多一个步长），只有查到的才锁页。
//   块之间重叠，GPU 地址跨块不连续，所以查找要说读多远；不知道（长度 1：间接绘制的索引缓冲、原始存储地址）给 BIG_UNKNOWN。原始全局内存表（着色器自己查池表）要整池：big_full（gmem_map）。
//   只为 CPU 读（addr_cpu）或只问在不在（pool_known）的查询不建块：块是 GPU 用的
enum { BIG_MIN = 512u << 20, BIG_S = 16u << 20, BIG_UNKNOWN = 64u << 20, BIG_MAX = 32 };
typedef struct { uintptr_t lo, hi, a, b; const void *mem; int *chunk, full; NSMutableArray *old; uint64_t dead; uint64_t made; int nofull; uint64_t old_dead; } big_pool;   // made：给这个池建过的零拷贝缓冲长度合计（块、加长替下的旧块都算：都活到池走）；nofull：整池缓冲建不出来过，不再试   // dead：游戏已释放、到这次提交序号才回收（同池条目的 dead，pool_reap）   // chunk：步长 → g_pools 下标 + 1；full：整池那条 + 1；old：被加长替换下来的缓冲，随池走
static big_pool g_big[BIG_MAX]; static int g_nbig; static uint64_t g_big_chunks;   // g_big_chunks：建过的块（读数）
// 池表删一条时（gone 走、末尾那条 from 改名为 gone）大池块表里的下标跟着改：块表记的是池表下标，别的池被删、挪进空位的若是某个大池的块，
//   不改就指着别人的条目（GPU 地址落到别的缓冲上）；走的若正是块，块表那格清掉（下次查到再包）。调用方持 g_mu
static void big_index_move(int gone, int from) {
    for (int q = 0; q < g_nbig; q++) { big_pool *b = &g_big[q]; size_t nk = ((b->b - b->a) >> 24) + 1;
        for (size_t k = 0; k < nk; k++) { if (b->chunk[k] == gone + 1) b->chunk[k] = 0; else if (b->chunk[k] == from + 1) b->chunk[k] = gone + 1; }
        if (b->full == gone + 1) b->full = 0; else if (b->full == from + 1) b->full = gone + 1; }
}
static int big_of(uint64_t addr) { for (int i = 0; i < g_nbig; i++) if (addr >= g_big[i].lo && addr < g_big[i].hi) return i; return -1; }   // 调用方持 g_mu
static int pool_chunks(void) { static int c = -1; if (c < 0) { const char *e = getenv("DM_NVN_POOL_CHUNKS"); c = !e || atoi(e); } return c; }   // DM_NVN_POOL_CHUNKS=0：大池照旧整块（对照用）
static NSMutableArray *g_keep;                  // Holds the buffer references (pool_ent has non-owning pointers)
static uint64_t g_pool_adds;
static int g_pool_res_n;   // registered pools already in the residency set (for the memory readout; under g_mu)
// A queue piece parked after it was submitted may still name a pool after the guest Finalizes it. Keep the buffer alive and resident until that piece is replayed or dropped.
// The pool's normal deferred release is not merely allowed to run early: it also removes residency at its original fence, which can be before the later replay completes.
typedef struct { void *buf; uint32_t refs; int retired; } xq_buf_hold;
static xq_buf_hold *g_xq_bhold; static int g_xq_nbhold, g_xq_cbhold; static pthread_mutex_t g_xq_bhold_mu = PTHREAD_MUTEX_INITIALIZER;
static void xq_buf_hold_add(void *buf) {
    if (!buf) return; CFRetain(buf);
    pthread_mutex_lock(&g_xq_bhold_mu);
    int i = 0; while (i < g_xq_nbhold && g_xq_bhold[i].buf != buf) i++;
    if (i == g_xq_nbhold) {
        if (g_xq_nbhold == g_xq_cbhold) { int c = g_xq_cbhold ? g_xq_cbhold * 2 : 16; xq_buf_hold *p = realloc(g_xq_bhold, (size_t)c * sizeof *p); if (!p) MDIE("cross-queue buffer holds: out of memory"); g_xq_bhold = p; g_xq_cbhold = c; }
        g_xq_bhold[g_xq_nbhold++] = (xq_buf_hold){buf, 0, 0};
    }
    g_xq_bhold[i].refs++; pthread_mutex_unlock(&g_xq_bhold_mu);
}
static int xq_buf_hold_retire(void *buf) {
    int held = 0; pthread_mutex_lock(&g_xq_bhold_mu);
    for (int i = 0; i < g_xq_nbhold; i++) if (g_xq_bhold[i].buf == buf) { g_xq_bhold[i].retired = held = 1; break; }
    pthread_mutex_unlock(&g_xq_bhold_mu); return held;
}
static void xq_buf_hold_del(void *buf) {
    if (!buf) return; int retired = 0;
    pthread_mutex_lock(&g_xq_bhold_mu);
    for (int i = 0; i < g_xq_nbhold; i++) if (g_xq_bhold[i].buf == buf) {
        if (!--g_xq_bhold[i].refs) { retired = g_xq_bhold[i].retired; g_xq_bhold[i] = g_xq_bhold[--g_xq_nbhold]; }
        break;
    }
    pthread_mutex_unlock(&g_xq_bhold_mu);
    if (retired) defer_obj_release((__bridge id)buf);   // re-time residency removal behind the last replay that owned this hold
    CFRelease(buf);
}
// Access bits of the raw pool table (gmem_map / gmem_scan): a pool the table lists but the host has not made resident, or made resident only for the table, gets a bit, which a raw
// access sets when it chooses the pool's entry. Bits belong to pools, not entries, so a rebuilt table loses none set by submissions still running. Under g_mu
enum { GSLOT_MAX = 65536 };
static int *g_gslot_pool, *g_gslot_free, g_gslot_nfree, g_gslot_hi;   // bit → pool index (-1: free); freed bits; bits ever given out
static __strong id<MTLBuffer> g_gbits;   // the bitmap the shaders set (GSLOT_MAX bits), resident
static int gslot_get(int i) {   // pool i's bit, given out on first use; -1 when all are taken
    if (g_pools[i].gslot) return g_pools[i].gslot - 1;
    if (!g_gslot_pool) { g_gslot_pool = malloc(sizeof *g_gslot_pool * GSLOT_MAX); g_gslot_free = malloc(sizeof *g_gslot_free * GSLOT_MAX); if (!g_gslot_pool || !g_gslot_free) MDIE("raw global memory: out of memory for the access bits"); }
    int b = g_gslot_nfree ? g_gslot_free[--g_gslot_nfree] : g_gslot_hi < GSLOT_MAX ? g_gslot_hi++ : -1;
    if (b < 0) return -1;
    g_gslot_pool[b] = i; g_pools[i].gslot = b + 1;
    return b;
}
static void gslot_put(int i) {   // pool i goes: its bit is free again (a submission still running may set it once more: the next pool to get it is then taken as reached, which only makes it resident)
    int b = g_pools[i].gslot - 1; if (b < 0) return;
    g_gslot_pool[b] = -1; g_gslot_free[g_gslot_nfree++] = b; g_pools[i].gslot = 0;
    if (g_gbits) atomic_fetch_and((_Atomic uint32_t *)g_gbits.contents + (b >> 5), ~(1u << (b & 31)));
}

#define C1_BANK_SIZE (4u << 20)
#define C1_DECL_SIZE (64u << 10)
static NSMutableArray *g_c1_banks;
static size_t g_c1_bank_off, g_c1_alloc_bytes, g_c1_data_bytes;
static uint64_t g_c1_count, g_c1_exclusive;
static NSMutableSet<NSString *> *g_c1_full;
static int g_c1_full_valid;
static NSDictionary<NSString *, NSString *> *g_cb_ext;   // cb_extent.tsv: shader key → "reg:bytes ..." (how far into each uniform slot the shader can read); nil when stale or missing
static os_unfair_lock g_c1_lock = OS_UNFAIR_LOCK_INIT;

// DM_UDC_SELFTEST=1 (diagnostic, checks DontCare behavior on a real A19 device): private-storage Depth32Float_Stencil8 / RGBA8 (1952x900) are first cleared to write known values,
// then Load + DontCare without drawing, read back and compared pixel by pixel, printing one result line
static void udc_selftest(void) {
    if (!getenv("DM_UDC_SELFTEST")) return;
    id<MTLCommandQueue> q = [g_dev newCommandQueue];
    for (int depth = 1; depth >= 0; depth--) {
        NSUInteger w = 1952, h = 900;
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:depth ? MTLPixelFormatDepth32Float_Stencil8 : MTLPixelFormatRGBA8Unorm width:w height:h mipmapped:NO];
        td.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; td.storageMode = MTLStorageModePrivate;
        id<MTLTexture> t = [g_dev newTextureWithDescriptor:td];
        id<MTLCommandBuffer> cb = [q commandBuffer];
        for (int pass = 0; pass < 2; pass++) {
            MTLRenderPassDescriptor *rp = [MTLRenderPassDescriptor renderPassDescriptor];
            MTLLoadAction la = pass ? MTLLoadActionLoad : MTLLoadActionClear; MTLStoreAction sa = pass ? MTLStoreActionDontCare : MTLStoreActionStore;
            if (depth) { rp.depthAttachment.texture = t; rp.depthAttachment.loadAction = la; rp.depthAttachment.storeAction = sa; rp.depthAttachment.clearDepth = 0.3125;
                         rp.stencilAttachment.texture = t; rp.stencilAttachment.loadAction = la; rp.stencilAttachment.storeAction = sa; rp.stencilAttachment.clearStencil = 0x5a; }
            else { rp.colorAttachments[0].texture = t; rp.colorAttachments[0].loadAction = la; rp.colorAttachments[0].storeAction = sa; rp.colorAttachments[0].clearColor = MTLClearColorMake(0.2, 0.4, 0.6, 0.8); }
            [[cb renderCommandEncoderWithDescriptor:rp] endEncoding];
        }
        id<MTLBuffer> out = [g_dev newBufferWithLength:w * h * 4 options:MTLResourceStorageModeShared];
        id<MTLBlitCommandEncoder> b = [cb blitCommandEncoder];
        [b copyFromTexture:t sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1) toBuffer:out destinationOffset:0
            destinationBytesPerRow:w * 4 destinationBytesPerImage:w * h * 4 options:depth ? MTLBlitOptionDepthFromDepthStencil : MTLBlitOptionNone];
        [b endEncoding]; [cb commit]; [cb waitUntilCompleted];
        const uint32_t *px = out.contents; NSUInteger bad = 0; for (NSUInteger i = 0; i < w * h; i++) if (px[i] != px[0]) bad++;
        MLOG("UDC self-check %s %s %lux%lu first value %08x, values differing from it %lu / %lu", g_dev.name.UTF8String, depth ? "Depth32F_S8" : "RGBA8", (unsigned long)w, (unsigned long)h, px[0], (unsigned long)bad, (unsigned long)(w * h));
    }
}
static void bcd_prewarm(void);   // no BC: start building the decompression pipeline (defined with bcd_pso)
static void ixc_prewarm(void); static void tensor_sq_prewarm(void);   // Switch 2: start building the indirect conversion / tensor stand-in kernels (defined with ixc_run / tensor_sq_pass)
// 起局时的出图方式（mtl_init 首局、nvn_be_begin_session 每局开头共用同一判法，11-15：每局开头原先只按 DM_PRESENT_LINK 设、缺省 1，
//   补帧开着也起显示链——进程内重启 / 切游戏后补帧任务与显示链同时取画布，CAMetalLayerInvalidOperation 闪退，#ee56e7 / #1155 的另一条入口）。
//   0 = 出图线程自己取画布、1 = 60 Hz 显示链、2 = 高刷显示链
static int g_link_base = 1;   // 不算补帧时的出图方式（环境 DM_PRESENT_LINK，缺省 1）：补帧这局 / 这一帧不补时回到它（fi_link_follow、fi_off）
// Metal 性能浮层开着没有、从哪认出来的（NULL = 没开）：见 present_link_from_env 里 #1523 那段
static const char *metal_hud_source(void) {
    const char *e = getenv("MTL_HUD_ENABLED"); if (e && !strcmp(e, "1")) return "环境变量 MTL_HUD_ENABLED";
    if ([NSUserDefaults.standardUserDefaults boolForKey:@"MetalForceHudEnabled"]) return "偏好 MetalForceHudEnabled";
    for (uint32_t i = 0, n = _dyld_image_count(); i < n; i++) { const char *nm = _dyld_get_image_name(i); if (nm && strstr(nm, "libMTLHud")) return "浮层库 libMTLHud 已载入"; }
    return NULL;
}
static int present_link_from_env(void) {
    const char *link = getenv("DM_PRESENT_LINK");
    int v = link ? atoi(link) : 1; if (v < 0 || v > 2) v = 1;
    g_link_base = v;   // Default 1 (real-device same-process alternation: when load exceeds one display-link period, long frames 15% → 0 and frame intervals even out; no difference from 0 at a steady 60); DM_PRESENT_LINK=0 turns it off   // 1 = present on every tick of a 60 Hz display link; 2 = 120 Hz display link, the game presents a frame every other display-link tick (when behind, it can present on the next 8.33 ms display-link tick)
    // 出图补帧走出图线程自己取画布，一开始就不建显示链接。例外：社区帧率补丁已要了 120 Hz 显示链（DM_PRESENT_LINK=2，runtime/src/cpatch.c fps_link）——
    //   补丁开着时补帧每帧让路（fi_wanted），走原出图路径；这里再清成 0，原路径就没有显示链、只能按固定 60 Hz 出，120 档被锁在 60
    //   （11-15 iPhone 实机一款 120 帧补丁的游戏局内：补帧开 60.0 帧、DM_PRESENT_FI=0 120.0 帧）
    //   Metal 3 不补帧（nvn_present_fi.inc fi_wanted），显示链照建（审计 P1-188：原先在知道是不是 Metal 3 之前就清成 0，Metal 3 的局既没补帧也没显示链）——
    //   所以 mtl_init 要先定后端再调本函数
    { const char *fi = getenv("DM_PRESENT_FI"); if (fi && !strcmp(fi, "1") && v != 2 && !g_m3) v = 0; }
    // Metal 性能浮层 + 显示链在老 macOS 上闪退（D-G4ZD / #1490，macOS 15.7.9 两局开局 1～3 帧 abort）：系统的 libMTLHud 换掉
    //   CAMetalDisplayLinkUpdate 的 drawable 取值，把这个更新对象当 CAMetalLayer 交给浮层初始化，发 -device 不认 → ObjC 异常。
    //   macOS 27.2 上同样开浮层 + 显示链（本机最小程序，libMTLHud 已加载）跑 120 帧不崩，苹果已修；中间哪一版修的没核，按 27 以下都避开。
    //   玩家在启动器开了 Metal 性能浮层（MTL_HUD_ENABLED=1）时这一局出图线程自己取画布（同 DM_PRESENT_LINK=0），浮层照常显示
    //   D-3VFB（0.6.9 iPadOS 18.7.8）：iOS / iPadOS 同一个系统 bug（设置 → 开发者 → Metal 性能浮层，libMTLHud 载入，同一句 -[CAMetalDisplayLinkUpdate device]
    //   unrecognized selector），原先只在 Mac 上避开。不分平台同一判法：系统版本号 26 起两边统一，27 以下都避开（同 Mac 口径，iOS 哪一版修的没核）
    //   #1523（D-H9ZM，0.5.7 macOS 15.7.9）：只认环境变量漏了别的打开方式——浮层开着、这一行没打、照样闪退。改成判浮层实际开没开：
    //   环境变量 MTL_HUD_ENABLED=1、偏好 MetalForceHudEnabled（含全局 defaults write -g，开发者设置用的就是它）、或浮层库 libMTLHud 已载入进程，任一即算
    { const char *hud = metal_hud_source();
      if (v && hud && NSProcessInfo.processInfo.operatingSystemVersion.majorVersion < 27) {
          static int said; if (!said++) MLOG("Metal 性能浮层开着（%s）、系统版本 %ld 低于 27：这一局不用显示链（系统浮层在老版本上和显示链一起会闪退，D-G4ZD / D-3VFB）", hud, (long)NSProcessInfo.processInfo.operatingSystemVersion.majorVersion);
          v = 0; g_link_base = 0;
      } }
    return v;
}
static void present_fsr_env_check(void);   // nvn_present_fsr.inc
void mtl_init(void) {
    if (g_dev) return;
    present_fsr_env_check();   // 选了 Fsr 且 S2A_SCALING_FILTER_LEVEL 非法：起局就报红退出，不等第一次上屏（present_options 是首次上屏编码时才读的）
    const char *vbc = getenv("DM_NVN_VBUF_CACHE"); g_vbuf_cache = !(vbc && !strcmp(vbc, "0"));
    const char *latency = getenv("DM_PRESENT_LATENCY");
    if (latency && atoi(latency) > 0) g_present_latency = atoi(latency);
    g_res_check_on = getenv("DM_RES_CHECK") != NULL;
    s2a_mtl_slot_take("mtl_init");   // machine-wide Metal client slot (graphics/metal/mtl_slot.h): taken before the device, held until exit
    g_dev = MTLCreateSystemDefaultDevice();
    if (!g_dev) MDIE("no Metal device");
    if (!g_dev.hasUnifiedMemory) MDIE("needs a unified-memory device (zero-copy memory pools)");
    int os26 = 0, family4 = 0, ios26x = 0; const char *be_why;
    if (@available(macOS 26.0, iOS 26.0, *)) { os26 = 1; family4 = [g_dev supportsFamily:MTLGPUFamilyMetal4]; }
#if TARGET_OS_IPHONE
    if (os26) { if (@available(iOS 27.0, *)) {} else ios26x = 1; }   // iOS 26.x：见 nvn_be.h（#311）
#endif
    g_m3 = nvn_be_pick(getenv("NXGAL_BE"), os26, family4, ios26x, &be_why) == NVN_BE_MTL3;
    MLOG("direct backend: Metal %d (%s)", g_m3 ? 3 : 4, be_why);
    g_dm_present_link = present_link_from_env();   // 后端定了才定出图方式（Metal 3 不补帧、不关显示链）
    g_mesh_ok = [g_dev supportsFamily:MTLGPUFamilyMetal3];   // object / mesh functions (NVN2 DrawMeshTasks): Apple7+ / Mac2, every Metal 4 GPU; an older GPU on the Metal 3 path has none
    g_red_emu = !s2a_reduce_native(g_dev); g_lb_emu = !s2a_lodbias_native(g_dev);
    g_red_emu_why = s2a_samp_emu_forced() ? "forced by S2A_SAMP_EMU=1" : !os26 ? "macOS / iOS before 26" : "the GPU is not Apple10";
    MLOG("sampler reduction: %s; sampler LOD bias: %s (%s)", g_red_emu ? "in the shader" : "native", g_lb_emu ? "in the shader" : "native", g_dev.name.UTF8String);
    g_q = [g_dev newCommandQueue];
    MTLResidencySetDescriptor *rd = [MTLResidencySetDescriptor new];
    rd.initialCapacity = 4096;
    NSError *re = nil;
    g_res = [g_dev newResidencySetWithDescriptor:rd error:&re];
    if (!g_res) MDIE("failed to create the MTLResidencySet");
    [g_q addResidencySet:g_res];
    { void crash_set_wait_dump(void (*fn)(void)); void mtl_wait_state_dump(void); crash_set_wait_dump(mtl_wait_state_dump); }
    if (g_m3) {
        // The same residency set on an old queue (macOS 15 / iOS 18 on). Not made here: the Metal 4 queue, the three allocator rotations (main, upload, present), the argument tables
        // (bindings are D3-3 #279), the present argument table and UV buffers (present_encode binds directly)
        g_q3 = [g_dev newCommandQueue];
        if (!g_q3) MDIE("failed to create the Metal 3 MTLCommandQueue");
        [g_q3 addResidencySet:g_res];
        g_fence3 = [g_dev newFence];
        NSError *te = nil;   // the argument tables as DmTable3 (#279 D3-3; tab_new)
        g_vt = tab_new(31, 1, 0, &te); g_ft = tab_new(31, 1, 0, &te); g_ct = tab_new(31, 1, 0, &te); g_up_ct = tab_new(31, 1, 0, &te); g_ot = tab_new(31, 1, 0, &te); g_present_args = tab_new(1, 1, 1, &te);
        if (!g_vt || !g_ft || !g_ct || !g_up_ct || !g_present_args) MDIE("failed to create the Metal 3 argument tables: %s", te.localizedDescription.UTF8String);
        // Metal 3 编码线程：缺省关（DM_NVN_ENC_THREAD=1 可开），rec_on() 按 g_m3 判断
        MLOG("Metal 3 path: draw passes, copies and fills on the old encoders (D3-2 #278), argument tables DmTable3 (D3-3 #279), bindings below a buffer's start through prefixed scratch (D3-4 #329)");
    } else {
        dispatch_queue_attr_t feedback_attr = s2a_qos_queue_attr(DISPATCH_QUEUE_SERIAL, S2A_QOS_MTL_FEEDBACK);
        g_feedback_q = dispatch_queue_create("dm.nvn.mtl4-feedback", feedback_attr);
        MTL4CommandQueueDescriptor *q4d = [MTL4CommandQueueDescriptor new]; q4d.feedbackQueue = g_feedback_q;
        g_q4 = [g_dev newMTL4CommandQueueWithDescriptor:q4d error:&re];
        if (!g_q4) MDIE("failed to create the MTL4CommandQueue");
        [g_q4 addResidencySet:g_res];
        g_alloc_n = 3;
        for (int i = 0; i < 3; i++) {
            MTL4CommandAllocatorDescriptor *ad = [MTL4CommandAllocatorDescriptor new];
            ad.label = [NSString stringWithFormat:@"nvn-mtl allocator %d", i];
            NSError *ae = nil;
            g_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
            if (!g_alloc4[i]) MDIE("failed to create MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
            g_up_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
            if (!g_up_alloc4[i]) MDIE("failed to create upload MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
            MTL4CommandAllocatorDescriptor *pad = [MTL4CommandAllocatorDescriptor new];
            pad.label = [NSString stringWithFormat:@"nvn-mtl present allocator %d", i];
            g_present_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:pad error:&ae];
            if (!g_present_alloc4[i]) MDIE("failed to create present MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
            g_present_cb[i] = [g_dev newCommandBuffer];
            if (!g_present_cb[i]) MDIE("failed to create present MTL4CommandBuffer[%d]", i);
        }
        MTL4ArgumentTableDescriptor *atd = [MTL4ArgumentTableDescriptor new];
        atd.maxBufferBindCount = 31; atd.maxTextureBindCount = 1;
        NSError *ate = nil;
        g_vt = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_vt) MDIE("failed to create the vertex argument table: %s", ate.localizedDescription.UTF8String);
        g_vt_valid = 0;
        g_ft = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_ft) MDIE("failed to create the fragment argument table: %s", ate.localizedDescription.UTF8String);
        g_ct = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_ct) MDIE("failed to create the compute argument table: %s", ate.localizedDescription.UTF8String);
        g_ot = rec_table(tab_new(31, 1, 0, &ate));   // through tab_new: the object table is new code (avail / MTL4 ratchets)
        if (!g_ot) MDIE("failed to create the object argument table: %s", ate.localizedDescription.UTF8String);
        g_up_ct = [g_dev newArgumentTableWithDescriptor:atd error:&ate]; if (!g_up_ct) MDIE("failed to create the upload compute argument table: %s", ate.localizedDescription.UTF8String);
        MTL4ArgumentTableDescriptor *pad = [MTL4ArgumentTableDescriptor new];
        pad.maxTextureBindCount = 1; pad.maxSamplerStateBindCount = 1; pad.maxBufferBindCount = 1;
        g_present_args = [g_dev newArgumentTableWithDescriptor:pad error:&ate];
        if (!g_present_args) MDIE("failed to create the present argument table: %s", ate.localizedDescription.UTF8String);
        for (int i = 0; i < 3; i++) {
            g_present_uv[i] = [g_dev newBufferWithLength:sizeof(float) * 16 options:MTLResourceStorageModeShared];   // PR3b：UV 常量缓冲扩到 16 浮点（后 8 = 模式参数 p[0..7]，着色器 Crop 全量读）
            if (!g_present_uv[i]) MDIE("failed to create present UV buffer[%d]", i);
            res_add(g_present_uv[i]);
        }
    }
    g_half_masks = [g_dev newBufferWithLength:65536 * sizeof(uint32_t) options:MTLResourceStorageModeShared];
    if (!g_half_masks) MDIE("failed to create the half color rounding table");
    for (unsigned i = 0; i < 65536; i++) ((uint32_t *)g_half_masks.contents)[i] = i;
    res_add(g_half_masks);
    g_ev = [g_dev newSharedEvent];
    g_keep = [NSMutableArray array];
    // Both backends share one pipeline (newComputePipelineStateWithFunction); only the encode differs: Metal 4 sets an argument table and takes the parameter block from a buffer, Metal 3 passes it
    // with setBytes on the old compute encoder (#329 D3-4 class 3). Same kernel, so the Metal 3 result is byte-identical to the CPU deswizzle it replaces.
    g_nvn_deswz_gpu = nvn_deswz_gpu_init(g_dev) == 0;
    dm_res_report_register(mtl_res_counts);
    if (g_m3 && g_nvn_deswz_gpu) MLOG("Metal 3: GPU deswizzle on (classic compute encoder, parameter block through setBytes)");
    else if (!g_nvn_deswz_gpu) MLOG("【红】 GPU deswizzle init failed; swizzled textures fall back to the CPU");
    MLOG("Metal device %s", g_dev.name.UTF8String);
    udc_selftest();
    warm_announce();
    bcd_prewarm();   // S2Arm #582: no BC, the decompression pipeline is built in the background (see bcd_ready)
    ixc_prewarm(); tensor_sq_prewarm();   // S2Arm #674: Switch 2, the two kernels compiled from source are built in the background (see ixc_ready / tensor_sq_ready)
}



// No-copy buffers of finalized pools (weak references, under g_mu): the memory report counts how many are still alive and their length -- a buffer that outlives its pool is still strongly referenced by something else (a texture built directly on the pool, etc.)
static NSHashTable *g_dead_pools;
// Address → pool cache per thread (nvn_be_addr / mtl_gpu_addr), valid while g_pool_gen is unchanged (every pool add / removal bumps it under g_mu), holding only pools already in the residency set.
// Every buffer binding of every draw used to take g_mu, which game threads creating pools and the GPU completion handler also take, and search the pool index. Two levels: a table direct-mapped
// by 4 KB page, then the last 8 pools found, which also fill the table. Breath of the Wild binds from more pools a frame than 8 entries alone could hold (about 2300 of its 21000 lookups a frame
// took the lock), and its uniform rings move to a new page every few draws (the table alone missed as often)
enum { PC_BITS = 10, PC_RECENT = 8 };
static _Atomic uint64_t g_pool_gen = 1;
static _Atomic uint64_t g_gmem_pgen = 1;   // raw global memory table generation: bumped when g_addr or address-eligible pools change (not per-pool-age checks)
typedef struct { uintptr_t lo, hi, base; __unsafe_unretained id<MTLBuffer> buf; uint64_t gpu; uintptr_t host, end; } pc_ent;   // end: what the buffer holds for this entry (pool_end)   // host: buf.contents (the pool's pages, or their far shadow), kept so a CPU read sends no message
static __thread struct { uint64_t gen; unsigned next; pc_ent r[PC_RECENT], e[1u << PC_BITS]; } t_pc;   // an empty entry has hi 0
static inline unsigned pc_slot(uint64_t addr) { return (unsigned)(((addr >> 12) * 0x9E3779B97F4A7C15ull) >> (64 - PC_BITS)); }
static inline const pc_ent *pc_get(uint64_t addr, uint64_t len) {
    if (t_pc.gen != atomic_load_explicit(&g_pool_gen, memory_order_acquire)) return NULL;
    pc_ent *c = &t_pc.e[pc_slot(addr)];
    if (addr >= c->lo && addr + len <= c->hi) return c;
    for (unsigned k = 0; k < PC_RECENT; k++) { const pc_ent *x = &t_pc.r[k]; if (addr >= x->lo && addr + len <= x->hi) { *c = *x; return c; } }
    return NULL;
}
static uintptr_t pool_end(int i);   // below (pool_buf_end)
static void pc_put(int i, uint64_t addr) {   // caller holds g_mu, pool i is resident and holds addr
    uint64_t gen = atomic_load_explicit(&g_pool_gen, memory_order_relaxed);
    if (t_pc.gen != gen) { memset(t_pc.r, 0, sizeof t_pc.r); memset(t_pc.e, 0, sizeof t_pc.e); t_pc.gen = gen; }
    pc_ent c = {g_pools[i].lo, g_pools[i].hi, g_pools[i].base, g_pools[i].buf, g_pools[i].gpu, g_pools[i].host, pool_end(i)};
    t_pc.e[pc_slot(addr)] = c; t_pc.r[t_pc.next++ % PC_RECENT] = c;
}
// Test check (S2A_POOL_RES_CHECK=1; off for players, one branch on each cache hit): every GPU address a cache hands out without pool_res (pc_get in nvn_be_addr / gpu_addr_want,
//   the vertex buffer cache) is noted with the path that handed it out; when the submission commits (rchk_verify), one that lies only in pools the residency set no longer holds
//   is reported with that path. This is what pool_age must never cause: a pool taken out while a cache still gives out its address
static int g_rchk = -1; static pthread_mutex_t g_rchk_mu = PTHREAD_MUTEX_INITIALIZER; static CFMutableDictionaryRef g_rchk_seen; static uint64_t g_rchk_bad; static const char *g_rchk_last;   // g_rchk_last: the path of the last one reported
static int rchk_init(void) { const char *e = getenv("S2A_POOL_RES_CHECK"); g_rchk = e && *e && *e != '0'; if (g_rchk) MLOG("memory pools: residency check on (S2A_POOL_RES_CHECK): addresses the caches hand out are checked at each commit"); return g_rchk; }
static void rchk_note(uint64_t gpu, const char *path) {
    pthread_mutex_lock(&g_rchk_mu);
