        if (ch) { g_big[g_nbig++] = (big_pool){lo, hi, a, b, mem, ch, 0, [NSMutableArray array]}; g_plast = -1; atomic_fetch_add(&g_pool_gen, 1); if (addr_meets(lo, hi)) atomic_fetch_add(&g_gmem_pgen, 1); g_pool_adds++; }
