// g_gp_drop: encoders of the captured frame not recorded (GP_MAX full; the report then says the frame is truncated)
static __unsafe_unretained id g_gp_enc;   // the encoder g_gp_cur belongs to: gp_end of any other encoder (an upload batch's, through m4_end) leaves the label alone (11-06: it wrote a render pass's end into a compute encoder, NSInvalidArgumentException)
static gp_lab g_gp_lab[GP_MAX / 2]; static int g_gp_n, g_gp_cur = -1, g_gp_drop; static _Atomic int g_gp_state; static _Atomic uint64_t g_gp_rearm_frame = UINT64_MAX;   // state: 0 armed, 1 capturing, 2 report pending, 3 closed (frame ended)
static int gp_open(void); static long g_gp_f0 = -2, g_gp_f1; static uint64_t g_gp_frame;
static uint64_t g_stat_pass, g_stat_draw; static _Atomic uint64_t g_cur_frame; static uint32_t g_seg; static uint32_t g_gp_copies, g_gp_disp, g_gp_ubd;   // copies / dispatches encoded (for the compute encoders' labels)
static uint32_t g_rtw_w, g_rtw_h, g_rtw_fmt;   // 本窗口最大渲染目标（nvn_be_rt_window 读后清零）
static int gp_active(void) {
    if (__builtin_expect(g_gp_f0 == -1, 1)) return 0;
    if (g_gp_f0 == -2) { const char *e = getenv("DM_NVN_GPUPROF"); g_gp_f0 = e ? atol(e) : -1; g_gp_f1 = e && strchr(e, '-') ? atol(strchr(e, '-') + 1) : g_gp_f0;
        if (g_gp_f0 < 0) return 0; }
    long f = (long)atomic_load(&g_cur_frame); return f >= g_gp_f0 && f <= g_gp_f1;
}
static int gp_open(void) {   // may the encoder being made be captured (see DM_NVN_GPUPROF): the first encoder of a new frame closes the capture; a re-armed one starts at the next frame
    uint64_t f = atomic_load(&g_cur_frame); int st = g_gp_state;
    if (st == 1 && f != g_gp_frame) { g_gp_state = 3; return 0; }
    return st == 1 || (st == 0 && f != atomic_load(&g_gp_rearm_frame));
}
// Metal 3 (DM_NVN_GPUPROF): the same rows from an MTLCounterSampleBuffer on the device's timestamp counter set. The sample points go on the pass descriptor BEFORE the encoder is made
// (start of vertex / end of fragment at 2n and 2n+1; a compute pass has the start and end of the encoder), because an old encoder names no sample point itself. Copy encoders cannot sample
// (MTLBlitCommandEncoder has no sample buffer attachments), so a Metal 3 report has no compute / copy rows.
static int g_gp_sb_bad;
static int gp_m3_ready(void) {
    if (g_gp_sb_bad) return 0;
    if (g_gp_sb) return 1;
    id<MTLCounterSet> ts = nil;
    for (id<MTLCounterSet> cs in g_dev.counterSets) if ([cs.name isEqualToString:MTLCommonCounterSetTimestamp]) ts = cs;
    if (!ts || ![g_dev supportsCounterSampling:MTLCounterSamplingPointAtStageBoundary]) {
        MLOG("【红】 GPUPROF on Metal 3 needs the timestamp counter set and sampling at stage boundaries (this GPU: %s)", !ts ? "no timestamp counter set" : "no stage-boundary sampling; copy encoders are never sampled either");
        g_gp_sb_bad = 1; return 0; }
    MTLCounterSampleBufferDescriptor *sd = [MTLCounterSampleBufferDescriptor new]; sd.counterSet = ts; sd.storageMode = MTLStorageModeShared; sd.sampleCount = GP_MAX;
    NSError *er = nil; g_gp_sb = [g_dev newCounterSampleBufferWithDescriptor:sd error:&er];
    if (!g_gp_sb) { MLOG("【红】 GPUPROF: no Metal 3 sample buffer: %s", er.description.UTF8String); g_gp_sb_bad = 1; return 0; }
    return 1;
}
static gp_lab gp_lab_make(char kind, id d) {
    gp_lab l = {kind, 0, 0, 0, 0, 0, kind == 'R' ? (uint32_t)g_stat_draw : g_gp_copies, g_seg, g_stat_pass, (uint32_t)(g_gmem_draws + g_gmem_disp)}; if (kind != 'R') { l.w = (uint16_t)g_gp_disp; l.h = (uint16_t)g_gp_ubd; }
    if (d) { for (int i = 0; i < 8; i++) { MTLRenderPassColorAttachmentDescriptor *c = ((MTLRenderPassDescriptor *)d).colorAttachments[i]; if (!c.texture) continue;
            l.nc++; l.w = (uint16_t)MAX(c.texture.width >> c.level, 1); l.h = (uint16_t)MAX(c.texture.height >> c.level, 1); l.loads += c.loadAction == MTLLoadActionLoad; }
        MTLRenderPassDepthAttachmentDescriptor *z = ((MTLRenderPassDescriptor *)d).depthAttachment;
        if (z.texture) { l.depth = 1; l.w = (uint16_t)MAX(z.texture.width >> z.level, 1); l.h = (uint16_t)MAX(z.texture.height >> z.level, 1); l.loads += z.loadAction == MTLLoadActionLoad; } }
    return l;
}
static void gp_pre(id d, char kind) {   // Metal 3: before the encoder is made — the pass descriptor carries the sample points
    if (!g_m3 || !gp_active() || !gp_m3_ready() || !gp_open()) return;
    if (!g_gp_state) { g_gp_state = 1; g_gp_n = 0; g_gp_drop = 0; g_gp_frame = atomic_load(&g_cur_frame); }
    if (2 * g_gp_n + 2 > GP_MAX) { g_gp_drop++; return; }
    g_gp_lab[g_gp_n] = gp_lab_make(kind, kind == 'R' ? d : nil); g_gp_cur = g_gp_n;
    if (kind == 'R') { MTLRenderPassSampleBufferAttachmentDescriptor *a = ((MTLRenderPassDescriptor *)d).sampleBufferAttachments[0];
        a.sampleBuffer = g_gp_sb; a.startOfVertexSampleIndex = 2 * g_gp_n; a.endOfFragmentSampleIndex = 2 * g_gp_n + 1; }
    else { MTLComputePassSampleBufferAttachmentDescriptor *a = ((MTLComputePassDescriptor *)d).sampleBufferAttachments[0];
        a.sampleBuffer = g_gp_sb; a.startOfEncoderSampleIndex = 2 * g_gp_n; a.endOfEncoderSampleIndex = 2 * g_gp_n + 1; }
    g_gp_n++;
}
static id g_ts_heap; static int g_ts_pend = -1;   // ts_on; pend: the segment boundary the next encoder writes (ts_stamp)
static void gp_begin(id e, char kind, MTL4RenderPassDescriptor *d) {   // right after an encoder of the main command buffer is made (Metal 4; Metal 3 does this in gp_pre)
    if (g_ts_pend >= 0 && !g_m3) { NSUInteger slot = (NSUInteger)g_ts_pend; g_ts_pend = -1;   // a segment boundary (ts_stamp) at the start of this encoder
        ts_write(e, kind, MTLRenderStageVertex, g_ts_heap, slot); }
    if (g_m3 || !gp_active() || !gp_open()) return;
    if (!g_gp_heap) { NSError *er = nil;
        g_gp_heap = ts_heap_new(GP_MAX, &er); if (!g_gp_heap) { MLOG("【红】 GPUPROF: no counter heap: %s", er.description.UTF8String); g_gp_f0 = -1; return; } }
    if (!g_gp_state) { g_gp_state = 1; g_gp_n = 0; g_gp_drop = 0; g_gp_frame = atomic_load(&g_cur_frame); [g_gp_heap invalidateCounterRange:NSMakeRange(0, GP_MAX)]; }
    if (2 * g_gp_n + 2 > GP_MAX) { g_gp_drop++; return; }
    g_gp_lab[g_gp_n] = gp_lab_make(kind, d); g_gp_cur = g_gp_n; g_gp_enc = e;
    ts_write(e, kind, MTLRenderStageVertex, g_gp_heap, 2 * g_gp_n);
    g_gp_n++;
}
static void gp_end(id e) {   // right before that encoder ends
    if (g_gp_cur < 0 || (!g_m3 && e != g_gp_enc)) return;
    int k = g_gp_cur; g_gp_cur = -1; g_gp_lab[k].gm = (uint32_t)(g_gmem_draws + g_gmem_disp) - g_gp_lab[k].gm; if (g_gp_lab[k].kind == 'R') g_gp_lab[k].draws = (uint32_t)g_stat_draw - g_gp_lab[k].draws; else { g_gp_lab[k].draws = g_gp_copies - g_gp_lab[k].draws; g_gp_lab[k].w = (uint16_t)(g_gp_disp - g_gp_lab[k].w); g_gp_lab[k].h = (uint16_t)(g_gp_ubd - g_gp_lab[k].h); }
    if (g_m3) return;   // Metal 3: the sample points went on the pass descriptor (gp_pre)
    ts_write(e, g_gp_lab[k].kind, MTLRenderStageFragment, g_gp_heap, 2 * k + 1);
}
// S2Arm 11-06 能耗线：几何绘制段的两个道编码器（nvn_geometry.inc geo_run_*）与主遍同时开着，不能占 g_gp_cur：各记各的标签号。kind 'P' 抓顶点、'K' 几何核 + 索引压缩，
//   draws 记本编码器收了几笔几何绘制。原先不记，金刚一帧 51 ms 的几何段工作在逐编码器剖析里是一段「空档」（11-06 L2 补测局第 4400 帧）
static int gp_lane_begin(id e, char kind, uint32_t n0) {
    int cur = g_gp_cur, n = g_gp_n; __unsafe_unretained id enc = g_gp_enc; gp_begin(e, kind == 'P' ? 'R' : 'C', nil); int k = g_gp_n > n ? g_gp_n - 1 : -1; g_gp_cur = cur; g_gp_enc = enc;
    if (k >= 0) { g_gp_lab[k].kind = kind; g_gp_lab[k].w = g_gp_lab[k].h = 1; g_gp_lab[k].draws = n0; }
    return k;
}
static void gp_lane_end(id e, int k, uint32_t n1) {
    if (k < 0 || k >= g_gp_n || g_m3) return;
    char kind = g_gp_lab[k].kind; uint32_t n0 = g_gp_lab[k].draws; int cur = g_gp_cur;
    __unsafe_unretained id enc = g_gp_enc;
    g_gp_lab[k].kind = kind == 'P' ? 'R' : 'C'; g_gp_cur = k; g_gp_enc = e; gp_end(e); g_gp_cur = cur; g_gp_enc = enc;   // gp_end writes the end timestamp by kind
    g_gp_lab[k].kind = kind; g_gp_lab[k].draws = n1 - n0;
}
static void gp_report(int n, int dropped, gp_lab *lab, uint64_t frame) {   // the frame's last command buffer has completed
    // Both resolve to 2n 64-bit timestamps in order (MTLCounterResultTimestamp holds the one field); Metal 3's sample buffer reports nanoseconds, Metal 4's heap ticks
    NSData *r = g_m3 ? [g_gp_sb resolveCounterRange:NSMakeRange(0, 2 * n)] : [g_gp_heap resolveCounterRange:NSMakeRange(0, 2 * n)];
    const uint64_t *t = r.bytes; if (!t) { free(lab); atomic_store(&g_gp_rearm_frame, atomic_load(&g_cur_frame)); atomic_store(&g_gp_state, 0); return; }
    double tick_ns = g_m3 ? 1.0 : 1e9 / (double)[g_dev queryTimestampFrequency], tot[2] = {0}, span = 0, gm_us = 0; int gm_n = 0; uint64_t t0 = 0, t1 = 0;
    for (int i = 0; i < n; i++) { uint64_t a = t[2 * i], b = t[2 * i + 1]; if (!a || !b || b < a) continue;
        double us = (b - a) * tick_ns / 1e3; const gp_lab *l = &lab[i]; tot[l->kind != 'R' && l->kind != 'P'] += us; if (l->gm) { gm_us += us; gm_n++; }
        if (!t0 || a < t0) t0 = a; if (b > t1) t1 = b;
        if (l->kind == 'P' || l->kind == 'K') MLOG("[gpuprof] F%llu %4d %8.1f us geometry run %s, %u geometry draws, after pass %llu start %+.1f seg %u", (unsigned long long)frame, i, us,
            l->kind == 'P' ? "captures (render)" : "geometry kernels + compaction (compute)", l->draws, (unsigned long long)l->pass, (a - t[0]) * tick_ns / 1e3, l->seg);
        else if (l->kind == 'R') MLOG("[gpuprof] F%llu %4d %8.1f us render pass %llu %ux%u colors %u depth %u loads %u draws %u start %+.1f seg %u", (unsigned long long)frame, i, us, (unsigned long long)l->pass, l->w, l->h, l->nc, l->depth, l->loads, l->draws, (a - t[0]) * tick_ns / 1e3, l->seg);
        else MLOG("[gpuprof] F%llu %4d %8.1f us compute / copy after pass %llu start %+.1f seg %u copies %u (uniform updates %u) dispatches %u", (unsigned long long)frame, i, us, (unsigned long long)l->pass, (a - t[0]) * tick_ns / 1e3, l->seg, l->draws, l->h, l->w); }
    span = (t1 - t0) * tick_ns / 1e3;
    MLOG("[gpuprof] frame %llu: render %.2f ms, compute / copy %.2f ms over %d encoders, first start to last end %.2f ms; encoders with raw-memory-pool-table draws / dispatches %.2f ms (%d)%s", (unsigned long long)frame, tot[0] / 1e3, tot[1] / 1e3, n, span / 1e3, gm_us / 1e3, gm_n, dropped ? " (TRUNCATED: see the next line)" : "");
    // 11-05 金刚：一帧 4000 多个编码器，只记得下前 GP_MAX / 2 个，报告曾被当成整帧读。记满时明说截断：之后的编码器没记，以上合计 / 跨度只是前段
    if (dropped) MLOG("【黄】 [gpuprof] frame %llu TRUNCATED: %d more encoders after the first %d were not recorded (limit %d per frame = the largest timestamp heap); the totals and span above cover only the frame's start", (unsigned long long)frame, dropped, n, GP_MAX / 2);
    free(lab); atomic_store(&g_gp_rearm_frame, atomic_load(&g_cur_frame)); atomic_store(&g_gp_state, 0);
}
// Render pass descriptors: MTL4RenderPassDescriptor on Metal 4, MTLRenderPassDescriptor on Metal 3. The replay writes them through the Metal 4 type and uses only what both classes have
// with the same names and meanings (attachments, target size and layers, raster sample count, visibility buffer)
static inline id pass_desc(void) { return g_m3 ? [MTLRenderPassDescriptor new] : [MTL4RenderPassDescriptor new]; }
// Argument tables. Metal 4 sets them on the encoder. Metal 3 (the interface agreed in #279) only notes each stage's current table (0 vertex, 1 fragment, 2 compute), and every draw or
// dispatch hands those to m3_table_apply first (m3_bind_draw / m3_bind_dispatch)
static id g_m3_tab[5];   // 3 object, 4 mesh: noted by a task / mesh draw (mtk_encode), applied by m3_bind_mesh
static inline void enc_r_table(id e, id t, MTLRenderStages s) {
    if (!g_m3) { [(id<MTL4RenderCommandEncoder>)e setArgumentTable:t atStages:s]; return; }
    if (s & MTLRenderStageVertex) g_m3_tab[0] = t;
    if (s & MTLRenderStageFragment) g_m3_tab[1] = t;
    if (s & MTLRenderStageObject) g_m3_tab[3] = t;
    if (s & MTLRenderStageMesh) g_m3_tab[4] = t;
}
static inline void enc_c_table(id e, id t) { if (!g_m3) [(id<MTL4ComputeCommandEncoder>)e setArgumentTable:t]; else g_m3_tab[2] = t; }
static inline void m3_bind_draw(id e) { m3_table_apply(e, 0, g_m3_tab[0]); m3_table_apply(e, 1, g_m3_tab[1]); }
static inline void m3_bind_dispatch(id e) { m3_table_apply(e, 2, g_m3_tab[2]); }
static inline void m3_bind_mesh(id e) { m3_table_apply(e, 1, g_m3_tab[1]); m3_table_apply(e, 3, g_m3_tab[3]); m3_table_apply(e, 4, g_m3_tab[4]); }   // a task / mesh draw: fragment, object, mesh (no vertex stage)
#define BAR_FRAG_ONLY_BITS ((uint32_t)(NVN_BARRIER_ORDER_FRAGMENTS_BIT | NVN_BARRIER_ORDER_FRAGMENTS_TILED_BIT | NVN_BARRIER_INVALIDATE_TEXTURE_BIT | \
    NVN_BARRIER_INVALIDATE_TEXTURE_DESCRIPTOR_BIT | NVN_BARRIER_INVALIDATE_ZCULL_BIT))
static int bar_frag_skip_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_NVN_BAR_FRAG_SKIP"); v = !(e && !strcmp(e, "0")); }
    return v;
}
static inline id<MTL4RenderCommandEncoder> enc_r_begin_pass(MTL4RenderPassDescriptor *d) {   // the draw passes (rp_begin_ex); see barrier_game
    if (!g_rlane) geo_run_flush();
    enc_close_blit();
    g_half_mask_sent = -1;
    gp_pre(d, 'R');   // Metal 3: the sample points go on the pass descriptor before the encoder is made (no-op elsewhere)
    id<MTL4RenderCommandEncoder> e = [g_cb renderCommandEncoderWithDescriptor:d]; fault_enc_pass(e, d);
    int frag_only = g_game_barrier && bar_frag_skip_on() && !(g_game_barrier & ~BAR_FRAG_ONLY_BITS);
    int relaxed = g_last_end_relaxed && (!g_game_barrier || frag_only);
    int full = !relaxed;
    if (g_m3) m3_wait(e, 1, relaxed);
    else full = main_barrier_begin(e, relaxed);
    if (full) g_bar_full++; else g_bar_skip++;
    g_game_barrier = 0;
    enc_r_table(e, g_vt, MTLRenderStageVertex); enc_r_table(e, g_ft, MTLRenderStageFragment); gp_begin(e, 'R', d); return e;
}
static inline void enc_r_end_pass(id e) {
    if (!barrier_game()) { m4_end(e); return; }
    if (g_m3) { m4_end(e); g_last_end_relaxed = 1; return; }   // the fence is updated after the fragment stage either way; the next pass waits before its fragments only (enc_r_begin_pass)
    gp_end(e);
