    for (uint32_t i = 0; ks && seen && i < g_alias.cap; i++) { alias_key k;
        if (!alias_orph_cand(i, held, &k) || !nvn_hm_get(&g_alias_wrote, &k)) continue;
        ks[n] = k; seen[n++] = (uint64_t)(uintptr_t)nvn_hm_get(&g_alias_seen, &k); }
    CFRelease(held);
