        if (!alias_orph_cand(i, held, &k)) continue;
        if (!nvn_hm_get(&g_alias_wrote, &k)) { cache[nc++] = k; continue; }
        const pool_t *p = (const pool_t *)(uintptr_t)k.pool; nvn_texlayout L; nvn_tex_layout(&k.d, &L);
        wbytes += (int64_t)res_bytes((__bridge id)g_alias.vals[i]);
        if (p && p->mem && L.size) wr[nw++] = (cand_t){k, p->mem + k.off, L.size};
    }
    CFRelease(held);
    for (uint32_t j = 0; j < nc; j++) alias_orph_drop(&cache[j], 0);
    pthread_mutex_unlock(&g_smu);
    uint32_t nr = 0;
    for (uint32_t j = 0; j < nw; j++) {   // outside g_smu: the write ledger has its own lock
        uint64_t *runs = NULL, b = 0; int n = gpw_stale(wr[j].mem, wr[j].size, &runs, &b); free(runs);
        if (n == 0) wr[nr++] = wr[j];
    }
    if (nr) { os_unfair_lock_lock(&g_rmu); pthread_mutex_lock(&g_smu); CFMutableSetRef h2 = alias_held(); os_unfair_lock_unlock(&g_rmu);
        for (uint32_t j = 0; j < nr; j++) { void *v = nvn_hm_get(&g_alias, &wr[j].k); uint64_t seen = (uint64_t)(uintptr_t)nvn_hm_get(&g_alias_seen, &wr[j].k);
            if (!v || CFSetContainsValue(h2, v) || (seen && g_fence + 1 - seen < ALIAS_IDLE)) continue;   // taken up again meanwhile
            wbytes -= (int64_t)alias_orph_drop(&wr[j].k, 1); }
        CFRelease(h2); pthread_mutex_unlock(&g_smu); }
    if (g_orph_lv) { pthread_mutex_lock(&g_smu); int64_t d = wbytes - g_orph_noted; g_orph_noted = wbytes; pthread_mutex_unlock(&g_smu); if (d) g_orph_lv->note(g_orph_lv_me, d); }   // attribution: the ledger asks the largest holders first
    free(cache); free(wr);
}
static __unsafe_unretained id serial_get(uint64_t k) { pthread_mutex_lock(&g_smu); __unsafe_unretained id o = hm_get_id(&g_by_serial, &k); pthread_mutex_unlock(&g_smu); return o; }
static void serial_put(uint64_t k, id o) { pthread_mutex_lock(&g_smu); id old = hm_get_id(&g_by_serial, &k); if (old) { if (alias_has(old)) defer_obj_unref(old); else defer_obj_release(old); } hm_put_id(&g_by_serial, &k, o); ser_gen_bump_one(k); pthread_mutex_unlock(&g_smu); }
static void serial_del(uint64_t k) { pthread_mutex_lock(&g_smu); id old = hm_get_id(&g_by_serial, &k); if (old) { if (alias_has(old)) defer_obj_unref(old); else defer_obj_release(old); hm_del_id(&g_by_serial, &k); ser_gen_bump_one(k); } pthread_mutex_unlock(&g_smu); }   // nothing to drop: the texture ID caches stay valid
// Texture serials owned by a live NVN texture object (TextureInitialize until Finalize or re-initialization, hle_nvn.c). Command records and texture pool registrations snapshot the
// texture object (tex_snap in hle_nvn.c, nvn_be_reg_tex), so replay can resolve a texture the game has already finalized: Breath of the Wild records each frame's transient render targets
// (the HUD captures, the 640x360 half-resolution buffers) and finalizes their objects before it submits. Those serials went back into g_by_serial and stayed there for good, as no second
// Finalize comes: about 10 a frame, 200,000 after an hour in the first shrine. A dead serial resolves through g_ghost instead, a small table whose oldest entry goes when a new one comes,
// so a record replayed again soon still finds its texture
enum { NGHOST = 512 };
static nvn_hmap g_tex_live = {.klen = 8};   // serial → (void *)1, under g_smu
static nvn_hmap g_ghost = {.klen = 8}; static uint64_t g_ghost_ring[NGHOST]; static unsigned g_ghost_next; static uint64_t g_ghost_puts;
int nvn_be_tex_is_live(uint64_t ser) { pthread_mutex_lock(&g_smu); int r = nvn_hm_get(&g_tex_live, &ser) != NULL; pthread_mutex_unlock(&g_smu); return r; }   // 这个序号的贴图对象还活着（没 Finalize / 重新初始化）
uint32_t nvn_be_tex_live_n(void) { pthread_mutex_lock(&g_smu); uint32_t n = g_tex_live.n; pthread_mutex_unlock(&g_smu); return n; }   // 活着的贴图对象数（宽屏胶水表满时对照：是游戏真有这么多，还是登记漏还）
static void tp_reg(const tex_t *t);   // upload ahead (with page_count)
static nvn_hmap g_snap_texaddr; static int g_snap_on = -1;   // 即时存档：对象序号 → 游戏里贴图对象的地址（恢复时按地址把 GPU 私有贴图建出来再写回内容）
int s2a_snap_saving(void) __attribute__((weak));   // runtime/src/snapshot.c：即时存档开关的唯一定义处
// 弱链接[nvntest]：s2a_snap_saving（runtime/src/snapsw.c 提供；图形单测不链宿主，链接行按这行放行未定义）
// 弱链接[nvntest]：s2a_snap_arena_get（runtime/src/vawin.c 提供，nvn_snap.inc 用；同上）
// 弱链接[nvntest]：s2a_snap_arena_set（同上）
// 弱链接[nvntest]：s2a_snap_progress（runtime/src/snapshot.c 存档看门狗，nvn_snap.inc 用；同上）
// 弱链接[nvntest]：s2a_snap_conv_fread（runtime/src/snapshot.c 提供，nvn_snap.inc 经 snapfmt.h snap_fread 用：快照布局变了按字段转；同上）
static int snap_on(void) { if (g_snap_on < 0) g_snap_on = s2a_snap_saving ? s2a_snap_saving() : 0; return g_snap_on; }
void nvn_be_tex_init(const tex_t *t) { if (!t->serial) return; atomic_fetch_add(&g_tex_init_n, 1); pthread_mutex_lock(&g_smu); nvn_hm_put(&g_tex_live, &t->serial, (void *)1);
    if (snap_on()) { if (!g_snap_texaddr.klen) nvn_hm_init(&g_snap_texaddr, 8); nvn_hm_put(&g_snap_texaddr, &t->serial, (void *)t); }
    pthread_mutex_unlock(&g_smu); tp_reg(t); }
static void obj_drop(id o) { if (alias_has(o)) defer_obj_unref(o); else defer_obj_release(o); }   // caller holds g_smu
// A submission can resolve more finalized textures than the ring holds (S2Arm 11-05, after upstream PR #1299 commit 2 "A bindless pool churns finalized textures within a submission",
//   MIT, seedds/upstream 9fb44679: about 12,000 finalized descriptors in Ocarina of Time's Kokiri Forest, 18.9 GB resident on the Mac). The ring then evicted a texture that draws already
//   encoded in the same submission use, the next resolution made it again (a packaged one re-uploaded), and every copy stayed alive until the submission's fence. Finalized serials
//   resolved while a submission is encoded (submit thread, g_cb open) are also held in g_ghost_active until it ends: a lookup finds them there after the ring has let them go, and the ring
//   does not drop them early; ghost_finish_submission releases the overflow behind this submission's fence
static __unsafe_unretained id tex_get(uint64_t k) {
    pthread_mutex_lock(&g_smu);
    __unsafe_unretained id o = hm_get_id(&g_by_serial, &k);
    if (!o && g_ghost_active.n) o = hm_get_id(&g_ghost_active, &k);
    if (!o && g_ghost.n && (o = hm_get_id(&g_ghost, &k)) && g_cb && on_sub_thread()) hm_put_id(&g_ghost_active, &k, o);
    pthread_mutex_unlock(&g_smu);
    return o;
}
static void tex_put_locked(uint64_t k, id o) {   // caller owns g_smu
    // Serials from 2^62 up are external textures, never initialized by the game.
    int live = k >= (1ull << 62) || nvn_hm_get(&g_tex_live, &k);
    id active = live ? nil : hm_get_id(&g_ghost_active, &k);
    nvn_hmap *m = live ? &g_by_serial : active && !hm_get_id(&g_ghost, &k) ? &g_ghost_active : &g_ghost;   // evicted from the ring earlier in this submission: replaced where it is held
    id old = hm_get_id(m, &k);
    if (old) { if (old != o) obj_drop(old); }
    else if (m == &g_ghost) {
        uint64_t *slot = &g_ghost_ring[g_ghost_next++ % NGHOST];
        if (*slot) { id ev = hm_get_id(&g_ghost, slot); if (ev && ev != hm_get_id(&g_ghost_active, slot)) obj_drop(ev); hm_del_id(&g_ghost, slot); }   // still used by this submission: dropped when it ends
        *slot = k; g_ghost_puts++;
    }
    hm_put_id(m, &k, o); ser_gen_bump_one(k);
    if (m == &g_ghost && (active || (g_cb && on_sub_thread()))) hm_put_id(&g_ghost_active, &k, o);
}
static void tex_put(uint64_t k, id o) {
    pthread_mutex_lock(&g_smu);
    tex_put_locked(k, o);
    pthread_mutex_unlock(&g_smu);
}
// End of the submission's encoding (nvn_be_sub_commit, before its fence is taken): finalized textures the ring no longer holds are dropped behind this submission's fence, the rest stay in the ring.
//   The texture ID caches resolved them; g_ser_gen moves so they resolve again
static uint64_t g_ghost_kept;   // textures held past their ring eviction until their submission ended
static uint64_t g_ghost_shared;   // finalized serials resolved straight to a shared texture (tex_mtl_)
static void ghost_finish_submission(void) {
    pthread_mutex_lock(&g_smu);
    int dropped = 0;
    for (uint32_t i = 0; i < g_ghost_active.cap && g_ghost_active.n; i++) {
        void *v = g_ghost_active.vals[i]; if (!v) continue;
        if (nvn_hm_get(&g_ghost, g_ghost_active.keys + (size_t)i * g_ghost_active.klen) != v) { obj_drop((__bridge id)v); dropped++; }
    }
    if (g_ghost_active.n) nvn_hm_clear(&g_ghost_active, hm_rel);
    if (dropped) { ser_gen_bump_all(); g_ghost_kept += (uint64_t)dropped; }
    pthread_mutex_unlock(&g_smu);
}
// NVN ⇄ GL 纹理互操作（nvnTextureBuilderSetGLTextureName；11-03 火影羁绊：Scaleform 往 GL 纹理画界面，游戏按纹理名建 NVN 纹理，场景先拷进去、界面画完再拷回 NVN 画面）。
//   真机两边是同一块显存：NVN 纹理的格式 / 尺寸 / 级数取 GL 纹理的（构建器上那几项不看），存储就是 GL 那张。本层把 GL 层交出的 MTLTexture 登记在这个序号下，
//   NVN 的拷贝 / 采样 / 渲染目标解析（tex_mtl）直接拿到它；GL 内部格式换成 NVN 格式后，按 NVN 格式该用的 Metal 格式核一遍，对不上不登记（报红，免得按错格式解释同一份字节）。
//   原先只记名字，NVN 纹理格式 0、0×0，「texture format 0 has no Metal equivalent」，两次拷贝都落空，界面画不到屏上
id<MTLTexture> gl_tex_export(uint32_t name, uint32_t *internal, uint32_t *levels);   // gfx/gl/gl_tex.m
static int gl_internal_to_nvn(uint32_t f) {
    switch (f) {
        case 0x8058: return NVN_FORMAT_RGBA8; case 0x8C43: return NVN_FORMAT_RGBA8_SRGB; case 0x881A: return NVN_FORMAT_RGBA16F; case 0x8814: return NVN_FORMAT_RGBA32F;
        case 0x8229: return NVN_FORMAT_R8; case 0x822B: return NVN_FORMAT_RG8; case 0x8059: return NVN_FORMAT_RGB10A2; case 0x8C3A: return NVN_FORMAT_R11G11B10F;
        case 0x8D62: return NVN_FORMAT_RGB565; case 0x81A5: return NVN_FORMAT_DEPTH16; case 0x81A6: return NVN_FORMAT_DEPTH24; case 0x8CAC: return NVN_FORMAT_DEPTH32F;
        case 0x88F0: return NVN_FORMAT_DEPTH24_STENCIL8;
    }
    return 0;
}
int nvn_be_tex_from_gl(tex_t *t, uint32_t gl_name) { @autoreleasepool {
    uint32_t internal = 0, levels = 0; id<MTLTexture> img = gl_tex_export(gl_name, &internal, &levels);
    if (!img) { RED_ONCE(137, "nvnTextureBuilderSetGLTextureName: GL texture %u has no 2D storage (not a texture, not 2D, or level 0 undefined); the NVN texture stays empty (first case)", gl_name); return 0; }
    int f = gl_internal_to_nvn(internal); uint32_t pf = 0; uint8_t swz[4];
    if (!f || !nvn_fmt_to_mtl((uint32_t)f, &pf, swz) || pf != (uint32_t)img.pixelFormat) {
        RED_ONCE(138, "nvnTextureBuilderSetGLTextureName: GL texture %u internal format %#x (Metal %lu) has no NVN format stored the same way; the NVN texture stays empty (first case)", gl_name, internal, (unsigned long)img.pixelFormat);
        return 0;
    }
    t->d.target = NVN_TEXTURE_TARGET_2D; t->d.format = f; t->d.width = (uint32_t)img.width; t->d.height = (uint32_t)img.height; t->d.depth = 1; t->d.levels = levels; t->d.samples = 0; t->d.stride = 0;
    tex_put(t->serial, img);
    static int once; if (!once++) MLOG("GL texture interop: NVN texture ser=%llu is GL texture %u (%ux%u, format %#x, %u levels), same storage", (unsigned long long)t->serial, gl_name, t->d.width, t->d.height, f, levels);
    return 1;
}}
// Host record of a packaged texture: the current MTLTexture, the upload stamp, and the global write generation at the last check
// spare: the texture the last re-upload replaced, kept resident and written by the next re-upload once the GPU has passed spare_fence (a texture the CPU rewrites every frame, a movie frame,
// alternates between two textures instead of allocating one per frame: Link's Awakening's title movie made and freed an 8 MB texture a frame)
static void ph_free(uint64_t *ph, uint32_t n);
@interface NvPkg : NSObject { @public id<MTLTexture> tex, spare, view; uint64_t stamp, seen, hash, spare_fence, vgen, vseen, check_epoch; const void *span; int sparse, vbase; uint64_t *ph, *pgpu; uint32_t nph; int pre; uint64_t pre_fp; void *stex; uint64_t lseq; uint64_t (*runs)[2]; int nruns; uint8_t tex_shared; } @end   // tex_shared: tex is also the sharing table's (gpw_mark); the table's removal is then the NvPkg's own   // lseq / runs / nruns：稀疏贴图上次整段走页表时的映射日志序号与背后的物理段（nruns 0 = 没缓存，-1 = 段太多不缓存；马车世界缺口 ①，pkg_sparse_clean）   // hash: full hash of the uploaded content under DM_NVN_DIRTYCHECK; span: its tracked range (nvn_dirty_span, NULL = untracked);
static void evict_note(id obj) {
    id o = [obj isKindOfClass:[NvPkg class]] ? ((NvPkg *)obj)->tex : obj;
    id<MTLTexture> m = [o conformsToProtocol:@protocol(MTLTexture)] ? o : nil; while (m.parentTexture) m = m.parentTexture;
    if (!m) return;
    os_unfair_lock_lock(&g_evict_lk); if (!g_evict_w) g_evict_w = [NSHashTable weakObjectsHashTable]; [g_evict_w addObject:m]; g_evict_n++; os_unfair_lock_unlock(&g_evict_lk);
}
// sparse: in a sparse virtual pool, read through its page table (hle_nvn.c nvn_sparse_*), vgen the page table's generation at the upload and vseen at the last look; view: what it is bound as (sparse_view)
static void stex_pkg_free(void *s);   // nvn_stex.inc 胶水（pkg_upload_ 之前）：页还回堆
// stex：放置式稀疏贴图（nvn_stex.inc）背着的大稀疏贴图：tex 就是它的贴图，原地增量同步、不换
@implementation NvPkg
- (void)dealloc { if (!tex_shared) res_remove(tex); if (spare) res_remove(spare); ph_free(ph, nph); free(pgpu); free(runs); if (stex) stex_pkg_free(stex); }
@end
static id pkg_tex_of(id o) { return [o isKindOfClass:[NvPkg class]] ? ((NvPkg *)o)->tex : nil; }
static int pkg_unshare(id o) {
    int n = 0; nvn_hmap *hm[] = {&g_by_serial, &g_ghost, &g_ghost_active};
    for (int t = 0; t < 3; t++) for (uint32_t i = 0; i < hm[t]->cap; i++) { id v = (__bridge id)hm[t]->vals[i];
        if (v && [v isKindOfClass:[NvPkg class]] && ((NvPkg *)v)->tex == o) { ((NvPkg *)v)->tex_shared = 0; n = 1; } }
    return n;
}
static uint64_t g_pkg_uploads, g_pkg_reuploads, g_pkg_miss, g_pkg_same, g_pkg_gpu_writes, g_pkg_gpu_kept, g_pkg_partial;
// pgpu (S2Arm 10-25): per host page, the dirty-page generation when the GPU last wrote the texture's bytes there (a copy or clear into it; nvn_dirty_now at encoding, which is the game's submission).
// The replay's GPU writes reach the host texture, never guest memory, so a whole re-upload from guest memory would undo them. Who wrote a page last decides: written by the CPU after the GPU
// (page generation > pgpu) is uploaded, written before it is left as the GPU made it. Pages are re-uploaded as the texel rectangles their bytes hold (tex_bytes_rects), into the same texture
// ph / nph (S2Arm 10-25): a hash of the texture's bytes in each host page of its storage, taken at the upload between the stamp and the read (pkg_upload_). A written page is not a changed texture:
// host pages are 16 KB on Apple systems and NVN resources only 4 KB aligned, so a page holds the edge of a texture and other data the CPU rewrites every frame. Mario Kart 8 Deluxe re-uploaded
// whole textures on such pages (a 2048x2048 one of 32 MB among them) about 72,000 times in a run, 2,000 of 2,000 with the same bytes (DM_NVN_DIRTYCHECK), and the phone ran at 4.4 W instead of
// 2.4 - 3.4. Before a re-upload tex_mtl_ hashes the texture's bytes in the written pages only and keeps the upload when they all match
// #674: the first upload's hashes are taken on a background queue (ph_queue), not on the submit thread. The first CPU read of a texture's storage at the host's address faults once per
//   host page: the game filled it through another mapping (an alias of the same pages, or a GPU copy), so this address has no page table entries yet. 0400486024DEC000 loading a scene
//   uploads 643 textures (332 MB, 21,900 pages) in one frame and their hashes took 124 ms there, 22,000 page faults and 83 ms of it in the kernel; the same pages hashed again took 24 ms.
//   The faults serialise in the kernel (hashing on several cores at once took longer, 150 ms), so the work is moved off the submit thread, not split.
//   ph then holds nph + 1 words: the last is the state (PH_PEND / PH_OK / PH_BAD). The background hash runs after the stamp, but possibly after the GPU already read the texture: a page
//   written in between would put the new bytes in the hash and a later check would keep the old upload. So when it is done it asks the dirty-page tracking whether any page was
//   written since the stamp, and if so the hashes are PH_BAD (the next check re-uploads the whole texture, as without hashes). Re-uploads still hash on the submit thread: a texture
//   sharing a page with data the CPU rewrites every frame (the Mario Kart case above) would otherwise often see its background hash spoiled and never get the same-bytes skip.
//   Everything that reads or frees ph waits for its hash first (ph_usable / ph_free); a pool waits for all of them before it goes (nvn_be_pool_del: the hash reads its memory)
enum { PH_OK = 0, PH_PEND = 1, PH_BAD = 2 };
static dispatch_queue_t ph_queue(void) {
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.ph", s2a_qos_queue_attr(DISPATCH_QUEUE_SERIAL, S2A_QOS_UPLOAD_HASH)); });
    return q;
}
static _Atomic uint64_t *ph_state(uint64_t *ph, uint32_t n) { return (_Atomic uint64_t *)&ph[n]; }
static int ph_usable(uint64_t *ph, uint32_t n) {   // waits for a background hash still running; 0 = no usable hashes (none taken, or spoiled by a write)
    if (!ph) return 0;
    if (atomic_load_explicit(ph_state(ph, n), memory_order_acquire) == PH_PEND) dispatch_sync(ph_queue(), ^{});   // serial queue: everything queued before is done
    return atomic_load_explicit(ph_state(ph, n), memory_order_acquire) == PH_OK;
}
static void ph_free(uint64_t *ph, uint32_t n) { if (ph) { (void)ph_usable(ph, n); free(ph); } }
static uint64_t g_pfv_upgrades;
// DM_NVN_DIRTYCHECK=1 (diagnostic, compared against ground truth): fully hash the pool content on every use; changed but not detected by dirty-page tracking = a missed detection
static int dirtycheck(void) { static int v = -1; if (v < 0) v = getenv("DM_NVN_DIRTYCHECK") != NULL; return v; }
static uint64_t full_hash(const uint8_t *m, uint64_t n) { uint64_t h = 1469598103934665603ull; for (uint64_t i = 0; i < n; i++) h = (h ^ m[i]) * 1099511628211ull; return h; }
// GPUs without BC compressed formats (A15 / A16 and older, MTLDevice.supportsBCTextureCompression = NO): BC textures are created in the decompressed format and decoded at upload /
// buffer→texture copy time. Ported from MacNativeGames (MIT, games/wonder/third_party/d2r_gfx/gfx/nvn/nvn_mtl.m no_bc / bc_unpack); decoding in tex/nvn_bcdec.c (bcdec).
// Without it a BC game draws nothing on those phones, and the iOS 18 floor for direct mode means little. DM_TEST_NO_BC=1 forces the path on any machine (Mac checks)
static int no_bc(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_TEST_NO_BC"); v = (e && *e && strcmp(e, "0")) || ![g_dev supportsBCTextureCompression];
        if (v) MLOG("GPU without BC compressed formats%s: BC textures are created decompressed and decoded at upload", e && *e && strcmp(e, "0") ? " (test switch DM_TEST_NO_BC)" : ""); }
    return v;
}
// Textures the host stores in another format than the game's: BC on a GPU without BC (decompressed), and the formats it expands (nvn_fmt_expanded: three components into four,
//   *_UI2F / *_I2F into float, RGB10A2 signed into 16 bits; 缺口族 30). Both are deswizzled on the CPU and converted into the staging area (fmt_decode), read back never
static int fmt_unpack(uint32_t nvn_fmt, uint32_t *pf, int *bpp) { return nvn_fmt_expanded(nvn_fmt, pf, bpp) || (no_bc() && nvn_bc_unpacked(nvn_fmt, pf, bpp)); }
static int fmt_decode(uint32_t f, const uint8_t *src, size_t pitch, uint32_t w, uint32_t h, uint8_t *dst, size_t dpitch) {
    return nvn_fmt_expanded(f, NULL, NULL) ? nvn_fmt_expand(f, src, pitch, w, h, dst, dpitch) : nvn_bc_decode(f, src, pitch, w, h, dst, dpitch);
}
static void bc_note(uint32_t f, const char *where) {   // the first decode of each BC format, one line each: shows which BC formats a game really uploads on a GPU without BC
    static _Atomic uint32_t seen; uint32_t bit = f >= 0x41 && f <= 0x50 ? 1u << (f - 0x41) : 0;
    if (bit && !(atomic_fetch_or(&seen, bit) & bit)) MLOG("no BC: first texture in NVN format %#x decoded (%s)", f, where);
