// No BC: BC1–5, BC6H and BC7 are decompressed on the GPU (A16 logs in MacNativeGames: CPU deswizzle + CPU decompression took over 300 ms in one frame). Ported from MacNativeGames (MIT, commit 84eebcd0985c,
// nvn_mtl.m k_bcd_msl / bcd_fmt / bcd_pso / up_dec): the GPU deswizzle writes the compressed blocks into the staging area; at flush the kernel bcd decodes them into the texture, one thread per block,
// through a 2D view in the decompressed format (an sRGB texture is written with its raw values through an RGBA8Unorm view). 3D textures stay on the CPU (nvn_bcdec.c).
// The kernel decodes BC1–5 in float like the hardware does, so a texel may differ from bcdec by one level; BC7 and BC6H are integer and equal bcdec (S2Arm #582; t_bcd_gpu measures all)
#include "../tex/nvn_bcd_msl.h"   // k_bcd_msl: the kernel bcd (one header shared with graphics/nvn/tests/t_bcd_gpu.m)
static int bcd_fmt(uint32_t f) {   // NVN format → the kernel's fmt; 0 = not decoded on the GPU (not BC)
    switch (f) { case 0x41: case 0x42: case 0x45: case 0x46: return 1; case 0x43: case 0x47: return 2; case 0x44: case 0x48: return 3;
                 case 0x49: return 4; case 0x4a: return 5; case 0x4b: return 6; case 0x4c: return 7; case 0x4d: case 0x4e: return 8; case 0x50: return 9; case 0x4f: return 10; default: return 0; }
}
static id<MTLComputePipelineState> bcd_pso(void) {
    static id<MTLComputePipelineState> ps; static int failed;
    if (!ps && !failed) { NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(k_bcd_msl) options:nil error:&e]; id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"bcd"] : nil;
        ps = fn ? [g_dev newComputePipelineStateWithFunction:fn error:&e] : nil;
        if (!ps) { failed = 1; MLOG("【红】 no BC: the GPU decompression pipeline cannot be built (%s); BC1–7 fall back to the CPU", e.localizedDescription.UTF8String); } else MLOG("no BC: BC1–7 are decompressed on the GPU"); }
    return ps;
}
// S2Arm #582: bcd_pso compiles k_bcd_msl from source (newLibraryWithSource, about 230 ms on an M4 each launch, the system shader cache does not keep it); built at first use it sat on the
//   upload of the first BC texture. On a GPU without BC mtl_init starts the build in the background (bcd_prewarm); a use waits for it (bcd_ready), so ps / failed are only written on that queue
//   and only read after the wait. With BC (or before mtl_init) nothing is started and bcd_ready is bcd_pso
static dispatch_group_t g_bcd_pre;   // the background build, NULL = not started
static void bcd_prewarm(void) { if (!no_bc() || g_bcd_pre) return; g_bcd_pre = dispatch_group_create(); dispatch_group_async(g_bcd_pre, s2a_qos_global(S2A_QOS_SHADER_PREFETCH), ^{ (void)bcd_pso(); }); }
static id<MTLComputePipelineState> bcd_ready(void) { if (g_bcd_pre) dispatch_group_wait(g_bcd_pre, DISPATCH_TIME_FOREVER); return bcd_pso(); }
// GPU decompression applies (the texture is made shader-writable with format views; the upload still needs pool-backed storage, otherwise it decodes on the CPU)
static int bc_gpu_dec(const tex_t *t) { uint32_t upf; int ubpp; return fmt_unpack(t->d.format, &upf, &ubpp) && t->d.target != 2 && bcd_fmt(t->d.format) && bcd_ready(); }
typedef struct { __unsafe_unretained id<MTLBuffer> src, params; size_t poff; uint32_t bw, bh; __unsafe_unretained id<MTLTexture> view, base; } up_dec;   // view / base: held by g_up_texs within the batch, the view afterwards by defer_obj_unref until the GPU finishes
static up_dec *g_up_decs; static int g_nup_decs, g_up_deccap;
#include "nvn_rscale.inc"   // S2Arm internal resolution (S2A_RES_SCALE): state, eligibility, canvas sizes
// Multisample count the GPU can make: NVN games ask for 8x (a novel game's render targets on an iPhone 13 Pro Max, #903), which Apple's A15 and earlier iPhone GPUs do not
//   support (they take 1 / 2 / 4); an unsupported count is a Metal validation assertion that aborts the process. Step down to the largest supported count not above the
//   request. Render passes, pipelines and resolves already take the count from the Metal texture (g_pass.samples), so they follow; a shader reading sample index >= the
//   new count reads an undefined sample (logged once)
static NSUInteger mtl_samples_supported(const tex_t *t) {
    NSUInteger want = t->d.samples ? t->d.samples : 1, n = want;
    while (n > 1 && ![g_dev supportsTextureSampleCount:n]) n >>= 1;
    if (n != want) RED_ONCE(187, "multisample count %lu not supported by this GPU: created with %lu samples (first case ser=%llu %u×%u)", (unsigned long)want, (unsigned long)n,
                            (unsigned long long)t->serial, t->d.width, t->d.height);
    return n;
}

#include "../../texture_extent.inc"
// 超上限缩建（nvn_rscale.inc 文件头）：GPU 写的二维 / 二维数组 / 矩形贴图边长超过设备上限时按 上限 ÷ 长边 缩建，返回这个比例（1 = 不缩建）。
//   多重采样、块压缩、深度 / 层数 / 级数也超限的不走这条（照旧红行、建不出）
static double rs_fit_tex(const tex_t *t) {
    if (t->d.target != NVN_TEXTURE_TARGET_2D && t->d.target != NVN_TEXTURE_TARGET_2D_ARRAY && t->d.target != NVN_TEXTURE_TARGET_RECTANGLE) return 1.0;
    if (t->d.samples > 1 || fmt_compressed(t->d.format) || t->d.depth > 2048 || t->d.levels > 15) return 1.0;
    return rs_fit(t->d.width, t->d.height);
}
static MTLTextureDescriptor *tex_desc_fit(const tex_t *t, int packaged, double fit);
static MTLTextureDescriptor *tex_desc(const tex_t *t, int packaged) { return tex_desc_fit(t, packaged, 1.0); }
static MTLTextureDescriptor *tex_desc_fit(const tex_t *t, int packaged, double fit) {   // fit < 1：超上限缩建，宽高按 ⌈边 × fit⌉（rs_fit_tex）
    uint32_t pf = 0; uint8_t swz[4];
    if (!nvn_fmt_to_mtl(t->d.format, &pf, swz) || !pf) { RED_ONCE(0, "texture format %#x has no Metal equivalent (first case)", t->d.format); return nil; }
    { uint32_t upf; int ubpp; if (fmt_unpack(t->d.format, &upf, &ubpp)) pf = upf; }   // stored in another format (fmt_unpack): that format (a decompressed BC is still never a render target: fmt_compressed below)
    // Metal's limits: 16384 in 2D, 2048 in 3D, 2048 array layers; beyond them Metal aborts the process on an assertion, so they are caught here with a red line
    if (rs_up(t->d.width, fit) > 16384 || rs_up(t->d.height, fit) > 16384 || t->d.depth > 2048 || t->d.levels > 15) { RED_ONCE(71, "texture size exceeds Metal limits: %u×%u×%u levels %u format %#x target %d (first case ser=%llu)", t->d.width, t->d.height, t->d.depth, t->d.levels, t->d.format, t->d.target, (unsigned long long)t->serial); return nil; }
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.pixelFormat = (MTLPixelFormat)pf;
    tex_extent extent = tex_extent_at(t, nil, 0, 0);
    d.width = extent.physical.width; d.height = extent.physical.height; d.depth = 1; d.arrayLength = 1;
    d.mipmapLevelCount = t->d.levels ? t->d.levels : 1;
    switch (t->d.target) {
        // 1D / 1D array are created as one-row 2D / 2D array textures: translated shaders never declare texture1d (0 in all five games' libraries) and always sample them as 2D; a Metal 1D texture bound to a texture2d argument is a type mismatch with undefined reads.
        // Super Mario 3D World + Bowser's Fury's material shaders sample 64x1 R32F 1D lookup tables heavily every frame (on Maxwell a 2D sample of a 1D texture reads that one row)
        case 0: d.textureType = MTLTextureType2D; d.height = 1; break;
        case 2: d.textureType = MTLTextureType3D; d.depth = t->d.depth; break;
        case 3: d.textureType = MTLTextureType2DArray; d.arrayLength = t->d.height; d.height = 1; break;
        case 4: d.textureType = MTLTextureType2DArray; d.arrayLength = t->d.depth; break;
        case 5: d.textureType = MTLTextureType2DMultisample; d.sampleCount = mtl_samples_supported(t); d.mipmapLevelCount = 1; break;
        case 6: d.textureType = MTLTextureType2DMultisampleArray; d.sampleCount = mtl_samples_supported(t); d.arrayLength = t->d.depth; d.mipmapLevelCount = 1; break;
        // Cube textures are created as 6-layer 2D arrays and sampled through cube / cube array views made by tex_fit: Metal only allows cube array views of a 2D array base texture (not of a cube base).
        // The Legend of Zelda: Breath of the Wild has 1512 shaders that sample the environment light probes as a cube array while a single cube texture is bound (texture ID 1064 onwards): with mismatched types the reads are undefined, and every lit surface came out black
        case 8: d.textureType = MTLTextureType2DArray; d.arrayLength = 6; break;
        // Cube arrays likewise, as a 2D array of all their faces: NVN gives a cube array's depth in layer-faces (a multiple of 6), where a Metal cube array's arrayLength counts cubes.
        // Created as a cube array with arrayLength = depth, DRAGON QUEST XI S's 510-face one (85 cubes, made when its prologue movie ends) asked for 510 cubes, past Metal's 341, and Metal aborted the process
        case 9: d.textureType = MTLTextureType2DArray; d.arrayLength = t->d.depth; break;
        case 10: RED_ONCE(1, "buffer textures (TARGET_BUFFER) not implemented"); return nil;
        default: d.textureType = MTLTextureType2D; break;
    }
    if (fit != 1.0) { d.width = rs_up(d.width, fit); d.height = rs_up(d.height, fit); }   // 超上限缩建：只有二维 / 二维数组 / 矩形走到这里（rs_fit_tex）
    // Mip count clamped to what the dimensions allow, as Ryujinx TexturePool.ClampLevels (log2 of the largest edge + 1; depth only for 3D, layers never):
    //   NVN accepts a level count past the dimensions (Tomodachi Life asks 15 levels for a 128×256 render target), Metal aborts the process on it (validateWithDevice)
    { NSUInteger mx = MAX(d.width, d.textureType == MTLTextureType3D ? MAX(d.height, d.depth) : d.height), ml = 1; while (mx >>= 1) ml++;
      if (d.mipmapLevelCount > ml) d.mipmapLevelCount = ml; }
    d.storageMode = MTLStorageModePrivate;   // Render targets and assets both go in GPU private storage (lossless compression available)
    // Render-target usage on every uncompressed texture, packaged ones too: a game may draw into storage it first filled from the CPU, and adding the usage later is a whole-texture
    //   copy (tex_upgrade). Made without it, one Switch 2 session upgraded 30k-55k packaged textures, mostly R8 / R16F (#1634). On Apple GPUs the usage costs no memory
    //   (allocatedSize and heap size equal with and without it across R8 / R16 / RG8 / RGBA8 / RGBA16F, 64x64 to 1920x1080, with and without mips, M5 Max)
    d.usage = MTLTextureUsageShaderRead | (fmt_compressed(t->d.format) ? 0 : MTLTextureUsageRenderTarget)
            | (t->d.flags & NVN_TEXTURE_FLAGS_IMAGE ? MTLTextureUsageShaderWrite : 0)   // Image usage: shader-writable (compute kernels generating the 3D color lookup table, etc.
            | (bc_gpu_dec(t) ? MTLTextureUsageShaderWrite | MTLTextureUsagePixelFormatView : 0)   // no BC, decoded on the GPU: the kernel bcd writes it (an sRGB one through an RGBA8Unorm view)
            | (pf == MTLPixelFormatRGB9E5Float && !packaged ? MTLTextureUsagePixelFormatView : 0)   // RGB9E5 render targets written through R32UI views (04008E001F098000 packs its HDR color itself):
            //   without the usage the view cannot be attached (rt_view_fmt falls back to the base format) and the packed words were drawn as RGB9E5 floats, the whole picture red.
            //   Given at creation, like depth-stencil below: tex_upgrade_pfv at attach time would recreate a render target in use
            | (pf == MTLPixelFormatDepth32Float_Stencil8 ? MTLTextureUsagePixelFormatView : 0);   // Depth-stencil: the stencil is read through an X32_Stencil8 view, which Metal allows only with the format-view usage
            // (Apple GPUs read it right without, but the Metal validation layer aborts the process on the first such view). Given at creation: upgrading when the view first appears recreated the depth buffer in use
    return d;
}
// In-place upgrade: when the original texture was not created with PixelFormatView (off by default, to keep Apple GPU lossless compression) but a different-format view is needed, create a new one with the original spec + PixelFormatView, copy over every slice × level, and replace the registration.
// Count: across the 4 screens character select / camp / wilderness / combat, 17473 textures needed a different-format view 0 times, so this is a fallback and does not rely on predicting which textures need it
// The same upgrade adds render-target usage for a whole-level clear (clear_tex) of a texture made without it: Monster Hunter Rise clears a 32x80 packaged one
// macOS 27 on M5 Pro omits ShaderAtomic from texture.usage even when the
// descriptor has it. Remember successful creations by object lifetime; later
// format-view upgrades must preserve the declaration too.
static NSHashTable<id<MTLTexture>> *g_atomic_images;
static pthread_mutex_t g_atomic_mu = PTHREAD_MUTEX_INITIALIZER;
static int tex_atomic_usage(id<MTLTexture> t) {
    if (t.usage & MTLTextureUsageShaderAtomic) return 1;
    pthread_mutex_lock(&g_atomic_mu); int known = [g_atomic_images containsObject:t]; pthread_mutex_unlock(&g_atomic_mu);
    return known;
}
static void tex_note_atomic(id<MTLTexture> t) {
    pthread_mutex_lock(&g_atomic_mu);
    if (!g_atomic_images) g_atomic_images = [NSHashTable weakObjectsHashTable];
    [g_atomic_images addObject:t];
    pthread_mutex_unlock(&g_atomic_mu);
}
// An RGBA8 texture a shader binds as an R32 integer image with atomics (S2Arm 11-05, after upstream PR #1312, MIT, "Atomic reinterpretation of RGBA8"): Metal takes the atomic
//   usage only on R32Uint / R32Sint storage, even through a format view. On the Switch the image format decides how the texel's bits are read, so the same 32 bits are the RGBA8
//   texel and the integer. A private, single-sample 2D RGBA8 texture is upgraded to R32 storage with the atomic usage, and an RGBA8 view of it takes the texture's place: sampling,
//   rendering and copies go through the view, the atomics through the R32 storage, all on the same bytes. Packaged textures (re-uploaded from guest memory) stay as they are
static int tex_rgba_atomic_alias(id<MTLTexture> base) {
    return base.pixelFormat == MTLPixelFormatRGBA8Unorm && base.textureType == MTLTextureType2D && base.sampleCount == 1 && base.storageMode == MTLStorageModePrivate
        && !base.buffer && !base.parentTexture && !base.isSparse;
}
static int pf_r32i(MTLPixelFormat pf) { return pf == MTLPixelFormatR32Uint || pf == MTLPixelFormatR32Sint; }
// An sRGB / linear view tex_mtl_ made of its twin's texture (srgb_twins), known by the mark set where it is made, not by its shape: an external texture registered as a view of the
//   other format of the pair (mtl_ext_tex) looked the same, was dropped as stale with no NVN descriptor to make it again, and the present got no texture (t_present_settings srgb-plane)
static void srgb_twin_mark(id<MTLTexture> v) { if (v) objc_setAssociatedObject(v, &g_twin_view_key, (__bridge id)kCFBooleanTrue, OBJC_ASSOCIATION_ASSIGN); }
static int srgb_twin_view(id o) { return o && objc_getAssociatedObject(o, &g_twin_view_key) != nil; }
static int stex_backed(id<MTLTexture> t);   // 放置式 / 稀疏贴图（nvn_stex.inc 胶水）
// 同一贴图反复升级诊断（D-67FG / D-6A9G / D-XJNP：同一 serial 一局升「可写」3–5 万次，每次新建 + 整张拷贝）：按 serial 记上次升级出的那张，
//   再升时判是哪条路把它丢了——序号表里还是它、调用方却拿着旧的（另一层缓存没跟上）；序号表里换成了别的贴图（重建 / 重传）；预排布贴图（NvPkg）重传换了一张。
//   第 3 次起每个 serial 记一行红（全程至多 16 个 serial），之后不再记；表 64 格按 serial 取模覆盖，只存指针值作比较，不持有对象
static struct { uint64_t ser, n; uintptr_t up; } g_tupd[64]; static pthread_mutex_t g_tupd_mu = PTHREAD_MUTEX_INITIALIZER; static int g_tupd_red;
// 序号表里这个 serial 底下那张贴图（NvPkg 取它的 tex；视图取到底图，sRGB / 线性双生视图本身就是持有者）
static uintptr_t upd_under(id h, int *pkg) {
    *pkg = [h isKindOfClass:[NvPkg class]]; id<MTLTexture> x = *pkg ? ((NvPkg *)h)->tex : (id<MTLTexture>)h;
    while (!*pkg && x.parentTexture && !srgb_twin_view(x)) x = x.parentTexture;
    return (uintptr_t)(__bridge void *)x;
}
// pre：升级前序号表里底下那张；post：升级后序号表里底下那张
static void tex_upgrade_diag(const tex_t *t, id holder, uintptr_t pre, int pkg, id<MTLTexture> asked, MTLTextureUsage add, uintptr_t post) {
    pthread_mutex_lock(&g_tupd_mu);
    unsigned i = (unsigned)(t->serial % 64); uintptr_t last = g_tupd[i].ser == t->serial ? g_tupd[i].up : 0;
    if (g_tupd[i].ser != t->serial) { g_tupd[i].ser = t->serial; g_tupd[i].n = 0; }
    uint64_t n = ++g_tupd[i].n; g_tupd[i].up = post;
    int say = n == 3 && last && g_tupd_red < 16; if (say) g_tupd_red++;
    pthread_mutex_unlock(&g_tupd_mu);
    if (!say) return;
    const char *why = !holder ? "序号表里已没有这个 serial（被删 / 淘汰后重建）"
                    : pre == last ? "序号表里还是上次升级出的那张，调用方却拿着旧的（另一层缓存没跟上）"
                    : pkg ? "预排布贴图（NvPkg）重传换了一张，没带上升级过的用途"
                    : "序号表里换成了别的贴图（重建 / 别名表换了）";
    MLOG("【红】同一贴图第 %llu 次升级 ser=%llu：%s；持有者 %s，调用方给的用途 %#lx、要加 %#lx，格式 %lu %ux%u 标志 %#x（D-67FG 一类）",
         (unsigned long long)n, (unsigned long long)t->serial, why, pkg ? "NvPkg" : holder ? (((id<MTLTexture>)holder).parentTexture ? "视图" : "贴图") : "无",
         (unsigned long)asked.usage, (unsigned long)add, (unsigned long)asked.pixelFormat, t->d.width, t->d.height, t->d.flags);
}
static id<MTLTexture> tex_upgrade(const tex_t *t, id<MTLTexture> asked, MTLTextureUsage add, MTLPixelFormat view_pf) {
    id holder = tex_get(t->serial); int upd_pkg; uintptr_t upd_pre = upd_under(holder, &upd_pkg);   // 反复升级诊断（tex_upgrade_diag）
    // The serial holds an sRGB / linear view of the asked texture, or the asked texture is that view (upstream reference implementation, MIT, 92f223a7): the parent is upgraded and the
    //   view made again on it, so the pair keeps sharing its bytes
    id<MTLTexture> view = srgb_twin_view(holder) && (holder == asked || ((id<MTLTexture>)holder).parentTexture == asked) ? holder : nil;
    id<MTLTexture> base = view ? view.parentTexture : asked;
    if (stex_backed(base)) { RED_ONCE(204, "sparse-backed texture ser=%llu needs usage %#lx / a format view %lu it was not made with: not upgraded (a copy would take its whole size)", (unsigned long long)t->serial, (unsigned long)add, (unsigned long)view_pf); return asked; }
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.textureType = base.textureType; d.pixelFormat = base.pixelFormat; d.width = base.width; d.height = base.height; d.depth = base.depth;   // Keep the original format, only add the format-view usage
    d.arrayLength = base.arrayLength; d.mipmapLevelCount = base.mipmapLevelCount; d.sampleCount = base.sampleCount;
    d.storageMode = base.storageMode; d.cpuCacheMode = base.cpuCacheMode; d.hazardTrackingMode = base.hazardTrackingMode;
    d.resourceOptions = base.resourceOptions; d.usage = base.usage | add | (tex_atomic_usage(base) ? MTLTextureUsageShaderAtomic : 0);
    // A texture-buffer view must retain its pool storage: copying it to a new
    // texture would disconnect native atomics from the old IMGA / buffer reads.
    id<MTLTexture> upgraded = nil, root = nil;
    if ((add & MTLTextureUsageShaderAtomic) && !pf_r32i(base.pixelFormat)) {   // RGBA8 bound for integer atomics (tex_rgba_atomic_alias): R32 storage, an RGBA8 view in its place
        if (!tex_rgba_atomic_alias(base) || !pf_r32i(view_pf) || [holder isKindOfClass:[NvPkg class]]) return asked;   // the caller reports it
        d.pixelFormat = view_pf; d.usage |= MTLTextureUsagePixelFormatView;
        if ((root = [g_dev newTextureWithDescriptor:d])) {
            upgraded = [root newTextureViewWithPixelFormat:base.pixelFormat];
            if (upgraded) { tex_note_atomic(root); res_add(root); objc_setAssociatedObject(upgraded, &g_atomic_root_key, root, OBJC_ASSOCIATION_RETAIN_NONATOMIC); }
        }
    } else upgraded = base.buffer ? [base.buffer newTextureWithDescriptor:d offset:base.bufferOffset bytesPerRow:base.bufferBytesPerRow]
                                  : [g_dev newTextureWithDescriptor:d];
    if (!upgraded) { RED_ONCE(45, "texture upgrade failed ser=%llu format %lu → %lu usage %#lx", t->serial, (unsigned long)base.pixelFormat, (unsigned long)view_pf, (unsigned long)d.usage); return asked; }
    if (!root && (d.usage & MTLTextureUsageShaderAtomic)) tex_note_atomic(upgraded);
    if (!root) res_add(upgraded);
    { NvRsInfo *ri = rs_info(base); if (ri) rs_set_info(upgraded, ri->state, ri->cw, ri->ch, ri->s); }   // S2Arm internal resolution: same size, same record (nvn_rscale.inc)
    id<MTL4ComputeCommandEncoder> b = base.buffer ? nil : blit();
    NSUInteger slices = base.textureType == MTLTextureType3D ? 1 : base.arrayLength * (base.textureType == MTLTextureTypeCube || base.textureType == MTLTextureTypeCubeArray ? 6 : 1);
    for (NSUInteger l = 0; !base.buffer && l < base.mipmapLevelCount; l++) {
        NSUInteger w = MAX(base.width >> l, 1u), h = MAX(base.height >> l, 1u), z = base.textureType == MTLTextureType3D ? MAX(base.depth >> l, 1u) : 1;
        if (base.textureType == MTLTextureType3D)
            enc_b_copy_texture(b, base, 0, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, z), upgraded, 0, l, MTLOriginMake(0, 0, 0));
        else for (NSUInteger s = 0; s < slices; s++)
            enc_b_copy_texture(b, base, s, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), upgraded, s, l, MTLOriginMake(0, 0, 0));
    }
    id<MTLTexture> upgraded_view = nil;
    if ([holder isKindOfClass:[NvPkg class]]) { id<MTLTexture> old = ((NvPkg *)holder)->tex; ((NvPkg *)holder)->tex = upgraded; defer_obj_release(old); ser_gen_bump_one(t->serial);
        if (((NvPkg *)holder)->view) { defer_obj_unref(((NvPkg *)holder)->view); ((NvPkg *)holder)->view = nil; ((NvPkg *)holder)->vbase = 0; } }   // a sparse texture's view of the old one: bound whole until its next upload
    else {
        // Every name of the old texture moves to the upgraded one (upstream reference implementation, MIT, PR #107, with 92f223a7): other serials over the same storage (live in g_by_serial,
        //   finalized in g_ghost / g_ghost_active) and the sharing table. Only the asking serial and the sharing table moved before: the other serials kept reading the old copy while writes
        //   went to the new one, and the old texture stayed in g_alias_set, so an sRGB / linear view of it was never seen as stale (tex_mtl_). Slots are replaced in place (no insert, no
        //   resize during the walk); the old texture is retired once the submissions that used it complete, the view caches follow g_ser_gen
        pthread_mutex_lock(&g_smu);
        nvn_hmap *tables[] = {&g_by_serial, &g_ghost, &g_ghost_active}; int named = 0, shared = 0;
        for (unsigned j = 0; j < sizeof tables / sizeof *tables; j++) for (uint32_t i = 0; i < tables[j]->cap; i++) {
            if (tables[j]->vals[i] != (__bridge void *)base) continue;
            uint64_t serial; memcpy(&serial, tables[j]->keys + (size_t)i * tables[j]->klen, sizeof serial);
            void *old = tables[j]->vals[i]; tables[j]->vals[i] = (void *)CFBridgingRetain(upgraded); CFRelease(old); named |= serial == t->serial;
        }
        for (uint32_t i = 0; i < g_alias.cap; i++) {
            if (g_alias.vals[i] != (__bridge void *)base) continue;
            void *old = g_alias.vals[i]; g_alias.vals[i] = (void *)CFBridgingRetain(upgraded); CFRelease(old); shared = 1;
        }
        if (shared) { CFSetRemoveValue(g_alias_set, (__bridge const void *)base); CFSetAddValue(g_alias_set, (__bridge const void *)upgraded); }
        ser_gen_bump_all();
        pthread_mutex_unlock(&g_smu);
