                if (gdec) {   // decompression job: dispatched at flush, after the deswizzles (up_flush)
                    MTLPixelFormat vf = mt.pixelFormat == MTLPixelFormatRGBA8Unorm_sRGB ? MTLPixelFormatRGBA8Unorm : mt.pixelFormat;
                    id<MTLTexture> v = [mt newTextureViewWithPixelFormat:vf textureType:MTLTextureType2D levels:NSMakeRange(l, 1) slices:NSMakeRange(y, 1)];
                    size_t qoff; id<MTLBuffer> q = up_param_alloc(&qoff);
                    if (!v) { enc_ok = 0; break; }
                    uint32_t *pp = (uint32_t *)((uint8_t *)q.contents + qoff); pp[0] = (uint32_t)(stg_off + off); pp[1] = (uint32_t)pitch; pp[2] = w; pp[3] = h; pp[4] = (uint32_t)bcd_fmt(t->d.format); pp[5] = 0;
                    if (g_nup_decs == g_up_deccap) { size_t c = g_up_deccap ? g_up_deccap * 2 : 256; if (GROW(g_up_decs, c * sizeof *g_up_decs, "BC decode list")) g_up_deccap = c; }
                    if (g_nup_decs < g_up_deccap) g_up_decs[g_nup_decs++] = (up_dec){stg, q, qoff, (w + 3) / 4, (h + 3) / 4, v, mt}; [g_up_texs addObject:v]; defer_obj_unref(v);   // the view goes when this submission has run; the residency set holds the base texture
                    if (y == 0 && l == 0) bc_note(t->d.format, "upload, GPU");
                } else
                up_blit_add(stg, stg_off + off, pitch, pitch * rows, MTLSizeMake(w, h, z), mt, y, l);
                off += pitch * rows * z;
            }
        }
        if (enc_ok) {
            [g_up_texs addObject:mt];
            stl_add(STL_GENC, stl0); atomic_fetch_add_explicit(&g_stl_gpu_tex, 1, memory_order_relaxed);
            if (!g_cb) up_flush();
            return mt;
        }
        g_nup_blits = nb0; g_nup_decs = nd0;   // Roll back the copies / decompressions already recorded for this texture: the already-encoded deswizzle only writes the staging area and is harmless; this texture takes the CPU path below instead
        if (!g_cb) up_flush();
        RED_ONCE(41, "GPU deswizzle does not support format %#x target %d; falling back to the CPU", t->d.format, t->d.target);
    }

    // A sparse pool's texture is read through a copy gathered from its page table, unmapped pages as 0 (a mip tail at a 4 KB offset has no host alias; reading the alias stopped the host with SIGBUS)
    const uint8_t *src = src_override ? src_override : t->mem; uint8_t *part = NULL;
    stl0 = stl_now(); atomic_fetch_add_explicit(&g_stl_cpu_tex, 1, memory_order_relaxed);
    if (src_override) {}
    else if (sparse) {
        if (!(part = malloc(t->L.size ? t->L.size : 1))) MDIE("sparse texture copy of %llu bytes failed", (unsigned long long)t->L.size);
        nvn_sparse_copy(t->pool, part, (uint64_t)(uintptr_t)t->mem, t->L.size); src = part;
    }
    // #b5a081 / #8328e7（v0.4.0，3 台 3 款，Mac + iPhone）：存储不在任何内存池里的贴图（「not in a memory pool」那条红）没有池尾可截，按声明的全长读；
    //   游戏只映射了它真用到的那段，尾巴落进没映射的 2 MB 区（当前权限 ---），这里的整段拷贝读到就 SIGBUS（真机 GPU 只读用到的字节）。
    //   可读的不到全长：可读部分进副本、其余按 0（同稀疏池的未映射页），记一次红
    //   诊断#a4a895（0.4.1 仍崩）：贴图挂着池指针、存储却不在池登记的缓冲里（同样打「not in a memory pool」），起点落在没映射的块里——
    //   原先只在没有池指针时截短，这种跳过了、块线性拷贝直接从起点读，提交线程 SIGBUS。CPU 拷贝前一律先问可读长度（不看有没有池指针）
    else src = tex_src(t, t->L.size, &part);
    up_begin();
    id<MTLBuffer> stg = up_cpu_stage(total ? total : 16, t);
    res_add(stg); up_keep_add(stg);
    size_t off = 0;
    int zb = zblock_on() && t->d.format >= 0x79 && t->d.format <= 0x94; if (zb) { g_zb_ser = t->serial; g_zb_n = (int)MIN(d.mipmapLevelCount, 16u); memset(g_zb, 0, sizeof g_zb); memset(g_zb_tot, 0, sizeof g_zb_tot); }
    for (unsigned l = 0; l < d.mipmapLevelCount; l++) {
        uint32_t w = MAX(t->d.width >> l, 1u), h = MAX(t->d.height >> l, 1u), z = t->d.target == 2 ? MAX(t->d.depth >> l, 1u) : 1;
        size_t pitch = (size_t)((w + bw - 1) / bw) * bpb, rows = (h + bh - 1) / bh;
        if (unp) {   // no BC: the blocks of each layer are deswizzled into a scratch buffer and decompressed into the staging area (nvn_bc_decode, one depth slice at a time)
            size_t up = (size_t)w * ubpp; uint8_t *cb = malloc(pitch * rows * z ? pitch * rows * z : 1); bc_note(t->d.format, "upload");
            if (!cb) MDIE("BC decode scratch of %zu bytes failed", pitch * rows * z);
            for (unsigned y = 0; y < layers; y++) {
                if (nvn_deswizzle(&t->d, l, y, src, cb, pitch)) { RED_ONCE(9, "deswizzle failed format %#x target %d", t->d.format, t->d.target); break; }
                for (uint32_t zi = 0; zi < z; zi++) fmt_decode(t->d.format, cb + zi * pitch * rows, pitch, w, h, (uint8_t *)stg.contents + off + zi * up * h, up);
                up_blit_add(stg, off, up, up * h, MTLSizeMake(w, h, z), mt, y, l);
                off += up * h * z;
            }
            free(cb); continue;
        }
        for (unsigned y = 0; y < layers; y++) {
            if (nvn_deswizzle(&t->d, l, y, src, (uint8_t *)stg.contents + off, pitch)) { RED_ONCE(9, "deswizzle failed format %#x target %d", t->d.format, t->d.target); break; }
            if (zb && l < 16) { const uint64_t *q = (const uint64_t *)((const uint8_t *)stg.contents + off); size_t nb = pitch * rows * z / 16;
                for (size_t i = 0; i < nb; i++) g_zb[l] += !(q[2 * i] | q[2 * i + 1]);
                g_zb_tot[l] += (uint32_t)nb; }
            up_blit_add(stg, off, pitch, pitch * rows, MTLSizeMake(w, h, z), mt, y, l);
            off += pitch * rows * z;
        }
    }
    free(part);
    stl_add(STL_CPU, stl0);   // flush timed apart (STL_FLUSH)
    up_flush();
    return mt;
}
// Zero newly created non-packaged textures: a new Metal texture's content is undefined, while a freshly mapped memory pool on the Switch reads as 0. Games depend on it: SMBW's fountain water surface uses a 512×1 RGBA16F wave texture
// that every frame is "read last frame → render into a render target → copy back" and is never cleared; the undefined initial value keeps swinging through the feedback and pushes the water vertices to the top of the screen (the tall panels above the fountain).
// Copied level by level / slice by slice from one shared all-zero buffer, executed with the upload batch (ordered before this replay). Multisample, depth / stencil and block-compressed formats are not cleared (games always clear them before use, and they cannot be copied into anyway).
// mtl_pf_bytes 与 mtl_pfv_compatible 在 nvn_pfview.h（本文件开头 include），单测单独编这个头文件。
// Shared all-zero buffer (for zeroing new textures and scissored zero clears): replaced by a bigger one when too small; the old one is released after in-flight submissions finish
static id<MTLBuffer> fill_buf(size_t need, int poison) {   // bytes of 0, or of 0x3c (S2A_WIDEN_POISON)
    static id<MTLBuffer> zb[2]; static size_t zn[2];
    if (need > zn[poison]) {
        size_t n = MAX(need, (size_t)4 << 20);
        id<MTLBuffer> b = [g_dev newBufferWithLength:n options:MTLResourceStorageModeShared];
        if (!b) return nil;
        memset(b.contents, poison ? 0x3c : 0, n); res_add(b);
        if (zb[poison]) defer_obj_release(zb[poison]);
        zb[poison] = b; zn[poison] = n;
    }
    return zb[poison];
}
static id<MTLBuffer> zero_buf(size_t need) { return fill_buf(need, 0); }
static uint64_t g_tex_zeroed;
static void tex_fill(id<MTLTexture> mt, int poison);
static int wd_poison(void);
static void tex_zero_fill(id<MTLTexture> mt) { tex_fill(mt, wd_poison() == 2); }   // S2A_WIDEN_POISON=2: every new texture, not only widened storages
// S2Arm widen diagnostic S2A_WIDEN_POISON=1: a widened storage starts as bytes of 0x3c instead of 0 (f16 ≈ 1.06, RGBA8 60): in a one-frame replay, columns of the widened strip that are
//   read but never written this frame show up, which on a device hold another frame's or another texture's content (11-02 Mario Party: coloured blocks top right on the device only)
static int wd_poison(void) { static int on = -1; if (on < 0) { const char *e = getenv("S2A_WIDEN_POISON"); on = e && (!strcmp(e, "1") || !strcmp(e, "2")) ? atoi(e) : 0; } return on; }
static void tex_fill(id<MTLTexture> mt, int poison) {
    static int warned;
    if (!atomic_load(&g_sub_thread_set) || !on_sub_thread()) return;   // the upload batch belongs to the submit thread only
    MTLTextureType tt = mt.textureType;
    if (tt == MTLTextureType2DMultisample || tt == MTLTextureType2DMultisampleArray || tt == MTLTextureTypeTextureBuffer) return;
    size_t bpp = mtl_pf_bytes(mt.pixelFormat);
    if (!bpp) { if (!warned++) MLOG("new-texture zeroing: pixel format %lu not cleared (depth / stencil / compressed etc.)", (unsigned long)mt.pixelFormat); return; }
    NSUInteger slices = mt.arrayLength * (tt == MTLTextureTypeCube || tt == MTLTextureTypeCubeArray ? 6 : 1);
    size_t need = (size_t)mt.width * bpp * mt.height * mt.depth;   // level 0, one slice is the largest
    if (need > (64u << 20)) { static int big; if (!big++) MLOG("new-texture zeroing: %lux%lux%lu exceeds 64 MB, not cleared", (unsigned long)mt.width, (unsigned long)mt.height, (unsigned long)mt.depth); return; }
    id<MTLBuffer> zb = fill_buf(need, poison); if (!zb) return;
    up_begin();
    for (NSUInteger l = 0; l < mt.mipmapLevelCount; l++) {
        NSUInteger w = MAX(mt.width >> l, 1u), h = MAX(mt.height >> l, 1u), z = tt == MTLTextureType3D ? MAX(mt.depth >> l, 1u) : 1;
        for (NSUInteger y = 0; y < slices; y++) up_blit_add(zb, 0, w * bpp, w * bpp * h, MTLSizeMake(w, h, z), mt, y, l);
    }
    [g_up_texs addObject:mt];
    if (!g_cb) up_flush();
    if (!g_tex_zeroed++) MLOG("new-texture zeroing: on (new Metal textures are undefined; new Switch memory reads 0)");
}

// Initial content: what a memory pool's storage holds at nvnMemoryPoolInitialize is the pool's content, also in a pool the CPU cannot access afterwards (CPU_NO_ACCESS), where the
// game never writes it again. Rhythm Heaven Groove reads each texture file into memory and makes a CPU_NO_ACCESS | GPU_CACHED pool on it (245 by its first screens), with BC7 textures
// that have no packaged layout; as GPU textures of zeros its sprite shader discarded every fragment (alpha 0) and the screen stayed black. A new texture in such a pool whose storage
// holds data is filled from it once, as a GPU texture that can still be rendered into (no re-upload on page writes, unlike packaged / CPU-written ones). Left out: storage of zeros
// (the zero fill does the same), COMPRESSIBLE textures (their memory is meaningless without the compression tags), multisample, depth / stencil and sparse ones.
// In a pool the CPU can write, the same holds whether or not the game flushed it: on the Switch the GPU reads that very memory, so a texture the GPU has not written yet holds what
// its storage holds. Breath of the Wild copies its sky scattering tables into their pools and flushes them (without them the sky was brownish grey); The Witcher 3 reads its texture
// files into CPU-cached pools, then initializes the textures over them, with no flush (os::FlushDataCache runs natively): the CPU writes come before the texture is registered, so the
// write tracking (ft_add) never sees them, and 21 of its 46 128x128 BC1 / ASTC 5x5 textures sampled in Kaer Morhen were GPU textures of zeros (black floor and Geralt, magenta).
// DM_NVN_FLUSH_FILL=0 leaves the CPU-writable pools out
static int mem_any(const uint8_t *p, uint64_t n) {   // whether any byte is non-zero (stops at the first)
    uint64_t i = 0, v;
    for (; i + 8 <= n; i += 8) { memcpy(&v, p + i, 8); if (v) return 1; }
    for (; i < n; i++) if (p[i]) return 1;
    return 0;
}
// 同 mem_any，但不读游戏从没碰过的页：客体内存是匿名页，没写过的页既不在内存也没被压缩（mincore 两位都是 0），内容一定是 0；
//   读它一下宿主内核就当场给一页零页、计进进程实占（M5 Pro 实测：512 MB 未写匿名内存逐页读一遍，phys_footprint +512 MB）。
//   11-05 时之笛 iPhone：新建的 GPU 贴图（渲染目标等）都经 tex_init_fill 判存储是否全 0，全 0 的存储被整段读过一遍，游戏从没写过的页白白进了足迹。
//   只读在内存 / 已压缩的页；mincore 失败时退回整段读（同原来）
static uint64_t g_fill_untouched_bytes, g_fill_untouched_n;   // 判全 0 时没读的未触碰页（诊断行，首 4 次后按 2 的幂）
__attribute__((weak)) int s2a_guest_fd(void) { return -1; }   // native vawin.c (S2A_GUEST_FILE); graphics unit tests have no guest window
static int mem_any_touched(const uint8_t *p, uint64_t n) {
    // 客体内存文件后备时：被内核写回文件、又从内存里丢掉的页，mincore 两位也都是 0，但内容在文件里，不能当 0；而文件页读一下不计实占，直接整段读
    if (s2a_guest_fd() >= 0) return mem_any(p, n);
    uint64_t pg = (uint64_t)getpagesize(), a0 = (uint64_t)(uintptr_t)p & ~(pg - 1), a1 = ((uint64_t)(uintptr_t)p + n + pg - 1) & ~(pg - 1), skipped = 0;
    unsigned char vec[256];
    for (uint64_t a = a0; a < a1; a += sizeof vec * pg) {
        uint64_t len = MIN(a1 - a, (uint64_t)sizeof vec * pg), np = len / pg;
        if (mincore((void *)(uintptr_t)a, (size_t)len, (char *)vec)) {   // 查不了：整段读
            uint64_t lo = MAX(a, (uint64_t)(uintptr_t)p), hi = MIN(a + len, (uint64_t)(uintptr_t)p + n);
            if (mem_any((const uint8_t *)(uintptr_t)lo, hi - lo)) return 1;
            continue;
        }
        for (uint64_t i = 0; i < np; i++) {
            uint64_t lo = MAX(a + i * pg, (uint64_t)(uintptr_t)p), hi = MIN(a + (i + 1) * pg, (uint64_t)(uintptr_t)p + n);
            if (!(vec[i] & (MINCORE_INCORE | MINCORE_PAGED_OUT))) { skipped += hi - lo; continue; }
            if (mem_any((const uint8_t *)(uintptr_t)lo, hi - lo)) return 1;
        }
    }
    if (skipped) { uint64_t k = ++g_fill_untouched_n; g_fill_untouched_bytes += skipped;
        if (k <= 4 || !(k & (k - 1)) || skipped >= (8u << 20)) MLOG("initial content: storage %p+%#llx is zero, %llu KB of it never touched by the game and not read (%llu textures, %llu MB so far)",
                                                                   (void *)p, (unsigned long long)n, (unsigned long long)(skipped >> 10), (unsigned long long)k, (unsigned long long)(g_fill_untouched_bytes >> 20)); }
    return 0;
}
// Stale guest bytes: what a GPU write to a block-linear texture (render target attachment, image store, copy / clear destination) covered. On the Switch the texture is that memory
// and the write lands in it; here it lands in a Metal texture and the guest bytes stay what they were. tex_init_fill does not take such bytes as a new texture's initial content in a
// CPU_NO_ACCESS pool (10-28 Splatoon 3: after the plaza scene switch a 256×256×78 R11G11B10F lighting volume took 0.46–1.24 M Inf / NaN from bytes an earlier GPU texture had covered,
// and the exposure locked white: 5 of 6 runs; 0 of 3 with those fills skipped). Kept by guest address across textures and pools, at the granule of block-linear storage: a GOB,
// 512 bytes (also the storage alignment of a texture, so a neighbour sharing a 4 KB page is not touched; 10-28 audit #743 P1-1: the 4 KB page granule zeroed neighbours, and one
// covered page zeroed a whole texture).
// When a write is noted (only real ones: an attachment of a pass that is opened, an image bound writable to a shader that stores to images, a copy / clear destination; not
//   SetRenderTargets alone or the IMAGE flag), each GOB it covers is marked with a hash of its guest bytes at that moment.
// What makes a GOB current again (its guest bytes are what the Switch would hold): a write into guest memory itself. Those this backend executes are exact (gpw_clear: buffer copy,
//   fill, uniform update, transform feedback, texture→buffer copy destination; through pend_add / copy_t2b); any other (the CPU, the host, a storage buffer or report written by
//   a shader) shows as different bytes: a marked GOB whose bytes no longer hash as marked is current (checked when a texture fill reads it). A GOB touched in part counts as
//   rewritten. What does not: finalizing / re-creating a pool or texture over the memory, a CPU flush, another texture's description of it (none of these changes the bytes,
//   so on the Switch they still hold the GPU's write). Linear and buffer textures are not marked: they live on the pool buffer, GPU writes land in guest memory.
// DM_NVN_STALE_FILL=1 takes stale bytes as before (A/B only)
typedef struct { uint64_t bits[8]; uint64_t h[512]; } gpw_blk;   // 256 KB of guest memory: 512 GOBs; bit = stale, h = span_hash of its bytes when marked
typedef struct { uint64_t gen; uint32_t n; uint64_t bits[]; } gpw_dd;   // a texture's subresources (level × layer) already marked whole since generation gen
static nvn_hmap g_gpw = {.klen = 8}, g_gpw_ser = {.klen = 8};   // guest address >> 18 → gpw_blk *; serial → gpw_dd *
static pthread_mutex_t g_gpw_mu = PTHREAD_MUTEX_INITIALIZER; static uint64_t g_gpw_skips, g_gpw_gen = 1; static _Atomic uint64_t g_gpw_nblk;
// 记账和核对时取 GOB 的哈希，不读游戏从没碰过的页（同 mem_any_touched 的判据：匿名页 mincore 两位都是 0 = 没写过，内容一定是 0，哈希就是 512 个 0 的哈希）。
//   11-13 0400486024DEC000 Mac 读档进场景：新建的渲染目标存储游戏没写过，标记时逐 GOB 读一遍：一帧 553 次标记读 154 MB、在提交线程上 52 ms，
//   另一帧 63 次标记读 320 MB；两帧的页 9,602 / 9,997 和 20,478 / 20,482 没碰过，每页缺页一次，读过的零页还都计进进程实占。
//   mincore 按段查（gob_win 缓存一段的结果，GOB 顺着走），查不了的页照读；客体内存文件后备时一律照读（写回文件后丢掉的页两位也是 0，内容在文件里）
typedef struct { uint64_t a, n; int off; unsigned char v[256]; } gob_win;   // 宿主页 [a, a + n 页) 的 mincore 结果；off = 不查、一律照读
static uint64_t g_gob_untouched, g_gob_untouched_n;   // 没读的未触碰 GOB 数、有这种 GOB 的记账次数（under g_gpw_mu；诊断行，首 4 次后按 2 的幂）
static uint64_t gob_zero_hash(void) { static uint64_t h; static dispatch_once_t o; dispatch_once(&o, ^{ static const uint8_t z[512]; h = span_hash(z, sizeof z); }); return h; }
static gob_win gob_win_new(void) { return (gob_win){.off = s2a_guest_fd() >= 0}; }
static uint64_t gob_hash_w(gob_win *w, uint64_t g, uint64_t ge) {   // = gob_hash(g)；ge：调用方这一趟走到哪个 GOB 为止（决定往前查多少页）
    const uint8_t *h = host_rd((const uint8_t *)(uintptr_t)(g << 9));
    uint64_t pg = (uint64_t)getpagesize(), p = (uint64_t)(uintptr_t)h & ~(pg - 1);
    if (p < w->a || p >= w->a + w->n * pg) {
        uint64_t n = MIN(((ge - g) * 512 + pg - 1) / pg + 1, (uint64_t)sizeof w->v);
        if (w->off) memset(w->v, MINCORE_INCORE, (size_t)n);   // 文件后备：不按驻留判（文件页总算碰过），只按下面的可读判
        else if (mincore((void *)(uintptr_t)p, (size_t)(n * pg), (char *)w->v) && (n = 1, mincore((void *)(uintptr_t)p, (size_t)pg, (char *)w->v))) w->v[0] = MINCORE_INCORE;   // 查不了：当碰过，再看可读
        pages_mask_readable((uintptr_t)p, n, (uintptr_t)pg, w->v);   // 诊断#f83b30：驻留不等于可读，不可读的页按「没碰过」= 0，不读
        w->a = p; w->n = n;
    }
    if (!(w->v[(p - w->a) / pg] & (MINCORE_INCORE | MINCORE_PAGED_OUT))) { g_gob_untouched++; return gob_zero_hash(); }
    return span_hash(h, 512);
}
static void gpw_add(void *u, uint64_t lo, uint64_t hi) {   // under g_gpw_mu; u = the texture's storage base: [lo, hi) are offsets from it
    uint64_t base = (uint64_t)(uintptr_t)u, u0 = g_gob_untouched; gob_win w = gob_win_new();
    for (uint64_t g = (base + lo) >> 9, ge = (base + hi + 511) >> 9; g < ge; g++) {
        uint64_t k = g >> 9; gpw_blk *b = nvn_hm_get(&g_gpw, &k);
        if (!b) { if (!(b = calloc(1, sizeof *b))) MDIE("stale-byte table allocation failed"); nvn_hm_put(&g_gpw, &k, b); atomic_fetch_add(&g_gpw_nblk, 1); }
        unsigned i = (unsigned)(g & 511); b->bits[i >> 6] |= 1ull << (i & 63); b->h[i] = gob_hash_w(&w, g, ge);
    }
    if (g_gob_untouched != u0) { uint64_t k = ++g_gob_untouched_n;
        if (k <= 4 || !(k & (k - 1))) MLOG("stale-byte ledger: GPU write over %p+%#llx, %llu KB of it never touched by the game and not read (%llu marks, %llu MB so far)", (void *)u, (unsigned long long)lo,
                                         (unsigned long long)((g_gob_untouched - u0) >> 1), (unsigned long long)k, (unsigned long long)(g_gob_untouched >> 11)); }
}
static void gpw_unmark(uint64_t g) {   // under g_gpw_mu: GOB g is current again
    uint64_t k = g >> 9; gpw_blk *b = nvn_hm_get(&g_gpw, &k); unsigned i = (unsigned)(g & 511);
    if (!b || !(b->bits[i >> 6] >> (i & 63) & 1)) return;
    b->bits[i >> 6] &= ~(1ull << (i & 63)); g_gpw_gen++;   // marks deduplicated before this are taken again (gpw_mark)
    uint64_t any = 0; for (int w = 0; w < 8; w++) any |= b->bits[w];
    if (!any) { nvn_hm_del(&g_gpw, &k); free(b); atomic_fetch_sub(&g_gpw_nblk, 1); }
}
static void gpw_clear(uint64_t lo, uint64_t n) {   // this backend's GPU wrote guest memory [lo, lo + n) (buffer copy / fill / update, transform feedback, texture→buffer copy)
    if (!n || !atomic_load_explicit(&g_gpw_nblk, memory_order_relaxed)) return;
    pthread_mutex_lock(&g_gpw_mu);
    for (uint64_t g = lo >> 9, ge = (lo + n + 511) >> 9; g < ge; g++) {
        uint64_t k = g >> 9; if (!nvn_hm_get(&g_gpw, &k)) { g = (k << 9) + 511; continue; }
        gpw_unmark(g);
    }
    pthread_mutex_unlock(&g_gpw_mu);
}
// The storage bytes of a texel rectangle of a level at GOB precision (tex_rect_bytes gives whole block rows; a block is 2^tileH GOBs stacked vertically): fn(lo, hi) per run
static void tex_rect_gobs(const tex_t *t, unsigned l, unsigned layer, uint32_t x, uint32_t y, uint32_t w, uint32_t h, range_fn fn, void *u) {
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); unsigned nl = t->d.levels ? t->d.levels : 1; if (!bpb || 64 % bpb || l >= nl) return;
    uint64_t ls = t->L.layer_size ? t->L.layer_size : t->L.size, a = (uint64_t)layer * ls + nvn_tex_level_offset(&t->d, l), e = l + 1 < nl ? (uint64_t)layer * ls + nvn_tex_level_offset(&t->d, l + 1) : (uint64_t)(layer + 1) * ls;
    unsigned th = 0, td = 0; nvn_tex_level_tiles(&t->d, l, &th, &td); uint32_t gobs = nvn_tex_level_gobs(&t->d, l);
    uint32_t lw = MAX(t->d.width >> l, 1u), lh = MAX(t->d.height >> l, 1u);
    if (!w || !h) { x = y = 0; w = lw; h = lh; }
    if (t->d.target == 2 || td || t->d.samples > 1 || !gobs || (x == 0 && y == 0 && w >= lw && h >= lh)) { fn(u, a, e); return; }
    uint64_t blk = 512ull << th, row = (uint64_t)gobs * blk; uint32_t cw = (uint32_t)(64 / bpb) * (uint32_t)bw, gh = 8u * (uint32_t)bh, rh = gh << th;
    for (uint32_t r = y / rh; r * rh < y + h; r++) {
        uint32_t y0 = MAX(y, r * rh) - r * rh, y1 = MIN(y + h, (r + 1) * rh) - r * rh, g0 = y0 / gh, g1 = (y1 + gh - 1) / gh;
