                                                   (unsigned long long)t->serial, t->d.format, t->d.width, t->d.height, done, (unsigned long long)ew->serial, ew->d.format, (unsigned long long)c);
}
static void bcal_sync(const tex_t *t, id<MTLTexture> r) {
    if (!r || g_bcal_off || !t->mem || !t->pool || g_tex_peek || !g_cb || !on_sub_thread()) return;
    uint64_t k = (uint64_t)(uintptr_t)t->mem;
    bcal_seen_mark(k, t->pool);
    if (!atomic_load_explicit(&g_bcal_n, memory_order_relaxed)) return;
    bcal_e *pe = bcal_find(k); if (!pe) return;
    uint64_t mg = atomic_load(&pe->maxgen);
    if (atomic_load_explicit(&pe->s_ser, memory_order_relaxed) == t->serial && atomic_load_explicit(&pe->s_r, memory_order_relaxed) == (__bridge const void *)r
        && atomic_load_explicit(&pe->s_gen, memory_order_relaxed) == mg) return;   // 这张已同步到最新、解析结果没换
    tex_t ew; uint64_t elg[16]; bcal_snap(pe, &ew, elg);
    id<MTLTexture> dst = r; while (dst.parentTexture) dst = dst.parentTexture;
    __unsafe_unretained id o = tex_get(t->serial); NvPkg *pk = [o isKindOfClass:[NvPkg class]] ? o : nil;
    unsigned todo[16], n = 0; bcal_s *s;
    pthread_mutex_lock(&g_bcal_mu);
    if (!(s = nvn_hm_get(&g_bcal_sync, &t->serial))) { if (!(s = calloc(1, sizeof *s))) MDIE("block-compressed alias table allocation failed"); nvn_hm_put(&g_bcal_sync, &t->serial, s); }
    if (s->dst != (__bridge const void *)dst) { memset(s->lgen, 0, sizeof s->lgen); s->dst = (__bridge const void *)dst; }
    for (unsigned l = 0; l < 16; l++) if (elg[l] > s->lgen[l] && bcal_level_ok(&ew, t, l)) todo[n++] = l;
    id<MTLTexture> kept = n && pe->wtex && atomic_load(&pe->wser) == ew.serial ? (__bridge id<MTLTexture>)pe->wtex : nil;   // 锁下取强引用（换写入者也在锁下释放旧的）
    pthread_mutex_unlock(&g_bcal_mu);
    if (n) bcal_copy(t, dst, pk, &ew, elg, todo, n, s, kept);   // 拷不成（没有来源贴图 / 暂存缓冲）也记成已看过：不在每次解析时重试
    atomic_store(&pe->s_ser, t->serial); atomic_store(&pe->s_r, (__bridge const void *)r); atomic_store(&pe->s_gen, mg);   // mg 取在拷之前：其间的新写下次再看
}
static id<MTLTexture> tex_mtl(const tex_t *ct) { AP_B; g_tex_mtl_n++; uint64_t stl0 = stl_now(); id<MTLTexture> r = tex_mtl_(ct); stl_add(STL_TEXMTL, stl0); if (r && ct && fmt_compressed(ct->d.format)) bcal_sync(ct, r); AP_E(4); return r; }
// A sparse texture is bound from its first level whose pages, and those of every smaller level, are all mapped: a view of levels [r, n) samples as with a minimum LOD of r.
// The translator drops TEX's LOD clamp and residency predicate, so Monster Hunter Rise's streamed textures were sampled at levels it had not mapped yet; those read 0, which ASTC
// decodes as its error colour (magenta clothes on the title screen). Single-layer 2D textures only; the view follows each upload, as the mappings change only with one
static void sparse_view(NvPkg *pk, const tex_t *t) {
    unsigned n = (unsigned)pk->tex.mipmapLevelCount, r = n;
    if (t->d.target == NVN_TEXTURE_TARGET_2D && n > 1)
        while (r > 0) { uint64_t lo = nvn_tex_level_offset(&t->d, r - 1), hi = r < n ? nvn_tex_level_offset(&t->d, r) : t->L.size;
            if (!nvn_sparse_mapped(t->pool, (uint64_t)(uintptr_t)t->mem + lo, hi - lo)) break;
            r--; }
    else r = 0;
    if (r == n) r = n - 1;   // nothing mapped: the smallest level (reads 0)
    if (pk->view) defer_obj_unref(pk->view);   // a view shares its texture's allocation: drop only the reference, the residency set keeps the texture
    pk->view = r ? [pk->tex newTextureViewWithPixelFormat:pk->tex.pixelFormat textureType:pk->tex.textureType levels:NSMakeRange(r, n - r) slices:NSMakeRange(0, 1)] : nil;
