        return 1;
    }
    g_spc_walk++;
    uint64_t sq = nvn_sparse_log_seq(t->pool);   // 先取序号再走：走的期间来的映射请求序号 ≥ sq，下次按重叠算
    int clean = !nvn_sparse_since(t->pool, a, n, pk->vgen, pk->stamp);
