            if (!d || d.sampleCount > 1 || (d.textureType != MTLTextureType2D && d.textureType != MTLTextureType2DArray)) break;
            if (b.pixelFormat == d.pixelFormat || tex_need_pfv(b.pixelFormat, d.pixelFormat) || b.textureType != d.textureType) continue;
            v = [b newTextureViewWithPixelFormat:d.pixelFormat textureType:b.textureType levels:NSMakeRange(0, b.mipmapLevelCount) slices:NSMakeRange(0, b.arrayLength) swizzle:b.swizzle];
            if (v) { pthread_mutex_lock(&g_smu); nvn_hm_put(&g_alias_seen, &k, (void *)(uintptr_t)(g_fence + 1)); pthread_mutex_unlock(&g_smu);
                static int nv; if (nv++ < 4) MLOG("texture ser=%llu format %#x over the storage of its sRGB / linear twin (format %#x): made a view of it (%d so far)", (unsigned long long)t->serial, t->d.format, tw[j], nv); }
        }
        if (v) { srgb_twin_mark(v); tex_put(t->serial, v); return v; }
    }
    id<MTLTexture> mt = tex_linear(t);
    if (!mt) mt = gstex_new(t);   // GPU 写的稀疏贴图：块只在游戏映射了内存处（nvn_stex.inc）
    if (!mt) {
        double fit = rs_fit_tex(t);   // 边长超设备上限的按比例缩建（nvn_rscale.inc 文件头）
        MTLTextureDescriptor *d = tex_desc_fit(t, 0, fit);
        if (!d) return nil;
        uint64_t stl0 = stl_now();
        mt = rh_texture(t, d); if (!mt) mt = [g_dev newTextureWithDescriptor:d];   // 能进回收内存的先进（rh_texture）
        stl_add(STL_GNEW, stl0);
        if (!mt) { RED_ONCE(2, "failed to create MTLTexture ser=%llu %ux%u format %#x target %d samples %d levels %u", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, t->d.target, t->d.samples, t->d.levels); return nil; }
        if (fit != 1.0) {   // 记成已缩（画布 = 游戏尺寸）；游戏内存里的内容按游戏尺寸排，缩建的存储不从它初始化，清零
            atomic_store(&g_rs_over, 1); rs_set_info(mt, RS_SCALED, t->d.width, t->d.height, fit);
            static int nf; if (nf++ < 8) MLOG("内部分辨率：渲染目标 ser=%llu %ux%u 格式 %#x 超过贴图上限 %lu，按 %.4f 缩建成 %lux%lu（画面完整，这张目标分辨率降一档）",
                                               (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, (unsigned long)rs_dev_max(), fit, (unsigned long)mt.width, (unsigned long)mt.height);
        }
        res_add(mt); stl0 = stl_now(); int filled_ = fit == 1.0 && tex_init_fill(t, mt); if (!filled_) tex_zero_fill(mt); stl_add(STL_FILL, stl0);
        if (g_snap_newtex_log > 0) { g_snap_newtex_log--; MLOG("即时存档诊断：恢复后新建贴图 ser=%llu %ux%ux%u 级 %u 格式 %#x 目标 %d flags %#x 池 %p+%#llx 内容=%s", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.levels,
                                          t->d.format, t->d.target, t->d.flags, (void *)t->pool, (unsigned long long)t->off, filled_ ? "游戏内存" : "全零"); }   // register residency before filling (the copy destination must be resident too)
        if (big_tex_on() && mt.allocatedSize >= (4u << 20)) {   // 大贴图建立账（big_tex_res）：NVN 侧描述 + 存储有没有被游戏碰过（mincore，不读页）
            uint64_t touched = 0; size_t pg = (size_t)getpagesize(); unsigned char vec[512];
            for (uint64_t a = (uint64_t)(uintptr_t)t->mem & ~(uint64_t)(pg - 1), e = (uint64_t)(uintptr_t)t->mem + t->L.size; t->mem && a < e; a += sizeof vec * pg) {
                size_t n = (size_t)MIN((uint64_t)sizeof vec * pg, e - a); if (mincore((void *)(uintptr_t)a, n, (char *)vec)) break;
                for (size_t q = 0; q < (n + pg - 1) / pg; q++) if (vec[q] & (MINCORE_INCORE | MINCORE_PAGED_OUT)) touched += pg; }
            MLOG("[大贴图] GPU 贴图 ser=%llu NVN %ux%ux%u 级 %u 格式 %#x 目标 %d 采样 %d flags %#x（渲染目标可用 %d、图像 %d、可压缩 %d）池 %p flags %#x 偏移 %#llx 存储 %llu KB 其中常驻 / 压缩 %llu KB",
                 (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.levels, t->d.format, t->d.target, t->d.samples, t->d.flags, !!(mt.usage & MTLTextureUsageRenderTarget),
                 !!(t->d.flags & NVN_TEXTURE_FLAGS_IMAGE), !!(t->d.flags & NVN_TEXTURE_FLAGS_COMPRESSIBLE), (void *)t->pool, t->pool ? t->pool->flags : 0, (unsigned long long)t->off, (unsigned long long)(t->L.size >> 10), (unsigned long long)(touched >> 10)); }
    }
    if (g_allocprof > 0) { static int n; if (n++ < 30 || n % 500 == 0) MLOG("new texture (%s) #%d ser=%llu %ux%ux%u format %#x target %d levels %u storage %p", __func__, n, (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, t->d.target, t->d.levels, (void *)t->mem); }
    if (getenv("DM_NVN_TEXCPU") && t->pool && !(t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS)) MLOG("non-swizzled texture on a CPU-visible pool ser=%llu %ux%ux%u format %#x target %d levels %u texture flags %#x pool flags %#x storage %p", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, t->d.target, t->d.levels, t->d.flags, t->pool->flags, (void *)t->mem);
    res_add(mt);
    pthread_mutex_lock(&g_smu);
    if (!g_alias_set) g_alias_set = CFSetCreateMutable(NULL, 0, NULL);
    alias_take_over(&ak);
    hm_put_id(&g_alias, &ak, mt); CFSetAddValue(g_alias_set, (__bridge const void *)mt); nvn_hm_put(&g_alias_seen, &ak, (void *)(uintptr_t)(g_fence + 1));
    pthread_mutex_unlock(&g_smu);
    tex_put(t->serial, mt);
    return mt;
}
// Memory readout line (always on, low frequency, capped): resident memory, GPU allocated, deferred-release queue, residency set object count, registered memory pools / peak / tracking table capacity, cumulative texture re-uploads.
// Purpose: pin down "crashes with no log". The system gives no notice before killing a process for memory, so only readouts left beforehand can show which number kept climbing.
// Called by the frame hook every 300 frames; printed only when resident or GPU allocated changed by ≥ 64 MB since the last line, otherwise one line every 3000 frames; capped at 400 lines per game. All integers (the frame hook runs on the guest thread's small stack, so no floating-point formatting)
static void tess_stat_line(uint64_t frame);   // S2Arm tessellation: 曲面画出 / 跳过统计行（随本统计行一起打，定义在 tess_draw 旁）
static void nvn_mem_detail(unsigned long long frame);   // DM_NVN_MEM_DETAIL, defined with mtl_res_snapshot below (it needs the shader / pipeline / archive tables)
static void fb_report(uint64_t frame);   // same-pass feedback sampling counts (defined with fb_prepare)
static void fu_cls_report(uint64_t frame);   // first-use waits by prewarm list (#1001, defined with fu_list_class)
static void samp_report(uint64_t frame);   // sampler IDs registered again with another state (defined with nvn_be_reg_samp)
// Metal allocation size of a texture / buffer object held in a table (0 for anything else); for the memory report (#357)
static uint64_t res_bytes(id o) { return [o conformsToProtocol:@protocol(MTLResource)] ? (uint64_t)((id<MTLResource>)o).allocatedSize : 0; }
static uint64_t g_wd_ts_tbuf, g_wd_ts_tbuf_scaled, g_tb2_inexact;   // 取图倍率落在缓冲贴图上的条目数 / 其中倍率不为 1 的（widen_glue.inc wd_tex_scales_locked 计，诊断）；精确 2D 行形式放不下、退回固定行的次数（tbuf_as_2d）
static void audit_probe_report(uint64_t frame);   // audit #1534 passive probes P1-65 / P1-23 / P1-20 (defined after encode_args)
// 我方按种类的字节（S2A_MEM_SPLIT 跳变行，ios/app.m 的 100 ms 采样线程调；任意线程可调）：驻留集里的对象逐个分类——
//   私有贴图（游戏贴图的 Metal 副本、渲染目标）、私有缓冲（上传暂存块为主）、游戏内存池的零拷贝缓冲（按池表认，记虚拟长度和其中常驻 / 压缩页，含被驻留集钉住的未写页）、其它共享缓冲（每帧块、常量块等）。
//   锁序同 pool_res（g_mu → g_res_mu）：先在 g_mu 里拷池缓冲与范围，放锁后再取 g_res_mu 拍驻留集快照（强引用），分类在锁外做
// 切后台瘦身（11-13 维护者定，降低在后台被系统杀的概率）：进后台、GPU 排空后（hle_nvn.c dm_gfx_suspend_drain），把驻留集里我们自己分配的私有根贴图
//   （打包贴图副本 + 渲染目标等，正式游戏约 1.7 GB）标成可清除（MTLPurgeableStateVolatile）：可清除内存不计进 phys_footprint
//   （11-13 Duo 实测 1024 MB 共享缓冲：实占 1089 → 65 MB，标回 1089 MB、内容还在），系统缺内存时直接清掉这些、不用杀我们。
//   回前台、放开闸门之前（dm_gfx_suspend(0)）标回不可清除：没被清的原样接着用；被清的登记进 g_up_lost——打包贴图下次取用整张从客体内存重新上传（同上传被丢的
//   处理）。只标打包贴图：纯 GPU 贴图（渲染目标、GPU 写进去的）内容只在 GPU 上，被清了找不回（11-16 起不标，见下面 bg 分支）。不碰：零拷贝池缓冲（就是客体内存）、视图、缓冲背着的贴图、MTLHeap 分出来的（可清除按整堆算）、
//   各种缓冲（参数表、转换缓存等跨帧保留，被清了会错）。S2A_BG_PURGE=0 关
static void snap_test_zero(id<MTLTexture> t);   // nvn_snap.inc，测试开关 DM_TEST_BG_LOSE 用
static int g_test_bg_lose;   // 测试开关 DM_TEST_BG_LOSE 到点置 1（present_enqueue），下面进后台那一次用掉
// 标可清除 / 标回这两段，与即时存档读打包贴图时「钉成不可清除 → 读 → 标回」（nvn_snap.inc snap_tex_gone，存档线程，不经图形闸门）互斥：
//   不互斥的话，存档钉住一张的当口回前台标回，这张看着已是不可清除、不登记，存档读完又把它标回可清除——之后没人再标回，被清了也不登记重传
static pthread_mutex_t g_bg_purge_mu = PTHREAD_MUTEX_INITIALIZER;
static NSMutableArray<id<MTLTexture>> *g_bg_purged;   // 只在挂起 / 恢复的那一刻碰（闸门关着，提交线程停在闸门外）
static uint64_t bg_fp_mb(void) { task_vm_info_data_t v; mach_msg_type_number_t n = TASK_VM_INFO_COUNT; return task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&v, &n) == KERN_SUCCESS ? v.phys_footprint >> 20 : 0; }
void nvn_be_background_purge(int bg) {
    static int off = -1; if (off < 0) { const char *e = getenv("S2A_BG_PURGE"); off = e && *e == '0'; }
    if (!g_dev) return;
    // 后台期间的实占：标完那一刻读不出差别（系统挂起进程时才结算可清除页），进程挂起后定时器也不跑，所以在回前台、标回之前读一次——
    //   挂起期间实占不再变（除了被清），这个读数就是系统在后台看到的值；瘦身关（S2A_BG_PURGE=0）的局也记，好对照
    static uint64_t bg_in;
    if (bg) bg_in = bg_fp_mb();
    else if (bg_in) { LOG("[nvn] 回前台那刻实占 %llu MB（进后台时 %llu MB，切后台瘦身%s）", (unsigned long long)bg_fp_mb(), (unsigned long long)bg_in, off ? "关" : "开"); bg_in = 0; }   // 起局时的放闸不算
    if (off) return;
    pthread_mutex_lock(&g_bg_purge_mu);
    @autoreleasepool {
        if (bg) {
            uint64_t f0 = bg_fp_mb(), bytes = 0;
            // 只标能从客体内存重建的：打包贴图（CPU 写的内容，被清了下次取用整张重传，g_up_lost）。纯 GPU 贴图（渲染目标、游戏用 GPU 拷贝 / 计算写进去的）和
            //   GPU 写过的打包贴图（pgpu）不标：它们的内容只在 GPU 上，被清了没处找回。11-16 D-CZCW（0100B8A026F14000 iPhone，「切出去回来很容易花屏」）：
            //   两次回前台各清掉 853 / 909 张，只有 3 张走了重传、其余 850 / 906 张是纯 GPU 贴图，原设计假设「渲染目标下一帧重画」，
            //   只画一次的（字图集、GPU 拷贝填的 ASTC 贴图被清成全零 = 品红）就一直花
            NSHashTable *rebuildable = [[NSHashTable alloc] initWithOptions:NSPointerFunctionsStrongMemory | NSPointerFunctionsObjectPointerPersonality capacity:0];
            pthread_mutex_lock(&g_smu);
            nvn_hmap *tabs[] = {&g_by_serial, &g_ghost, &g_ghost_active};
            for (int ti = 0; ti < 3; ti++) for (uint32_t i = 0; i < tabs[ti]->cap; i++) {
                id o = (__bridge id)tabs[ti]->vals[i]; if (!o || ![o isKindOfClass:[NvPkg class]]) continue;
                NvPkg *pk = o; if (pk->pgpu || pk->sparse || pk->stex) continue;
                if (pk->tex) [rebuildable addObject:pk->tex];
                if (pk->spare) [rebuildable addObject:pk->spare]; }
            pthread_mutex_unlock(&g_smu);
            pthread_mutex_lock(&g_res_mu); NSArray *all = g_res_objects ? g_res_objects.allObjects : @[]; pthread_mutex_unlock(&g_res_mu);
            NSMutableArray<id<MTLTexture>> *marked = [NSMutableArray array]; uint64_t kept_n = 0, kept_b = 0;
            for (id o in all) {
                if (![o conformsToProtocol:@protocol(MTLTexture)]) continue;
                id<MTLTexture> t = o;
                if (t.buffer || t.parentTexture || t.heap || t.storageMode != MTLStorageModePrivate) continue;
                if (![rebuildable containsObject:t]) { kept_n++; kept_b += t.allocatedSize; continue; }   // 纯 GPU 内容：不标
                if ([t setPurgeableState:MTLPurgeableStateVolatile] != MTLPurgeableStateNonVolatile) continue;   // 已经可清除 / 已被清：不是这次标的
                [marked addObject:t]; bytes += t.allocatedSize;
            }
            g_bg_purged = marked;
            // 测试开关（见 present_enqueue）：当作系统在后台把这次标的全清了。iOS 上被清掉的贴图读出来是全零；Mac 上标成已清后原内容还读得到
            //   （11-23 M 系列 Mac 实测 256² / 2048² 两张 RGBA8 私有贴图：标已清、标回后读回，全零 0 字节、原内容 100%），所以先把内容写成全零再标
            if (g_test_bg_lose) for (id<MTLTexture> t in marked) { [t setPurgeableState:MTLPurgeableStateNonVolatile]; snap_test_zero(t); [t setPurgeableState:MTLPurgeableStateVolatile]; [t setPurgeableState:MTLPurgeableStateEmpty]; }
            g_test_bg_lose = 0;
            LOG("[nvn] 切后台瘦身：%lu 张打包贴图 %llu MB 标成可清除（系统缺内存时直接清掉、不计实占，回前台按需重传）；纯 GPU 内容的 %llu 张 %llu MB 不标（清了找不回）；实占 %llu → %llu MB",
                (unsigned long)marked.count, (unsigned long long)(bytes >> 20), (unsigned long long)kept_n, (unsigned long long)(kept_b >> 20), (unsigned long long)f0, (unsigned long long)bg_fp_mb());
        } else if (g_bg_purged) {
            uint64_t f0 = bg_fp_mb(), lost = 0, lost_b = 0;
            NSMutableArray<id<MTLTexture>> *emptied = [NSMutableArray array];
            for (id<MTLTexture> t in g_bg_purged) if ([t setPurgeableState:MTLPurgeableStateNonVolatile] == MTLPurgeableStateEmpty) { [emptied addObject:t]; lost++; lost_b += t.allocatedSize; }
            if (lost) {
                os_unfair_lock_lock(&g_up_lost_lk); if (!g_up_lost) g_up_lost = [NSHashTable weakObjectsHashTable];
                for (id t in emptied) [g_up_lost addObject:t];
                atomic_store(&g_up_lost_n, (int)g_up_lost.allObjects.count); os_unfair_lock_unlock(&g_up_lost_lk);
            }
            LOG("[nvn] 回前台：%lu 张贴图标回不可清除，其中 %llu 张 %llu MB 在后台被系统清掉（打包贴图下次取用整张重新上传、渲染目标下一帧重画），实占 %llu → %llu MB",
                (unsigned long)g_bg_purged.count, (unsigned long long)lost, (unsigned long long)(lost_b >> 20), (unsigned long long)f0, (unsigned long long)bg_fp_mb());
            g_bg_purged = nil;
        }
    }
    pthread_mutex_unlock(&g_bg_purge_mu);
}
void nvn_be_mem_kinds(uint64_t *priv_tex, uint64_t *priv_buf, uint64_t *pool_len, uint64_t *pool_touched, uint64_t *shared_other, uint64_t *objects) {
    *priv_tex = *priv_buf = *pool_len = *pool_touched = *shared_other = *objects = 0;
    if (!g_dev) return;
    @autoreleasepool {
        NSHashTable *pools = [[NSHashTable alloc] initWithOptions:NSPointerFunctionsStrongMemory | NSPointerFunctionsObjectPointerPersonality capacity:0];
        NSMutableArray<NSArray<NSNumber *> *> *ranges = [NSMutableArray array];
        pthread_mutex_lock(&g_mu);
        for (int i = 0; i < g_npool; i++) if (g_pools[i].buf) { [pools addObject:g_pools[i].buf]; if (g_pools[i].res) [ranges addObject:@[@(g_pools[i].base), @(g_pools[i].hi - g_pools[i].base)]]; }
        pthread_mutex_unlock(&g_mu);
        pthread_mutex_lock(&g_res_mu); NSArray *all = g_res_objects ? g_res_objects.allObjects : @[]; pthread_mutex_unlock(&g_res_mu);
        for (id o in all) {
            (*objects)++;
            if ([o conformsToProtocol:@protocol(MTLTexture)]) { id<MTLTexture> t = o; if (t.buffer || t.parentTexture) continue; if (t.storageMode == MTLStorageModePrivate) *priv_tex += t.allocatedSize; else *shared_other += t.allocatedSize; }
            else if ([o conformsToProtocol:@protocol(MTLBuffer)]) { id<MTLBuffer> b = o;
                if ([pools containsObject:b]) *pool_len += b.length; else if (b.storageMode == MTLStorageModePrivate) *priv_buf += b.allocatedSize; else *shared_other += b.allocatedSize; }
        }
        size_t pg = (size_t)getpagesize(); unsigned char vec[4096];
        for (NSArray<NSNumber *> *r in ranges) {   // 驻留池里常驻 / 已压缩的页：驻留集会把没写过的页也钉进内存，这里一并算（mincore 分不出）
            uint64_t a = r[0].unsignedLongLongValue & ~(uint64_t)(pg - 1), e = r[0].unsignedLongLongValue + r[1].unsignedLongLongValue;
            for (; a < e; a += sizeof vec * pg) { size_t n = (size_t)MIN((uint64_t)sizeof vec * pg, e - a), np = (n + pg - 1) / pg;
                if (mincore((void *)(uintptr_t)a, n, (char *)vec)) continue;
                for (size_t k = 0; k < np; k++) if (vec[k] & (MINCORE_INCORE | MINCORE_PAGED_OUT)) *pool_touched += pg; }
        }
    }
}
// #1117：驻留集按类拆（同一时刻的快照，字节）：k[0..1] 纹理 个数 / 字节，k[2..3] GPU 独占（私有）缓冲，k[4..5] 共享缓冲（多是零拷贝的内存池缓冲，
//   存储就是游戏内存本身、不另占），k[6..7] 其他。footprint 只给总量，长局只涨不落时先看是哪一类在涨。视图的 allocatedSize 是 0，不重复算
void nvn_res_by_kind(uint64_t k[8]) {
    memset(k, 0, 8 * sizeof k[0]);
    @autoreleasepool { pthread_mutex_lock(&g_res_mu);
        for (id o in g_res_objects) { uint64_t b = res_bytes(o); int c;
            if ([o conformsToProtocol:@protocol(MTLTexture)]) c = 0;
            else if ([o conformsToProtocol:@protocol(MTLBuffer)]) c = ((id<MTLBuffer>)o).storageMode == MTLStorageModePrivate ? 1 : 2;
            else c = 3;
            k[c * 2]++; k[c * 2 + 1] += b; }
        pthread_mutex_unlock(&g_res_mu); }
}
// 贴图按大小前 10（11-16，马车世界 Mac 第 300 帧驻留集贴图 2287 张 31 GB、内存池才 7 GB）：只知总量定不了是哪类贴图在吃，
//   贴图合计超过 4 GB 时列最大的 10 张（Metal 尺寸 / 层 / mip / 格式 / 存储 / 用途 / 标签），全程最多记 5 次
static void tex_top_report(unsigned long long frame) {
    static int said; if (said >= 5) return;
    enum { N = 10 }; id top[N] = {nil}; uint64_t tb[N] = {0}, total = 0; unsigned long nt = 0;
    @autoreleasepool { pthread_mutex_lock(&g_res_mu);
        for (id o in g_res_objects) { if (![o conformsToProtocol:@protocol(MTLTexture)]) continue;
            uint64_t b = res_bytes(o); total += b; nt++;
            for (int i = 0; i < N; i++) if (b > tb[i]) { for (int j = N - 1; j > i; j--) { tb[j] = tb[j - 1]; top[j] = top[j - 1]; } tb[i] = b; top[i] = o; break; } }
        pthread_mutex_unlock(&g_res_mu);
        if (total < (4ull << 30)) return;
        said++;
        MLOG("textures by size up to frame %llu: %lu textures %llu MB in the residency set; largest %d:", frame, nt, (unsigned long long)(total >> 20), N);
        for (int i = 0; i < N && top[i]; i++) { id<MTLTexture> t = top[i];
            MLOG("  #%d %llu MB: %lux%lux%lu array %lu mips %lu samples %lu type %lu format %lu storage %lu usage %#lx", i + 1, (unsigned long long)(tb[i] >> 20),
                 (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.depth, (unsigned long)t.arrayLength, (unsigned long)t.mipmapLevelCount, (unsigned long)t.sampleCount,
