        MLOG("command allocator usage:%s", ab);
        MLOG("GPU allocation growth by function: pass end %llu MB, pass begin %llu MB, pipeline fetch %llu MB, argument buffers %llu MB, texture fetch %llu MB", g_ap_fn[0] >> 20, g_ap_fn[1] >> 20, g_ap_fn[2] >> 20, g_ap_fn[3] >> 20, g_ap_fn[4] >> 20); }
    if (g_allocprof > 0) { int top[4] = {-1, -1, -1, -1}; for (int o = 0; o < 64; o++) for (int k = 0; k < 4; k++) if (top[k] < 0 || g_ap_bytes[o] > g_ap_bytes[top[k]]) { for (int j = 3; j > k; j--) top[j] = top[j - 1]; top[k] = o; break; }
        MLOG("GPU allocation growth by op: op%d %llu MB, op%d %llu MB, op%d %llu MB, op%d %llu MB", top[0], g_ap_bytes[top[0]] >> 20, top[1], g_ap_bytes[top[1]] >> 20, top[2], g_ap_bytes[top[2]] >> 20, top[3], g_ap_bytes[top[3]] >> 20); }
}
void nvn_be_pkg_stats(uint64_t *uploads, uint64_t *reuploads) { *uploads = g_pkg_uploads; *reuploads = g_pkg_reuploads; }
uint64_t nvn_be_pkg_same(void) { return g_pkg_same; }
void nvn_be_pkg_gpu_stats(uint64_t *writes, uint64_t *kept, uint64_t *partial) { *writes = g_pkg_gpu_writes; *kept = g_pkg_gpu_kept; *partial = g_pkg_partial; }   // GPU writes into uploaded textures; checks that left the GPU's content; partial re-uploads   // written pages whose texture bytes were unchanged: re-uploads skipped
uint64_t nvn_be_pkg_miss(void) { return g_pkg_miss; }
// Texture lifecycle counters (DM_NVN_ALLOCPROF): init / host-creation failure / release. The failure lines above already carry ser= / samples / levels;
//   these counters answer the other question a diagnostic log has to answer: "did the game issue any texture creation in this window at all?"
//   A flat init counter means the guest never asked (game-side), not that the host refused (host-side) — the two need different follow-ups.
void nvn_be_tex_counters(uint64_t *init, uint64_t *rel) {
    if (init) *init = atomic_load(&g_tex_init_n);
    if (rel)  *rel  = atomic_load(&g_tex_rel_n);
}
void nvn_be_tex_tick(uint64_t frame) {
    if (g_allocprof < 0) g_allocprof = getenv("DM_NVN_ALLOCPROF") != NULL;
    if (g_allocprof <= 0 || (frame % 300) != 0) return;
    static uint64_t pi, pr;
    uint64_t i = atomic_load(&g_tex_init_n), r = atomic_load(&g_tex_rel_n);
    MLOG("[tex] frame %llu: init %llu (+%llu) / release %llu (+%llu) / live %lld",
         (unsigned long long)frame, (unsigned long long)i, (unsigned long long)(i - pi),
         (unsigned long long)r, (unsigned long long)(r - pr), (long long)(i - r));
    pi = i; pr = r;
}
void mtl_vc_drop(uint64_t ser);
void nvn_be_tex_release(tex_t *t) {
    if (!t->serial) return;
    atomic_fetch_add(&g_tex_rel_n, 1);
    pthread_mutex_lock(&g_smu);
    nvn_hm_del(&g_tex_live, &t->serial);
    nvn_hm_del(&g_snap_texaddr, &t->serial);   // 即时存档的「序号 → 对象地址」表跟着删：原先只增不删，随游玩时长涨，存档时逐项查可读（每项一次系统调用）越来越慢
    id holder = hm_get_id(&g_by_serial, &t->serial);
    if ([holder isKindOfClass:[NvPkg class]]) {
        // #778 (reporter shengyifan's minimal repro): a texture the GPU wrote (NvPkg) is finalized while recorded commands still sample it by this serial
        //   (late / in flight). Dropping it from g_by_serial made tex_get re-create it from the all-zero guest storage (BotW's 100x56 / 400x225 R8 masks:
        //   one-frame light / dark flashes on iPad). Keep the GPU result under the existing bounded ghost-ring lifetime instead, as tex_put does for evicted ones
        tex_put_locked(t->serial, holder);
        hm_del_id(&g_by_serial, &t->serial);   // borrow-safe: the ghost ring keeps holder (tex_put_locked above), so a replay borrowing it this submission still has it
    }
    pthread_mutex_unlock(&g_smu);
    serial_del(t->serial);
    mtl_vc_drop(t->serial);
    gpw_forget(t->serial);
    wd_release(t->serial);
    // Idempotent: nvnTextureFinalize clears magic but NOT serial, so a repeated Finalize used to walk this whole path a second time
    //   (release counter inflated until "live" went negative). Zeroing the serial makes the second call return at the line above.
    t->serial = 0;
}

// ---------- Render passes: SetRenderTargets opens a new pass; clears before the first command in the pass are folded into the load action ----------
static struct {
    p_set_rt rt; int has_rt;
    tex_t kept[9];   // owned target snapshots, included when a parked queue saves/restores R
    uint8_t clear_c[8]; MTLClearColor cc[8];
    uint8_t clear_d, clear_s; double cd; uint32_t cs;
    p_scissor sc; int has_sc;
} R;

// SetRenderTargets points into command records, including host shadow blocks
// that can be recycled after completion. Read all sources before updating the
// retained slots: inherited bindings can already point into R.kept itself.
static void rt_keep_state(void) {
    if (!R.has_rt) return;
    tex_t values[9]; unsigned present = 0;
    for (int i = 0; i < R.rt.n && i < 8; i++) if (R.rt.color[i]) {
        values[i] = *R.rt.color[i]; present |= 1u << i;
    }
    if (R.rt.depth) { values[8] = *R.rt.depth; present |= 1u << 8; }
    for (int i = 0; i < 9; i++) if (present & (1u << i)) R.kept[i] = values[i];
    for (int i = 0; i < 8; i++) if (present & (1u << i)) R.rt.color[i] = &R.kept[i];
    if (present & (1u << 8)) R.rt.depth = &R.kept[8];
}

// ---------- Zero-source skip ----------
// Shader fact table (statically proven keys): 'the textures it samples are all 0 and the coefficient is finite ⇒ the output is all 0'. Coefficient = component comp of vector vec of fragment-stage constant buffer register ubo_slot.
//   Entries come from the game profile's zero_skip (zskip_facts_load; the list with each proof is graphics/nvn/games/zero_skip.tsv): a proof comes from reading the shader's translation line by line
//   (dmsh_b/<chain version>/<key>_b.metal); unit tests add their own (zskip_test_add).
typedef struct { char key[17]; int ubo_slot, vec, comp; } zskip_fact;
static zskip_fact g_zskip_facts[16];
static int g_zskip_nf;
void zskip_test_add(const char *key, int ubo_slot, int vec, int comp) {
    if (!key || g_zskip_nf >= 16) return;
    snprintf(g_zskip_facts[g_zskip_nf].key, sizeof g_zskip_facts[0].key, "%s", key);
    g_zskip_facts[g_zskip_nf].ubo_slot = ubo_slot; g_zskip_facts[g_zskip_nf].vec = vec; g_zskip_facts[g_zskip_nf].comp = comp; g_zskip_nf++;
}
int zskip_test_count(void) { return g_zskip_count; }
static int g_zskip_env = -1;   // Cache of DM_NVN_ZSKIP (−1 = not read). This function is called on every draw, and getenv once took about 8% of the submit path; unit tests set it back to −1 after toggling the switch mid-run
static int zskip_on(void) { if (g_zskip_env < 0) { const char *e = getenv("DM_NVN_ZSKIP"); g_zskip_env = !e || strcmp(e, "0"); } return g_zskip_env && tbdr_on(); }
static void zskip_clear(void) { g_zskip_n = 0; memset(g_zskip_cand_ok, 0, sizeof g_zskip_cand_ok); }
static void zskip_del(uint64_t ser) { for (int i = 0; i < g_zskip_n;) if (g_zskip_zero[i].ser == ser) g_zskip_zero[i] = g_zskip_zero[--g_zskip_n]; else i++; }
static int zskip_has(uint64_t ser, int lv, int sl) { for (int i = 0; i < g_zskip_n; i++) if (g_zskip_zero[i].ser == ser && g_zskip_zero[i].level == lv && g_zskip_zero[i].slice == sl) return 1; return 0; }
static void zskip_add(uint64_t ser, int lv, int sl) { if (!ser || zskip_has(ser, lv, sl) || g_zskip_n >= 4096) return; g_zskip_zero[g_zskip_n++] = (zskip_zero){ser, (uint16_t)lv, (uint16_t)sl}; }
static int zskip_zero_clear(int i) { return R.clear_c[i] && R.cc[i].red == 0 && R.cc[i].green == 0 && R.cc[i].blue == 0 && R.cc[i].alpha == 0; }
static void zskip_commit_clears(void) { for (int i = 0; i < 8; i++) if (g_zskip_cand_ok[i]) zskip_add(g_zskip_cand[i].ser, g_zskip_cand[i].level, g_zskip_cand[i].slice); }
static int zskip_target_zero(const tex_t *t, const view_t *v, int hv) { int lv = hv && v->set_levels ? v->base_level : 0, sl = hv && v->set_layers ? v->min_layer : 0; return t && zskip_has(t->serial, lv, sl); }
