    MTLPixelFormat pf; const char *no = rtdup_no(&R.rt, i, tex_mtl(R.rt.color[i]), &pf);
    if (!no && g_rp_layered) no = "layered pass";
    if (no) { g_rtdup_why[i] = no; return 0; }
    attach(a, R.rt.color[i], &R.rt.cview[i], R.rt.has_cview[i]);
