    if (!dst || pf_int_kind(dst.pixelFormat)) { a.texture = nil; g_rtdup_why[i] = dst ? "integer format" : "not attachable"; return 0; }
    NSUInteger lv = a.level, sl = a.slice, w = mip_extent(dst.width, lv), h = mip_extent(dst.height, lv);
