        if (g_qf_sgen[i] != g_qf_gen) { uint32_t e = g_qf_n++; g_qf_ptr[e][0] = a; g_qf_ptr[e][1] = pb; g_qf_ent[e] = (qf_ent){qf_hex(sa), qf_hex(sb), kind}; g_qf_sgen[i] = g_qf_gen; g_qf_slot[i] = e; return; }
