    if (!sh_fn_constants(o, lib, fnn(o, entry), o->fn_u ? fnn(o, j[@"entry_u"]) : nil, stage, pc)) return nil;
    if (!shader_args_init(o)) return nil;
    if (o->rf.has_c1 && !t_hydrate) c1_store(o);
