// The fallback directory's <key>_se.metal is of this host's format version (an older host's is made again at the first use, which has the guest code: se_build)
static int se_file_current(const char *key) {
    const char *fb = getenv("DM_MSL_FALLBACK"); if (!fb || !*fb) return 0;
    char p[1200], l[64] = ""; snprintf(p, sizeof p, "%s/%.16s_se.metal", fb, key); FILE *f = fopen(p, "r"); if (!f) return 0;
    char want[48]; snprintf(want, sizeof want, "// s2a:samp-emu %d ", SE_VERSION); int ok = fgets(l, sizeof l, f) && !strncmp(l, want, strlen(want)); fclose(f); return ok;
}
static int se_lib_fold(id<MTLLibrary> lib) { return [lib.functionNames containsObject:@"s2a_se_fold"]; }   // the variant reads folded textures (S2A.Dsh RedHelp's marker kernel; format 4 on)
static id<MTLFunction> se_build(NvShader *sh, const uint8_t md[8], uint64_t code, const void *ctl, char *why, size_t n) {
    const char *fb = getenv("DM_MSL_FALLBACK");
    if (!fb || !*fb) { snprintf(why, n, "DM_MSL_FALLBACK is not set"); return nil; }
    if (!dm_shader_se_fresh(sh->key)) {
        char path[1200]; int rc;
        // 游戏已收回控制段：本机同链源码，或包里的客体输入（库容器种类 56，dm_shader_se_cached；同顶点补齐 vp_build）
        if (!code) { rc = dm_shader_se_cached(md, sh->stage == 5 ? 2 : 1, path, sizeof path);
            if (rc == 1) { snprintf(why, n, "the game no longer holds its control section, and neither the package (guest input, kind 56) nor this device has a translation of it"); return nil; } }
        else rc = dm_shader_se(md, code, ctl, path, sizeof path);
        if (rc) { snprintf(why, n, "%s", rc == 3 ? "main0 samples through no sampler member the variant rewrites" : "the device could not make it"); return nil; }
    }
    char p[1200]; snprintf(p, sizeof p, "%s/%.16s_se.metal", fb, sh->key);
    NSString *src = [NSString stringWithContentsOfFile:@(p) encoding:NSUTF8StringEncoding error:nil], *ver = [NSString stringWithFormat:@"// s2a:samp-emu %d ", SE_VERSION];
    // A variant an older host made (another format version, still fresh by its source): made again from the guest code when there is some (version 4 added folded textures, 11-03)
    if (src && ![src hasPrefix:ver] && code && !dm_shader_se(md, code, ctl, p, sizeof p)) { snprintf(p, sizeof p, "%s/%.16s_se.metal", fb, sh->key); src = [NSString stringWithContentsOfFile:@(p) encoding:NSUTF8StringEncoding error:nil]; }
    if (!src || ![src hasPrefix:ver]) { snprintf(why, n, "%s %s", p, src ? "is of another format" : "is unreadable"); return nil; }
    NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:src options:dm_msl_opts() error:&e];
    if (!lib) { snprintf(why, n, "failed to build: %s", e.localizedDescription.UTF8String); return nil; }
    id<MTLFunction> f = lib_entry(lib, @"main0");
    NSUInteger al = f && sh->rf.nb ? [f newArgumentEncoderWithBufferIndex:sh->rf.abi].encodedLength : sh->arg_len;
    if (!f || al != sh->arg_len) { snprintf(why, n, "%s", f ? "it takes another argument buffer than the library's main0" : "it has no main0"); return nil; }
    sh->se_fold = se_lib_fold(lib);
    return f;
}
// The variant the package precompiled (library container kind LP_K_SE, <key>_se.metallib, entry main0, or s<key>_main0 in a batched one; the package builds it for the keys whose pipelines a census run recorded
//   with the SE_RD bit: pso_user.tsv C lines' fc, R lines' pso_key.fc): loaded at once, so its first draw already runs it. nil: not in the package (made on the device, se_build)
static id<MTLFunction> se_packed(NvShader *sh) {
    char nm[32]; snprintf(nm, sizeof nm, "%.16s_se", sh->key);
    if (!lp_pack_get()) return nil;
    NSError *e = nil; id<MTLLibrary> lib = lib_from_pack(nm, &e); if (!lib) return nil;
    // a batched variant library (11-20: the package compiles the variants in batches, S2A.Dsh Build.SeFinish): its functions are s<key>_main0 / s<key>_main0_fold (the folded-texture marker s2a_se_fold, renamed so a batch has one per key)
    NSString *pre = [NSString stringWithFormat:@"s%.16s_", sh->key];
    BOOL batched = [lib.functionNames containsObject:[pre stringByAppendingString:@"main0"]];
    id<MTLFunction> f = lib_entry(lib, batched ? [pre stringByAppendingString:@"main0"] : @"main0");
    NSUInteger al = f && sh->rf.nb ? [f newArgumentEncoderWithBufferIndex:sh->rf.abi].encodedLength : sh->arg_len;
    if (!f || al != sh->arg_len) { MLOG("【红】 packaged sampler-emulation variant %s %s: made on the device instead", nm, f ? "takes another argument buffer than the library's main0" : "has no main0"); return nil; }
    sh->se_fold = batched ? [lib.functionNames containsObject:[pre stringByAppendingString:@"main0_fold"]] : se_lib_fold(lib);
    return f;
}
// The variant is there (f) or not (why): published to the draws (se_st), counted, one line (t0: when its first use asked for it; how: 包内 / 后台编 / 同步现编)
// 审计 #1534 P1-96：读折行贴图的绘制等变体时用（se_fold_wait）。变体的状态离开 SE_BUSY 时广播：se_done、预热放弃（se_warm 退回 SE_NONE）
static pthread_mutex_t g_se_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_se_cv = PTHREAD_COND_INITIALIZER;
static void se_signal(void) { pthread_mutex_lock(&g_se_mu); pthread_cond_broadcast(&g_se_cv); pthread_mutex_unlock(&g_se_mu); }
static void se_done(NvShader *sh, id<MTLFunction> f, const char *why, uint64_t t0, const char *how) {
    if (f) sh->se_main = f;
    __atomic_store_n(&sh->se_st, f ? SE_READY : SE_FAIL, __ATOMIC_RELEASE); se_signal();
    atomic_fetch_add(f ? &g_se_made : &g_se_failed, 1);
    fprintf(stderr, "[s2a] 归约变体：程序号 %s 着色器 %.16s %s%s %.1f ms%s%s\n", s2a_nvn_game_id(), sh->key, how, f ? "完成" : "失败", (bp_now() - t0) / 1e6, f ? "" : "：", f ? "" : why);
    if (!f) MLOG("【红】 shader %s binds a sampler this GPU cannot do natively (min / max without native reduction, or a custom border colour), but it has no emulation variant: %s; its draws keep main0 (averaged / nearest standard border colour)", sh->key, why);
}
static int se_sync(void) {   // S2A_SE_SYNC=1: the variant is made on the submit thread at its first use (se_want)
    static int v; static dispatch_once_t once;
    dispatch_once(&once, ^{ const char *e = getenv("S2A_SE_SYNC"); v = e && !strcmp(e, "1"); if (v) MLOG("S2A_SE_SYNC=1: sampler reduction variants are made on the submit thread at their first use"); });
    return v;
}
// Ask for the variant at the shader's first use that needs it (se_want, submit thread; the caller claimed the shader). The guest code / control come from program p as for
//   pso_fout_variant: the control section is only valid during SetShaders, so its key is recomputed (prog_stage_of); for the background both are copied here first (dm_shader_snap)
static dispatch_queue_t se_queue(void) {   // the background queue of se_kick (a function so t_nvn_red can hold it: dispatch_suspend until its first draw is read back)
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.se", s2a_qos_queue_attr(DISPATCH_QUEUE_SERIAL, S2A_QOS_SHADER_VARIANT)); });
    return q;
}
static void se_kick(const prog_t *p, NvShader *sh, int sync) {   // sync: made here on the submit thread (S2A_SE_SYNC=1, or a draw reading a folded texture: se_want)
    uint8_t md[8] = {0}; int at = p ? prog_stage_of(p, sh->key, md) : -1; uint64_t t0 = bp_now();
    if (sync || se_sync()) { char why[300] = ""; id<MTLFunction> f = se_build(sh, md, at < 0 ? 0 : p->sd[at].data, at < 0 ? NULL : p->sd[at].control, why, sizeof why); se_done(sh, f, why, t0, "同步现编"); return; }
    uint64_t code = 0; const void *ctl = NULL; void *snap = at < 0 ? NULL : dm_shader_snap(p->sd[at].data, p->sd[at].control, &code, &ctl); uint64_t key; memcpy(&key, md, 8);
    fprintf(stderr, "[s2a] 归约变体：程序号 %s 着色器 %.16s 首遇，后台编，编好前这支照常用 main0 画（取平均）\n", s2a_nvn_game_id(), sh->key);
    dispatch_async(se_queue(), ^{ @autoreleasepool {
        if (dm_gfx_session_stopping()) { free(snap); return; }
        uint8_t m[8]; memcpy(m, &key, 8); char why[300] = "";
        id<MTLFunction> f = se_build(sh, m, code, ctl, why, sizeof why); free(snap);
        se_done(sh, f, why, t0, "后台编");
    } });
}
// v0.4.1 重译抢跑（#065090）：出包库里旧翻译器出的计算着色器（pkg_oldx），管线编满 5 秒还没完时，pso_archive.h par_compute_wait 在后台调这里：
//   按本机翻译器重出源码（dm_shader_retrans，带大计算核拆分），核对能原样顶替，编出管线。做不了 / 不必要 → nil（原管线照等）。
//   顶替的条件：新 MSL 的摘要不等于出包函数名里的摘要（相等 = 内容没变，重编也一样慢）；宿主读的反射字段（rt_same_keys）与出包 json 相同；参数缓冲长度相同（同 se_build）。
//   赢了就留 <键>.retrans 标记，下一局 shader_build 直接载本机这份
static const char *const rt_same_keys[] = {"stage", "entry", "bindings", "threadgroup_size", "c1", "cbuf_use", "spill", "spill_slot", "s2a_push", "tex_scales",
    "resolution_scale_abi", "resolution_scale_exact", "scale_exact", "tensor_mma_count", "drv_reads", "drv_unfillable"};
static id<MTLComputePipelineState> cps_retrans(NvShader *cs, const uint8_t md[8], uint64_t code, const void *ctl) {
    const char *fb = getenv("DM_MSL_FALLBACK"); NSString *pc = @(cs->key); uint64_t t0 = bp_now(); char why[200] = "";
    id<MTLComputePipelineState> ps = nil;
    do {
        if (!fb || !*fb) { snprintf(why, sizeof why, "DM_MSL_FALLBACK is not set"); break; }
        if (dm_shader_retrans(md, code, ctl)) { snprintf(why, sizeof why, "the device could not translate it"); break; }
        NSString *src = [NSString stringWithContentsOfFile:[NSString stringWithFormat:@"%s/%@.metal", fb, pc] encoding:NSUTF8StringEncoding error:nil];
        NSData *fj = [NSData dataWithContentsOfFile:[NSString stringWithFormat:@"%s/%@.json", fb, pc]], *pj = json_from_pack(cs->key);
        NSDictionary *nj = fj ? [NSJSONSerialization JSONObjectWithData:fj options:0 error:nil] : nil, *oj = pj ? [NSJSONSerialization JSONObjectWithData:pj options:0 error:nil] : nil;
        if (!src || ![nj isKindOfClass:[NSDictionary class]] || ![oj isKindOfClass:[NSDictionary class]]) { snprintf(why, sizeof why, "its source or reflection is unreadable"); break; }
        const char *u = src.UTF8String; uint8_t d[CC_SHA256_DIGEST_LENGTH]; CC_SHA256(u, (CC_LONG)strlen(u), d);
        char pfx[24]; snprintf(pfx, sizeof pfx, "s%02x%02x%02x%02x%02x%02x%02x%02x_", d[0], d[1], d[2], d[3], d[4], d[5], d[6], d[7]);
        if ([cs->fnpfx isEqualToString:@(pfx)]) { snprintf(why, sizeof why, "this build translates it to the same MSL as the package"); break; }
        for (size_t i = 0; i < sizeof rt_same_keys / sizeof *rt_same_keys && !why[0]; i++) { NSString *f = @(rt_same_keys[i]); id a = nj[f], b = oj[f];
            if ((a || b) && ![a isEqual:b]) snprintf(why, sizeof why, "its reflection field %s differs from the package's", rt_same_keys[i]); }
        if (why[0]) break;
        NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:src options:dm_msl_opts() error:&e];
        if (!lib) { snprintf(why, sizeof why, "failed to build: %s", e.localizedDescription.UTF8String); break; }
        NSString *fp = [nj[@"fn_prefix"] isKindOfClass:[NSString class]] ? nj[@"fn_prefix"] : @"";
        id<MTLFunction> f = lib_entry(lib, [fp stringByAppendingString:@"main0"]);
        NSUInteger al = f && cs->rf.nb ? [f newArgumentEncoderWithBufferIndex:cs->rf.abi].encodedLength : cs->arg_len;
        if (!f || al != cs->arg_len) { snprintf(why, sizeof why, "%s", f ? "it takes another argument buffer than the package's main0" : "it has no main0"); break; }
        ps = [g_dev newComputePipelineStateWithFunction:f error:&e];
        if (!ps) { snprintf(why, sizeof why, "failed to create its pipeline: %s", e.localizedDescription.UTF8String); break; }
        int fd = open([NSString stringWithFormat:@"%s/%@.retrans", fb, pc].fileSystemRepresentation, O_CREAT | O_WRONLY, 0644); if (fd >= 0) close(fd);
    } while (0);
    if (ps) MLOG("compute shader %s: retranslated on this device (%s) and built in %.0f ms: this dispatch runs it, and later runs load it instead of the package's", cs->key, cs->mslnote.UTF8String ?: "-", (bp_now() - t0) / 1e6);
    else MLOG("%scompute shader %s: no retranslation to replace its slow compile (%s): its own compile is waited for", strstr(why, "same MSL") ? "" : "【红】 ", cs->key, why);   // 同一份 MSL 是正常结论（本机翻译器对它没改动）
    return ps;
}
// S2Arm (10-30, Kirby Star Allies, census c1029c: "vertex … does not write user(locn) mask 0x8 that fragment … reads: draw skipped"): a vertex shader the game pairs at run time with a
//   pixel shader that reads a user(locn) it does not write. Metal refuses the pipeline (pso_pair_ok). The package's pairs (shader_pairs.tsv → offline vs_pad) cannot know every pair a
//   game makes stage by stage, and the old answer (skip the draw, record the pair in pso_user.tsv for the next build) never reached a player: the package is built once.
//   Now the variant is made on this device at the pair's first use (vp_ask, submit thread): S2A.Dsh writes <key>_vp<mask>.metal (dm_shader_vpad: the shader's own translation with
//   those outputs (0,0,0,1), the offline vs_pad's rule, what the hardware reads there) and it is compiled in the background (vp_kick); until it is ready the pair's draws are skipped
//   as before, from the next draw after it they draw with it (pso_desc). One variant per vertex shader, for the union of the masks asked for: a pair that needs more rebuilds it.
//   S2A_SE_SYNC=1 makes it on the submit thread too. One line per variant ("[s2a] 顶点补齐变体：…"), and a count in the run's summary (mtl_vp_stats)
static pthread_mutex_t g_vp_mu = PTHREAD_MUTEX_INITIALIZER;
static _Atomic uint64_t g_vp_made, g_vp_failed;
void mtl_vp_stats(uint64_t out[2]) { out[0] = atomic_load(&g_vp_made); out[1] = atomic_load(&g_vp_failed); }
static uint32_t pso_pair_miss(NvShader *vs, NvShader *fs) {   // the user(locn) fs reads and vs does not write (0 = none, or positions unknown on either side)
    if (!vs || !fs || !(vs->rf.has_user & 1) || !(fs->rf.has_user & 2)) return 0;
    return fs->rf.user_in & ~vs->rf.user_out;
}
// 0.6.0 出包着色器全覆盖：the package's <key>_vp (container kind LP_K_VP, Build.cs VpFinish) pads the union of every pixel shader's user(locn) inputs the vertex shader does not
//   write, so it covers any pair's miss; its mask rides in the library as an empty function dm_vp_mask_<hex>. Tried once per shader (vp_pk); not there / unusable: the device makes
//   one per pair at first use as before (vp_ask)
static void vp_pack(NvShader *vs) {
    pthread_mutex_lock(&g_vp_mu); int tried = vs->vp_pk, st = vs->vp_st; vs->vp_pk = 1; pthread_mutex_unlock(&g_vp_mu);
    if (tried || st == SE_READY || st == SE_BUSY || !lp_pack_get()) return;
    char nm[32]; snprintf(nm, sizeof nm, "%.16s_vp", vs->key);
    NSError *e = nil; id<MTLLibrary> lib = lib_from_pack(nm, &e); if (!lib) return;
    // a batched variant library (11-20, Build.cs VarBatches): the shader's functions are s<key>_<entry> and its mask s<key>_main0_vpmask_<hex>
    NSString *pre = [NSString stringWithFormat:@"s%.16s_", vs->key], *ent = vs->ventry;
    BOOL batched = [lib.functionNames containsObject:[pre stringByAppendingString:ent]];
    NSString *mp = batched ? [pre stringByAppendingString:@"main0_vpmask_"] : @"dm_vp_mask_";
    uint32_t mask = 0;
    for (NSString *n in lib.functionNames) if ([n hasPrefix:mp]) mask = (uint32_t)strtoul(n.UTF8String + mp.length, NULL, 16);
    id<MTLFunction> f = lib_entry(lib, batched ? [pre stringByAppendingString:ent] : ent);
    NSUInteger al = f && vs->rf.nb ? [f newArgumentEncoderWithBufferIndex:vs->rf.abi].encodedLength : vs->arg_len;
    if (!f || !mask || al != vs->arg_len) { MLOG("【红】 packaged padded vertex variant %s %s: made on the device per pair instead", nm, !f ? "has no such entry" : !mask ? "carries no mask" : "takes another argument buffer than the library's entry"); return; }
    pthread_mutex_lock(&g_vp_mu); int took = vs->vp_st != SE_READY; if (took) { vs->vp_main = f; vs->vp_mask = mask; vs->vp_st = SE_READY; } pthread_mutex_unlock(&g_vp_mu);
    static _Atomic uint64_t n; uint64_t c = took ? atomic_fetch_add(&n, 1) + 1 : 0;
    if (c && (c <= 8 || !(c & (c - 1)))) MLOG("vertex %s: packaged padded variant in use (user(locn) mask %#x), no device build (%llu so far)", vs->key, mask, (unsigned long long)c);
}
static id<MTLFunction> vp_fn(NvShader *vs, uint32_t miss) {   // the padded variant when it covers miss, else nil (any thread)
    pthread_mutex_lock(&g_vp_mu); id<MTLFunction> f = vs->vp_st == SE_READY && (vs->vp_mask & miss) == miss ? vs->vp_main : nil; pthread_mutex_unlock(&g_vp_mu);
    return f;
}
// Make the variant and load it: S2A.Dsh writes it from the guest code / control (code 0: none to make it from). → the shader's entry point in it, nil with why
static id<MTLFunction> vp_build(NvShader *vs, const uint8_t md[8], uint64_t code, const void *ctl, uint32_t mask, char *why, size_t n) {
    char path[1200]; int rc;
    if (!code) {   // the game reused its control section: this device's translation, or the package's guest input (container kind 56, dm_shader_vpad_cached)
        rc = dm_shader_vpad_cached(md, vs->mesh_kind == 2 ? 5 : 0, mask, path, sizeof path);
        if (rc == 1) { snprintf(why, n, "the game no longer holds its control section, and neither the package (guest input, kind 56) nor this device has a translation of it"); return nil; }
    }
    else rc = dm_shader_vpad(md, code, ctl, mask, path, sizeof path);
    if (rc) { snprintf(why, n, "%s", rc == 3 ? "its translation already writes those outputs (or has no main0_out to add them to)" : "the device could not make it"); return nil; }
    NSString *src = [NSString stringWithContentsOfFile:@(path) encoding:NSUTF8StringEncoding error:nil];
    if (!src || ![src hasPrefix:@"// s2a:vs-pad 1 "]) { snprintf(why, n, "%s %s", path, src ? "is of another format" : "is unreadable"); return nil; }
    NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:src options:dm_msl_opts() error:&e];
    if (!lib) { snprintf(why, n, "failed to build: %s", e.localizedDescription.UTF8String); return nil; }
    id<MTLFunction> f = lib_entry(lib, vs->ventry);   // the logical entry the library's function is (main0 / main0_z / the layer ones); a source library has no name prefix
    NSUInteger al = f && vs->rf.nb ? [f newArgumentEncoderWithBufferIndex:vs->rf.abi].encodedLength : vs->arg_len;
    if (!f || al != vs->arg_len) { snprintf(why, n, "%s", f ? "it takes another argument buffer than the library's entry" : "it has no such entry"); return nil; }
    return f;
}
static void vp_done(NvShader *vs, id<MTLFunction> f, uint32_t mask, const char *why, uint64_t t0, const char *how) {
    pthread_mutex_lock(&g_vp_mu); if (f) { vs->vp_main = f; vs->vp_mask = mask; } vs->vp_st = f ? SE_READY : SE_FAIL; pthread_mutex_unlock(&g_vp_mu);
    atomic_fetch_add(f ? &g_vp_made : &g_vp_failed, 1);
    fprintf(stderr, "[s2a] 顶点补齐变体：程序号 %s 顶点 %.16s 补 user(locn) 掩码 %#x %s%s %.1f ms%s%s\n", s2a_nvn_game_id(), vs->key, mask, how, f ? "完成" : "失败", (bp_now() - t0) / 1e6, f ? "" : "：", f ? "" : why);
    if (!f) MLOG("【红】 vertex shader %s has no padded variant for user(locn) mask %#x: %s; draws pairing it with such a fragment shader stay skipped", vs->key, mask, why);
}
// Prewarm (background thread): a recorded padded mesh row (pso_user.tsv M row, pad mask) whose variant this run has not made yet. It is made here from this device's own
//   variant on disk (code 0: dm_shader_vpad_cached; an earlier run wrote it when the draw first asked), so the pipeline the prewarm builds is the padded one and the draw finds it.
//   Before (#1269, D-FVDM 0400486024DEC000): mtk_warm skipped the row because the variant was not ready, so every run the first draw built the unpadded pipeline, Metal refused it
//   (user(locn5) not written), and the pair's draws were skipped until vp_ask had made the variant in the background. Nothing on disk to make it from: the state goes back to SE_NONE
//   (not SE_FAIL, which would stop the draw's own vp_ask from trying with the guest's code) and the row is skipped as before. → the variant covering mask, or nil
static id<MTLFunction> vp_warm(NvShader *vs, uint32_t mask) {
    pthread_mutex_lock(&g_vp_mu);
    if (vs->vp_st == SE_READY && (vs->vp_mask & mask) == mask) { id<MTLFunction> f = vs->vp_main; pthread_mutex_unlock(&g_vp_mu); return f; }
    if (vs->vp_st != SE_NONE) { pthread_mutex_unlock(&g_vp_mu); return nil; }   // being made by the draw's vp_ask, failed, or a narrower variant is ready: leave it to the draw
    // only a variant an earlier run already wrote (<key>_vp<mask>.metal; dm_shader_vpad_cached still checks it is this chain's and not older than its source): the prewarm
    //   does not translate, and with no translation on disk the cached path would translate from the package's guest input here, on the prewarm thread
    const char *fb = getenv("DM_MSL_FALLBACK"); char vp[1200];
    if (!fb || !*fb || snprintf(vp, sizeof vp, "%s/%.16s_vp%x.metal", fb, vs->key, mask) >= (int)sizeof vp || access(vp, R_OK)) { pthread_mutex_unlock(&g_vp_mu); return nil; }
    vs->vp_st = SE_BUSY; pthread_mutex_unlock(&g_vp_mu);
    uint8_t md[8] = {0}; for (int i = 0; i < 8; i++) { unsigned b = 0; if (sscanf(vs->key + 2 * i, "%2x", &b) != 1) break; md[i] = (uint8_t)b; }
    char why[300] = ""; uint64_t t0 = bp_now(); id<MTLFunction> f = vp_build(vs, md, 0, NULL, mask, why, sizeof why);
    if (f) { vp_done(vs, f, mask, why, t0, "预热按本机译文"); return f; }
    pthread_mutex_lock(&g_vp_mu); vs->vp_st = SE_NONE; pthread_mutex_unlock(&g_vp_mu);
    return nil;
}
// #674 (11-12): the program a draw passes to vp_ask is not always the one the shader to pad was bound from.
//   bind_stages makes a host stand-in carrying only a serial (no stages); a mesh draw's S.prog is the fragment
//   stage's program while its mesh shader was bound at stage 4. prog_stage_of then found nothing, vp_build saw
//   code = 0 and reported "the game no longer holds its control section" — a misread: the stages were never in
//   that program. vp_done pinned the variant to SE_FAIL and the caller put the pair on the failed list for the
//   whole run. Fall back to the per-stage binds (vp_prog_pick.h, tested by t_vp_prog_pick.c).
static int vp_stage_of_at(const void *prog, const char *key, uint8_t md[8], void *ctx) { (void)ctx; return prog_stage_of((const prog_t *)prog, key, md); }
static const void *vp_bst_at(unsigned st, void *ctx) { (void)ctx; return st < 5 ? (const void *)S.bst[st] : NULL; }
// A pair needs outputs the vertex shader does not write (miss): ask for the variant (submit thread). 1 = being made or just made (the caller skips this draw, nothing is recorded as
//   failed), 0 = it cannot be made (the caller records the pair as failed, as before)
static int vp_ask(const prog_t *p, NvShader *vs, uint32_t miss) {
    pthread_mutex_lock(&g_vp_mu);
    int st = vs->vp_st; uint32_t want = (st == SE_READY ? vs->vp_mask : 0) | miss;
    if (st == SE_BUSY || st == SE_FAIL || (st == SE_READY && (vs->vp_mask & miss) == miss)) { pthread_mutex_unlock(&g_vp_mu); return st != SE_FAIL; }
    vs->vp_st = SE_BUSY; pthread_mutex_unlock(&g_vp_mu);
    // The library shader's key stays valid after the guest reuses its program / control section: md always comes from vs->key
    //   (the cached mesh source is looked up by it); vp_pick_prog only supplies live guest inputs and leaves its own key copy at zero on a miss.
    uint8_t md[8] = {0}, live[8]; int at = -1; uint64_t t0 = bp_now();
    for (int i = 0; i < 8; i++) { unsigned b = 0; if (sscanf(vs->key + 2 * i, "%2x", &b) != 1) break; md[i] = (uint8_t)b; }
    const prog_t *gp = (const prog_t *)vp_pick_prog(p, vp_bst_at, 5, vs->key, live, vp_stage_of_at, NULL, &at);
    if (at < 0) { static unsigned n; if (!n++ || !(n & (n - 1))) MLOG("顶点补齐变体：%s 在绘制 program 与 5 个按阶段绑定的 program 里都没有有效控制段（%u 次）", vs->key, n); }
    if (se_sync()) { char why[300] = ""; id<MTLFunction> f = vp_build(vs, md, at < 0 ? 0 : gp->sd[at].data, at < 0 ? NULL : gp->sd[at].control, want, why, sizeof why); vp_done(vs, f, want, why, t0, "同步现编"); return f != nil; }
    uint64_t code = 0; const void *ctl = NULL; void *snap = at < 0 ? NULL : dm_shader_snap(gp->sd[at].data, gp->sd[at].control, &code, &ctl); uint64_t key; memcpy(&key, md, 8);
    fprintf(stderr, "[s2a] 顶点补齐变体：程序号 %s 顶点 %.16s 首遇缺 user(locn) 掩码 %#x，后台编，编好前这对的绘制照旧跳过\n", s2a_nvn_game_id(), vs->key, want);
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.vp", s2a_qos_queue_attr(DISPATCH_QUEUE_SERIAL, S2A_QOS_SHADER_VARIANT)); });
    dispatch_async(q, ^{ @autoreleasepool {
        if (dm_gfx_session_stopping()) { free(snap); pthread_mutex_lock(&g_vp_mu); vs->vp_st = SE_NONE; pthread_mutex_unlock(&g_vp_mu); return; }
        uint8_t m[8]; memcpy(m, &key, 8); char why[300] = "";
        id<MTLFunction> f = vp_build(vs, m, code, ctl, want, why, sizeof why); free(snap);
        vp_done(vs, f, want, why, t0, "后台编");
