    if (!b || !obj) { free(obj); RED_ONCE(172, "cannot allocate a %s pool table of %d IDs: its reads fault on the GPU", samp ? "sampler" : "texture", n); return -1; }
    res_add(b); res_commit(); g_pool_made++; g_pool_walks++;
