// A task shader's slot i (object stage table g_ot; the mesh stage shares the vertex table, enc_r_vbuf). Recorded as enc_r_vbuf records g_vt (nvn_rec.h)
static inline void enc_o_args(uint64_t gpu, NSUInteger i) { if (rec_on() && !g_m3) rec_table_op(RO_T_ADDR, g_ot, gpu, i); else tab_addr(g_ot, gpu, i); }
static int g_args_object;   // nonzero while a task / mesh draw binds its task shader (nvn_geometry.inc mtk_encode): stage 3 is the object stage, not the hull kernel
// #770 the host running a task / mesh stage as a compute kernel (nvn_geometry.inc mtk_emu_prep): the stage's argument block is captured here (g_args_compute 2) and bound at the
//   kernel's own dispatch later, whatever stage it belongs to
static uint64_t g_args_cap_gpu; static NSUInteger g_args_cap_ai; static int g_args_cap_ok, g_args_compute;
static void bind_args(id<MTLCommandEncoder> en, int nvn_stage, int metal_vertex, id<MTLBuffer> ab, uint64_t gpu, size_t off, NSUInteger ai) {
    if (g_args_compute == 2) { g_args_cap_gpu = gpu; g_args_cap_ai = ai; g_args_cap_ok = 1; return; }
    if (nvn_stage == 3 && g_args_object) { enc_o_args(gpu, ai); return; }
    if (nvn_stage == 5 || nvn_stage == 2 || nvn_stage == 3) enc_c_args((id<MTLComputeCommandEncoder>)en, gpu, ai);   // compute, the geometry kernel (geo_draw), the hull kernel (tess_draw ②)
    else enc_r_args((id<MTLRenderCommandEncoder>)en, metal_vertex ? MTLRenderStageVertex : MTLRenderStageFragment, gpu, ai);
}
// Static constant buffers of route B: the Ryujinx support_buffer (layout in Ryujinx.Graphics.Shader/SupportBuffer.cs: alpha_test u32 x4 (op, ref), is_bgra u32[8],
// viewport_inverse f4, viewport_size f4, frag_scale_count i32, render_scale f32[73]..., each field aligned to 16 bytes) and the all-0 driver constant segment (64 KB = the upper bound declared by shaders)
static id<MTLBuffer> support_buf(void) {
    static __strong id<MTLBuffer> b; if (b) return b;
    b = [g_dev newBufferWithLength:65536 options:MTLResourceStorageModeShared]; res_add(b);   // All 0 when newly created
    const int render_scale_off = 192;   // Measured MSL layout: alpha_test 0, is_bgra[8] 16, viewport_inverse 144, viewport_size 160, frag_scale_count 176, render_scale float4[73] 192 (take .x)
    for (int i = 0; i < 73; i++) *(float *)((uint8_t *)b.contents + render_scale_off + 16 * i) = 1.0f;
    // S2Arm: render_scale_y float4[73] at 1440 (after tfe_offset 1360, tfe_vertex_count 1376 and the s2a_flags / s2a_point / s2a_widen placeholders 1392 / 1408 / 1424: the
    // translator's SupportBuffer matches the generic mode's member for member; RenderScaleY = Ryujinx patch 0206 semantics):
    // the fragment position y and the y component of scaled fetches divide / multiply by it, so widening (render_scale[0] = k, wd_rscale) leaves y alone
    for (int i = 0; i < 73; i++) *(float *)((uint8_t *)b.contents + 1440 + 16 * i) = 1.0f;
    return b;
}
static uint64_t support_gpu(void) { static uint64_t gpu; if (!gpu) gpu = support_buf().gpuAddress; return gpu; }
// Raw global memory (binding kind NVN_RB_GMEM): a shader that loads or stores at an address it read from memory, which the translator could tie to no storage buffer
// (Ryujinx GlobalToStorage.TryGenerateRawStorageOp), looks the address up in this table and goes through a pointer to the pool's Metal GPU address (upstream reference implementation (MIT)).
// Until 11-06 the host had no table: the reflection took the translator's sentinel slot 0xff for uniform slot 252, which the replay cannot read, and bound the dummy buffer, so every
// such read gave 0 and every write was lost (Ocarina of Time: 2,206 shaders).
// Layout (GlobalToStorage GmemMap*): GMEM_ENTRIES entries of GMEM_ENTRY bytes {start, end (exclusive), delta (the pool's Metal GPU address minus the address the game holds), 64 bits
// each, then a 32-bit lookup hint and a 32-bit access state}, sorted by start, entry 0 empty, unused entries starting at ~0. The game holds GPU addresses of the window hle_nvn.c gives
// each pool (gva_alloc), so an entry covers a pool's window range (a pool that got no window: its CPU range, the address it was given instead). Ranges are disjoint (a range overlapping
// an earlier one keeps only its part past that one's end). Only pools something gave an address in are listed (nvn_be_pool_addressed).
// Rebuilt when the pools change (g_pool_gen) or the table's residency does (g_gmem_rgen, gmem_scan); the replaced table goes through deferred release, so submissions encoded with it keep
// it. g_gmem_cpu: each entry's CPU start, for the write log (sbw_note works on CPU addresses)
// On-demand residency (11-06; upstream reference implementation (MIT) made every listed pool resident). A shader may reach any listed pool, and the GPU must never touch memory outside
// the residency set, so the table itself is the gate: an entry is usable only while its pool is resident. A pool not resident gets a cold entry {start, start, its true end}, which the
// translator's lookup takes for no pool (a library translated before this skips it the same way: reads 0, its writes are dropped), and the access sets the pool's bit in the access
// bitmap (g_gbits, its address in entry 0's delta words; the bit + 1 in the entry's last word). Before the next submission's encoding uses the table, gmem_scan makes each such pool
// resident and commits the residency set, then the table is rebuilt with its entry usable: nothing the GPU runs reaches a pool before the residency commit that holds it. The first
// submission that reaches a pool reads 0 there and its writes there are lost, as a texture handle seen the first time reads the dummy texture (pool_seen_scan). A pool the table made
// resident keeps its bit in its usable entry (state != 0): a raw access that chooses the entry sets it, and one not reached for GAGE_BASE frames (doubled for each time it was taken out
// before, at most 2^GAGE_SHIFT_MAX times: one used every few seconds does not come and go) is taken out: its entry turns cold at once, the residency set lets it go only when the
// submission that may still have used the usable entry has completed (gfence). A pool a binding gave the GPU the address of (reg, pool_res) is not tracked here: pool_age ages it
enum { GMEM_ENTRIES = 8192, GMEM_ENTRY = 32, GMEM_HINT_SHIFT = 21, GMEM_INDEX_BITS = 13 };   // = GlobalToStorage GmemMapLog2 13, GmemMapEntryWords 8, GmemHintShift 21
enum { GAGE_BASE = 300, GAGE_SHIFT_MAX = 4, GAGE_CHECK = 60, GSTAT_EVERY = 300 };   // frames
typedef struct { uint64_t lo, hi, delta, cpu; int pool; } gmem_ent;
static int gmem_ent_cmp(const void *a, const void *b) { uint64_t x = ((const gmem_ent *)a)->lo, y = ((const gmem_ent *)b)->lo; return x < y ? -1 : x > y; }
enum { GMEM_RECYCLE = 16 };
typedef struct { id<MTLBuffer> buf; uint64_t fence; _Atomic int busy; } gmem_rec_slot;
static gmem_rec_slot g_gmem_rec[GMEM_RECYCLE];
static id<MTLBuffer> g_gmem_buf; static NSData *g_gmem_cpu; static uint64_t g_gmem_gen, g_gmem_built_rgen; static int g_gmem_cur_slot = -1, g_gmem_built_on = -1;
static int gmem_slot_of(id<MTLBuffer> buf) {
    if (!buf) return -1;
    for (int s = 0; s < GMEM_RECYCLE; s++) if (g_gmem_rec[s].buf == buf) return s;
    return -1;
}
// DM_NVN_GMEM=0 turns the table off: it is empty and nothing is made resident for it, those shaders read 0 and their writes are dropped. Otherwise on, the Mac and iOS alike. Until 11-06
// iOS had it off, as every listed pool was made resident, and on an iPhone that passed the GPU's wired limit (8 GB on a 17 Pro Max): Ocarina of Time's 3,560 ranges asked the kernel for up to
// 6.9 GB a command buffer, 1,181 command buffers refused in a 5-minute run (IOGPUCommandDescriptor::prepare remainingBytes < 0), with flashing, over-bright frames, a stalled pipeline
// prewarm and exits; on with every pool resident, 5,392 refused and 35.8 → 23.8 fps (11-06 test device 1). Now only pools a raw access reached are resident (gmem_scan)
static int g_gmem_on = -1;
static int gmem_decide(const char *e) { return !(e && *e == '0'); }   // DM_NVN_GMEM=0: off; anything else or unset: on
static int gmem_enabled(void) {
    if (g_gmem_on < 0) { const char *e = getenv("DM_NVN_GMEM");
        g_gmem_on = gmem_decide(e);
        MLOG("raw global memory: pool table %s (DM_NVN_GMEM %s)", g_gmem_on ? "on, pools resident once reached" : "off: those shaders read 0 and their writes are dropped", e && *e ? e : "unset"); }
