static void ubo_read(int stage, int reg, int off, size_t n, void *out) {
    memset(out, 0, n);
    if (g_handle_read_failed) return;
    if (stage < 0 || stage >= 6 || reg < 0 || reg >= 16) return;
    const p_bind_buf *u = &S.ubo[stage][reg];
