static id<MTLBuffer> g_quad_ib; static uint64_t g_quad_gpu;
static id<MTLBuffer> g_fan_ib; static uint64_t g_fan_gpu;   // non-indexed triangle fans: shared indices (0, i, i+1), base vertex = first
#define SHARED_IB_N 65536   // quads / fan triangles the shared index buffers cover
static void quad_ib_make(void) {   // Quads: shared indices 0,1,2,0,2,3
    if (g_quad_ib) return;
    uint32_t n = SHARED_IB_N; uint32_t *ix = malloc(n * 6 * 4);
    for (uint32_t q = 0; q < n; q++) { uint32_t b = q * 4; uint32_t v[6] = {b, b + 1, b + 2, b, b + 2, b + 3}; memcpy(ix + q * 6, v, 24); }
    g_quad_ib = [g_dev newBufferWithBytes:ix length:n * 24 options:MTLResourceStorageModeShared]; g_quad_gpu = g_quad_ib.gpuAddress; res_add(g_quad_ib); free(ix);
}
static void fan_ib_make(void) {
    if (g_fan_ib) return;
    uint32_t n = SHARED_IB_N; uint32_t *ix = malloc(n * 12);
    for (uint32_t i = 0; i < n; i++) { uint32_t v[3] = {0, i + 1, i + 2}; memcpy(ix + i * 3, v, 12); }
    g_fan_ib = [g_dev newBufferWithBytes:ix length:n * 12 options:MTLResourceStorageModeShared]; g_fan_gpu = g_fan_ib.gpuAddress; res_add(g_fan_ib); free(ix);
}
// Primitive restart (SetPrimitiveRestart): NVN restarts where an index equals the restart index taken at the index's width (as tf_draw compares); Metal restarts its strips at the
// all-ones index of their type, always, and its lists never (audit #846 F-nvn-restart-raw). The value to compare at width isz, or -1 when restart is off
static int64_t rst_val(int isz) { return S.restart.on ? (int64_t)(S.restart.index & (isz == 1 ? 0xFFu : isz == 2 ? 0xFFFFu : 0xFFFFFFFFu)) : -1; }
#define IXR(src, isz, i) ((isz) == 1 ? (uint32_t)(src)[i] : (isz) == 2 ? (uint32_t)((const uint16_t *)(src))[i] : ((const uint32_t *)(src))[i])
// Quads / triangle fans as a triangle list: the triangle count (0 for fewer vertices than one primitive; an upper bound once restart cuts the indices), and the expansion into d
// (3 per triangle, returns the triangles written). src NULL = the vertices themselves (non-indexed: first goes in as the base vertex); else isz-byte indices. Quads (q, q+1+h, q+2+h),
// fans (0, t+1, t+2); rv >= 0: each restart index starts a new fan / run of quads after it, and what is left of the old one short of a primitive is dropped
static uint32_t fanquad_tris(int prim, int32_t count) { return count <= 0 ? 0 : prim == 7 ? (uint32_t)count / 4 * 2 : count >= 3 ? (uint32_t)count - 2 : 0; }
static uint32_t fanquad_expand(int prim, const uint8_t *src, int isz, uint32_t count, int64_t rv, uint32_t *d) {
    #define IX(i) (!src ? (uint32_t)(i) : IXR(src, isz, i))
    uint32_t o = 0;
    for (uint32_t s = 0; s < count;) {
        uint32_t e = s; if (src && rv >= 0) while (e < count && IX(e) != (uint32_t)rv) e++; else e = count;
        uint32_t nt = fanquad_tris(prim, (int32_t)(e - s));
        for (uint32_t t = 0; t < nt; t++, o += 3) {
            if (prim == 6) { d[o] = IX(s); d[o + 1] = IX(s + t + 1); d[o + 2] = IX(s + t + 2); }
            else { uint32_t q = s + (t >> 1) * 4, h = t & 1; d[o] = IX(q); d[o + 1] = IX(q + 1 + h); d[o + 2] = IX(q + 2 + h); }
        }
        s = e + 1;
    }
    #undef IX
    return o / 3;
}
// 16 / 32-bit strip indices Metal would restart somewhere NVN does not, or not where NVN does: rewritten into 32-bit d (NVN's restart → 0xFFFFFFFF, a 16-bit 0xFFFF that is a vertex
// stays vertex 65535). Returns 0 when none differ (the indices go to Metal as they are). A 32-bit 0xFFFFFFFF that is not a restart is outside any vertex buffer: left as it is
static int strip_rst_fix(const uint8_t *src, int isz, uint32_t n, int64_t rv, uint32_t *d) {
    uint32_t mx = isz == 2 ? 0xFFFFu : 0xFFFFFFFFu; uint32_t i = 0;
    for (; i < n; i++) { uint32_t v = IXR(src, isz, i); if ((v == mx) != ((int64_t)v == rv) && !(isz == 4 && v == mx)) break; }
    if (i == n) return 0;
    if (d) for (i = 0; i < n; i++) { uint32_t v = IXR(src, isz, i); d[i] = (int64_t)v == rv ? 0xFFFFFFFFu : v; }
    return 1;
}
static id<MTL4RenderCommandEncoder> rp_begin(void);
// ---------- Pass lookahead: does this pass use depth / stencil ----------
// When opening a pass, scan forward from the op after the current draw, simulating the changes of depth-stencil state, up to where this pass must end (target reset, copy, compute dispatch -
// matching one-to-one the ops that end a pass in the replay). If no draw in between enables depth test / depth write / stencil test, this pass may leave the depth attachment unattached:
// not one byte of the depth content is touched, and on TBDR the load and store of the whole depth texture are saved (measured on a real device: a single-draw fullscreen pass takes half the GPU, with an extra D32S8 load and store attached).
// The scan follows real replay order across sub-list returns and across the remaining handles of this submission; end of submission = the pass must end. Undecidable cases such as a mid-pass clear or too-deep nesting always count as 'used'.
static const uint8_t *g_exec_next;   // The op following the current draw in the replay
static const uint8_t *g_exec_cur;    // The current draw's own op (set with g_exec_next)
static const uint8_t *g_ret[16]; static int g_ret_n;   // Call return stack of the replay (at OP_CALL the caller's next op is pushed)
static const uint64_t *g_rest; static int g_nrest;      // Handles in this submission still to be replayed after the current handle
void nvn_be_exec_rest(const uint64_t *h, int n) { g_rest = h; g_nrest = n; }
static uint64_t g_stat_ds_omit;      // Number of passes that attach less depth-stencil because the lookahead proved it unused (including stencil-only / depth-only)
static uint64_t g_stat_s_only, g_stat_d_only;   // Of those, the number of passes that attach only stencil / only depth
// Clear-only pass hoist (hoist_try): ops that were already executed early and must be skipped when replay reaches their original position (each group's SetRenderTargets and the clears in it).
// The exec loop, the store lookahead (sdx index) and the depth-stencil lookahead (ds_scan) all skip by it - otherwise the lookahead would take the clear at the original position as 'cleared again' and wrongly judge the early-cleared content redundant
#define HOIST_MAX 40   // At most 4 groups × (1 set-target op + 8 clears)
static const uint8_t *g_hoist_skip[HOIST_MAX]; static int g_hoist_n; static uint64_t g_hoist_groups;
static int hoist_skipped(const uint8_t *p) { for (int i = 0; i < g_hoist_n; i++) if (g_hoist_skip[i] == p) return 1; return 0; }
// A record header the recorder can have written (hle_nvn.c put_hdr: size counts the 8-byte header, a multiple of 8; OP_BEGIN is no longer recorded). Every cursor over the
//   command stream checks it before it uses the size: a size of 0 does not move the cursor, so a walk into memory that holds no records of ours used to spin in place
//   (Ring Fit Adventure, census 11-03, frame 454: the submit thread replayed {op 2, size 0} for 80 s, no crash and no red line)
// 上限是宿主录的最后一个操作码 OP_NVN2_END_（nvn2_cmd.h 的 OP_PUSH_CONST / OP_DLSS 接在 OP_COUNT_ 之后）：原判据 op ≥ OP_COUNT_ 把 NVN2 推常量当坏记录，
//   整条列表从那里截断（11-04 金刚：放大器的推常量 (1/宽, 1/高, 宽, 高) 之后的放大与合成全丢，画面只剩清屏紫色）
static inline int rec_bad(op_hdr h) { return h.size < 8 || (h.size & 7) || h.op >= OP_NVN2_END_ || h.op == OP_BEGIN; }
static const uint8_t *g_exec_top;   // The top-level handle being replayed (nvn_be_exec at return depth 0)
// One red line per bad header (the first 16 in a run): which cursor, where, the handle and list it was walking, the record before it; the cursor then ends that list
static void rec_bad_red(const char *who, const uint8_t *p, op_hdr h, const uint8_t *list, const uint8_t *prev) {
    static _Atomic unsigned n; if (atomic_fetch_add(&n, 1) >= 16) return;
    op_hdr ph = {0, 0}; if (prev) memcpy(&ph, prev, sizeof ph);
    char hx[3 * 32 + 1]; for (int k = 0; k < 32; k++) snprintf(hx + 3 * k, 4, "%02x ", p[k]);
    MLOG("【红】 command record at %p is not one of ours (%s): op %u size %u; handle %p, list %p + %#lx, previous record %p op %u size %u, call depth %d: that list ends here; bytes: %s",
         p, who, h.op, h.size, g_exec_top, list, list ? (unsigned long)(p - list) : 0ul, prev, ph.op, ph.size, g_ret_n, hx);
}
typedef struct { const uint8_t *p, *ret[sizeof g_ret / sizeof *g_ret]; int ret_n, rest_i, bad; } fz_cursor;   // ret: same capacity as the replay return stack it is copied from
// Lookahead starting from the op after the current draw, carrying the replay return stack so that sub-list boundaries are correctly crossed.
// Every lookahead that may run while inside a CALL sub-list must use this; a bare {.p = g_exec_next} with ret_n=0 would cross an OP_END by consuming g_rest instead of returning to the caller.
static inline fz_cursor fz_cursor_from_exec(void) {
    fz_cursor c = {.p = g_exec_next};
    // g_ret_n counts every CALL but g_ret keeps only the first entries: deeper than that the caller chain is lost, so the lookahead stops rather than guess (or copy past the array)
    if (g_ret_n < 0 || g_ret_n > (int)(sizeof c.ret / sizeof *c.ret)) { c.p = NULL; c.bad = 1; return c; }
    c.ret_n = g_ret_n; memcpy(c.ret, g_ret, sizeof(*g_ret) * (size_t)g_ret_n);
    return c;
}
static int fz_next(fz_cursor *c, const uint8_t **out, op_hdr *oh, const void **oa) {
    for (int guard = 0; guard < 1000000; guard++) {
        if (!c->p) return 0;
        op_hdr h; memcpy(&h, c->p, sizeof h); const void *a = c->p + 8;
        if (rec_bad(h)) { rec_bad_red("lookahead fz_next", c->p, h, NULL, NULL); c->p = NULL; c->bad = 1; return 0; }
        switch (h.op) {
            case OP_END:
                if (c->ret_n) c->p = c->ret[--c->ret_n];
                else if (c->rest_i < g_nrest) c->p = (const uint8_t *)g_rest[c->rest_i++];
                else { c->p = NULL; return 0; }
                continue;
            case OP_JUMP: memcpy(&c->p, a, 8); continue;
            case OP_MULTI_DRAW: c->bad = 1; return 0;   // its live draws and their argument addresses are resolved at replay (draw_multi): a lookahead cannot move work across the range (c7ba23df)
            case OP_CALL: { uint64_t t; memcpy(&t, a, 8); if (nvn_cmd_call_resolve(t, &t) < 0) break; if (c->ret_n >= (int)(sizeof c->ret / sizeof *c->ret)) { c->bad = 1; return 0; }
                c->ret[c->ret_n++] = c->p + h.size; c->p = (const uint8_t *)t; continue; }
            default: break;
        }
        const uint8_t *p = c->p; c->p += h.size;
        if (g_hoist_n && hoist_skipped(p)) continue;
        if (out) *out = p; if (oh) *oh = h; if (oa) *oa = a; return 1;
    }
    c->bad = 1; return 0;
}
// Variant of fz_next for pre-pass argument hoisting: crosses OP_MULTI_DRAW so indirect/multi-draw state inside the range is hoisted before rp_begin_ex.
static int fz_next_md(fz_cursor *c, const uint8_t **out, op_hdr *oh, const void **oa) {
    if (fz_next(c, out, oh, oa)) return 1;
    if (!c->bad || !c->p) return 0;
    op_hdr h; memcpy(&h, c->p, sizeof h);
    if (h.op != OP_MULTI_DRAW || rec_bad(h)) return 0;
    const uint8_t *p = c->p; c->p += h.size; c->bad = 0;
    if (out) *out = p; if (oh) *oh = h; if (oa) *oa = p + 8;
    return 1;
}
