static const p_draw *g_wdg_dw; static const p_draw_idx *g_wdg_di; static __unsafe_unretained NvProg *g_wdg_pr;
typedef struct { const p_draw *dw; const p_draw_idx *di; NvShader *vs; int n; uint32_t vid[64]; } wdg_ctx;
// Vertex attribute formats the geometry check decodes (what the shader sees after the fetch: normalized -> float, integer -> integer bits); packed / RG11B10 are refused
static int wdg_fmt(MTLVertexFormat f, int *kind, int *comps, int *csz) {   // kind: 0 f32, 1 f16, 2 unorm, 3 snorm, 4 uint, 5 sint
    switch (f) {
#define WF(F, K, N, Z) case F: *kind = K; *comps = N; *csz = Z; return 1;
        WF(MTLVertexFormatFloat, 0, 1, 4) WF(MTLVertexFormatFloat2, 0, 2, 4) WF(MTLVertexFormatFloat3, 0, 3, 4) WF(MTLVertexFormatFloat4, 0, 4, 4)
        WF(MTLVertexFormatHalf, 1, 1, 2) WF(MTLVertexFormatHalf2, 1, 2, 2) WF(MTLVertexFormatHalf3, 1, 3, 2) WF(MTLVertexFormatHalf4, 1, 4, 2)
        WF(MTLVertexFormatUCharNormalized, 2, 1, 1) WF(MTLVertexFormatUChar2Normalized, 2, 2, 1) WF(MTLVertexFormatUChar3Normalized, 2, 3, 1) WF(MTLVertexFormatUChar4Normalized, 2, 4, 1)
        WF(MTLVertexFormatCharNormalized, 3, 1, 1) WF(MTLVertexFormatChar2Normalized, 3, 2, 1) WF(MTLVertexFormatChar3Normalized, 3, 3, 1) WF(MTLVertexFormatChar4Normalized, 3, 4, 1)
        WF(MTLVertexFormatUShortNormalized, 2, 1, 2) WF(MTLVertexFormatUShort2Normalized, 2, 2, 2) WF(MTLVertexFormatUShort3Normalized, 2, 3, 2) WF(MTLVertexFormatUShort4Normalized, 2, 4, 2)
        WF(MTLVertexFormatShortNormalized, 3, 1, 2) WF(MTLVertexFormatShort2Normalized, 3, 2, 2) WF(MTLVertexFormatShort3Normalized, 3, 3, 2) WF(MTLVertexFormatShort4Normalized, 3, 4, 2)
        WF(MTLVertexFormatUChar, 4, 1, 1) WF(MTLVertexFormatUChar2, 4, 2, 1) WF(MTLVertexFormatUChar3, 4, 3, 1) WF(MTLVertexFormatUChar4, 4, 4, 1)
        WF(MTLVertexFormatChar, 5, 1, 1) WF(MTLVertexFormatChar2, 5, 2, 1) WF(MTLVertexFormatChar3, 5, 3, 1) WF(MTLVertexFormatChar4, 5, 4, 1)
        WF(MTLVertexFormatUShort, 4, 1, 2) WF(MTLVertexFormatUShort2, 4, 2, 2) WF(MTLVertexFormatUShort3, 4, 3, 2) WF(MTLVertexFormatUShort4, 4, 4, 2)
        WF(MTLVertexFormatShort, 5, 1, 2) WF(MTLVertexFormatShort2, 5, 2, 2) WF(MTLVertexFormatShort3, 5, 3, 2) WF(MTLVertexFormatShort4, 5, 4, 2)
        WF(MTLVertexFormatUInt, 4, 1, 4) WF(MTLVertexFormatUInt2, 4, 2, 4) WF(MTLVertexFormatUInt3, 4, 3, 4) WF(MTLVertexFormatUInt4, 4, 4, 4)
