        MLOG("color attachments proven unwritten to the pass end not loaded: %s (DM_NVN_NOLOAD%s)", g_noload_on ? "on" : "off, every attachment loaded", g_noload_on ? "=0 turns it off" : "=0"); }
    return g_noload_on;
