                        if (mc) { stop = 1; break; } }
                    int itype_ok = hq.op != OP_DRAW_IDX || (((const p_draw_idx *)aq)->itype >= 0 && ((const p_draw_idx *)aq)->itype <= 2);
                    if (gv && gv->geo_fn && !pr->sh[3] && !pr->sh[4] && itype_ok) { proven = 1; stop = 1; }
