    pool[slot][lru].t = t; pool[slot][lru].used = ++tick; pool[slot][lru].used_draw = g_draw_seq; pool[slot][lru].bytes = (uint64_t)t.allocatedSize;
    g_fbsnap_bytes += pool[slot][lru].bytes;
