    return t;
}
// ⑤ 遍内自采样改片上读取（10-30 帧率能耗线；DM_NVN_FB_TILE=0 关）：第 ③ 步结束遍之前先试——这一笔采样本遍已改过的附件 k，且只在本像素读它：
//   就用片元着色器的可读瓦片版（_bf，FX_i = k）直接读瓦片里的颜色，遍不结束。瓦片里正是「这一笔之前」的内容（同 Switch：先前的笔已写进，本笔的写还没落），
//   和第 ③ 步结束遍后重新载入读到的一样，却省了整片写回 + 读入（塞尔达每帧 250 处切遍、附件读写约 10 GB）。
//   证明不成立（槽混用、坐标不是投影本像素、视图不是附件本身、没有 _bf、特化失败……）回到 ③（本笔不写采样槽）或 ④（自写槽快照）。
//   已知差别：同一笔里重叠的片元，后者读到前者刚写的值（Switch 两者都读本笔之前）；DM_NVN_FB_TILE_CHECK 双画比对量它
static uint64_t g_fb_l5, g_fb_l5_unpush, g_fb_l5ld;   // ⑤ 的次数；其中外推参数非零、这一笔不外推的次数（fb_report）
// DM_NVN_FB_TILE_CHECK=1（诊断，同局双画逐字节比对；每帧最多 DM_NVN_FB_TILE_CHECK 次，=1 时每帧 8 次）：命中 ⑤ 的笔先按常规路径（③ / ④）画、
//   结果拷出；附件恢复成这一笔之前的底，再按 ⑤（读瓦片）画同一笔；两份逐字节比。同一帧、同一笔、同一组输入，不依赖两局能否复现。只比单命中的笔
static struct { int pending, forcing, fx[32], n; uint8_t fbmask, lmap[8]; __strong id<MTLFunction> fn; __strong id<MTLTexture> att[8], s0[8]; __strong NSMutableArray *keep; uint64_t ser[8], frame, quota; } g_fbc;
static _Atomic uint64_t g_fbc_same, g_fbc_diff;
static long fbc_limit(void) { static long v = -2; if (v == -2) { const char *e = getenv("DM_NVN_FB_TILE_CHECK"); v = e && atol(e) > 0 ? (atol(e) == 1 ? 8 : atol(e)) : 0; if (v) MLOG("same-pass feedback sampling: on-chip read double render on (DM_NVN_FB_TILE_CHECK, up to %ld draws a frame)", v); } return v; }
static id<MTLTexture> fbc_copy(id<MTLTexture> t) {   // 同形私有纹理，拷 0 级 0 层；进驻留集并持有到提交回调（dbl_keep，draw_top 末尾 dbl_retire）
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:t.pixelFormat width:t.width height:t.height mipmapped:NO];
    d.usage = MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate; id<MTLTexture> c = [g_dev newTextureWithDescriptor:d]; if (!c) return nil;
    if (!g_fbc.keep) g_fbc.keep = [NSMutableArray array];
    dbl_keep(g_fbc.keep, c);
    enc_b_copy_texture(blit(), t, 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(t.width, t.height, 1), c, 0, 0, MTLOriginMake(0, 0, 0)); return c;
}
static struct { int on; int fx[32]; uint8_t fbmask, lmap[8]; id<MTLFunction> fn; } g_fbt;   // 本笔的片上读取方案（fb_prepare 定，draw 取管线时用，下一笔清）
static int fb_tile_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_FB_TILE"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("same-pass feedback sampling: on-chip read off (DM_NVN_FB_TILE=0)"); } return v; }
// 颜色格式的分量数（只认能当附件的常见单 / 双 / 三分量格式；其余按 4，即「缺的分量」为空、只认恒等）
static int pf_ncomp(MTLPixelFormat f) {
    switch ((int)f) {
        case MTLPixelFormatR8Unorm: case MTLPixelFormatR8Unorm_sRGB: case MTLPixelFormatR8Snorm: case MTLPixelFormatR8Uint: case MTLPixelFormatR8Sint:
        case MTLPixelFormatR16Unorm: case MTLPixelFormatR16Snorm: case MTLPixelFormatR16Uint: case MTLPixelFormatR16Sint: case MTLPixelFormatR16Float:
        case MTLPixelFormatR32Uint: case MTLPixelFormatR32Sint: case MTLPixelFormatR32Float: return 1;
        case MTLPixelFormatRG8Unorm: case MTLPixelFormatRG8Unorm_sRGB: case MTLPixelFormatRG8Snorm: case MTLPixelFormatRG8Uint: case MTLPixelFormatRG8Sint:
        case MTLPixelFormatRG16Unorm: case MTLPixelFormatRG16Snorm: case MTLPixelFormatRG16Uint: case MTLPixelFormatRG16Sint: case MTLPixelFormatRG16Float:
        case MTLPixelFormatRG32Uint: case MTLPixelFormatRG32Sint: case MTLPixelFormatRG32Float: return 2;
        case MTLPixelFormatRG11B10Float: case MTLPixelFormatB5G6R5Unorm: return 3;
        default: return 4;
    }
}
// 视图通道顺序按读数等于恒等：格式有的分量必须原样，缺的分量取贴图读的缺省（G / B 为 0、A 为 1）。帧缓冲读取（[[color(n)]] 按 float4 读）缺的分量
//   苹果 GPU 给的正是 0 / 0 / 1（11-02 实测 R32Float / RG32Float / RG11B10Float / R16Float / R8Unorm），所以这样的视图读瓦片与采样逐分量相同。
//   11-02 塞尔达：灯光 / 贴花 7636e1d2542c221a_b、eadbb36f187df11e_b 采样 R32Float 附件 7 的视图通道顺序是 (R, 0, 0, 1)，原先只认严格恒等 → 每帧 80 次结束遍（附件像素 82.6%）
static int swz_ident_for(MTLPixelFormat f, MTLTextureSwizzleChannels s) {
    int n = pf_ncomp(f); const MTLTextureSwizzle c[4] = {s.red, s.green, s.blue, s.alpha}, id[4] = {MTLTextureSwizzleRed, MTLTextureSwizzleGreen, MTLTextureSwizzleBlue, MTLTextureSwizzleAlpha};
    for (int i = 0; i < 4; i++) if (c[i] != id[i] && !(i >= n && c[i] == (i == 3 ? MTLTextureSwizzleOne : MTLTextureSwizzleZero))) return 0;
    return 1;
}
// ⑤ 走不成的原因计数（300 帧统计行里列出前几名；#1152 异度之刃 iPhone：每帧 2000–3600 次 ④ 快照、⑤ 0 次，诊断里看不出被哪条前提挡住）
enum { FBR_STATE, FBR_NO_VS, FBR_NO_FO, FBR_MIXED, FBR_NOT_PROJ, FBR_SCR_PROOF, FBR_NO_FC, FBR_SUB, FBR_PRE_SIZE, FBR_CANVAS, FBR_VIEW, FBR_SWIZZLE, FBR_NO_FN, FBR_N };
static const char *const g_fbr_name[FBR_N] = {"pass state", "no vertex shader", "no fragment outputs", "texture also read another way", "not sampled at its own pixel",
    "same pixel not proven", "slot not a tile read", "attachment level / layer not 0", "pass sizes differ (pass not open)", "canvas differs from the pass", "view format differs", "view swizzle", "no tile-read variant"};
static uint64_t g_fbr[FBR_N];
enum { FB4_LISTED, FB4_PRE_BLOCKED, FB4_PRE_REFUSED, FB4_DIRTY_REFUSED, FB4_LOADED_REFUSED, FB4_NOT_LOADED, FB4_N };
static const char *const g_fb4_name[FB4_N] = {"forced by DM_NVN_FB list", "pass not open, deferred replay / merge", "pass not open, refused", "drawn in this pass, refused", "loaded, refused", "pass open, slot not loaded (cleared / don't-care)"};
static uint64_t g_fb4[FB4_N];
static inline int fbr(int r) { g_fbr[r]++; return 0; }
static int fb_tile_try(NvProg *pr, NvShader *fs, int k, int reg, id<MTLTexture> tv, int pre) {   // pre：遍还没开（开遍前定，调用方让这一槽开遍时载入）
    NvShader *vs = pr->sh[0];
    if (!fb_tile_on() || (pre ? g_enc != nil : !g_enc) || k < 0 || k >= 8) return fbr(FBR_STATE);
    if (!vs) return fbr(FBR_NO_VS);
    if (!fs->rf.nfo) return fbr(FBR_NO_FO);
    if (fs->rf.fc_mixed[reg >> 6] >> (reg & 63) & 1) return fbr(FBR_MIXED);   // 同一张纹理还有别的读法（如读邻像素）：只能结束遍
    int fx[32]; memcpy(fx, g_fbt.on ? g_fbt.fx : (int[32]){[0 ... 31] = -1}, sizeof fx); int any = 0;
    for (int c = 0; c < fs->rf.nfc; c++) if (fs->rf.fc_reg[c] == reg) {
        if (!(fs->rf.fc_proj >> c & 1)) return fbr(FBR_NOT_PROJ);
        if (!scr_proof(pr, vs, fs->rf.fc_locn[c], fs->rf.fc_ndc >> c & 1, 1, R.rt.color[k])) return fbr(FBR_SCR_PROOF);
        fx[c] = k; any = 1; }
    if (!any) return fbr(FBR_NO_FC);
    uint64_t s_; int lv, sl; rt_sub(&R.rt, k, &s_, &lv, &sl);
    if (lv || sl || !R.rt.color[k]) return fbr(FBR_SUB);
    if (pre) {   // 遍的画布还没定：要求本遍每个附件游戏尺寸都与它相同（画布 = 它），且不放宽（放宽会改画布）
        uint32_t w0 = MAX(R.rt.color[k]->d.width, 1u), h0 = MAX(R.rt.color[k]->d.height, 1u);
        if (g_wd > 0) return fbr(FBR_PRE_SIZE);
        for (int i = 0; i < R.rt.n && i < 8; i++) if (R.rt.color[i] && (MAX(R.rt.color[i]->d.width, 1u) != w0 || MAX(R.rt.color[i]->d.height, 1u) != h0)) return fbr(FBR_PRE_SIZE);
        if (R.rt.depth && (MAX(R.rt.depth->d.width, 1u) != w0 || MAX(R.rt.depth->d.height, 1u) != h0)) return fbr(FBR_PRE_SIZE);
    } else {   // 遍已开：附件 k 的画布（canvas 单位：内部分辨率按游戏尺寸、满屏按加宽后的存储，tex_extent_at）要正好是这一遍的画布，同像素由 scr_proof 证。
        //   原先比游戏尺寸 d.width / d.height：满屏加宽了存储、画布跟着变宽 / 变高，永远不等，⑤ 一律被拒（11-12 Duo 一款开放世界游戏：13.3 万次自采样全走快照、累计拷 372 GB、每帧 412 遍）
        id<MTLTexture> at = tex_mtl(R.rt.color[k]); if (!at) return fbr(FBR_CANVAS);
        tex_extent ex = tex_extent_at(R.rt.color[k], at, 0, 0);
        if (MAX(ex.canvas.width, 1u) != g_pass.cw || MAX(ex.canvas.height, 1u) != g_pass.ch) return fbr(FBR_CANVAS); }
    {   // 采样的视图必须就是附件本身（同 fz_p2_draw：起始级 / 层 0、单级、格式同附件实际格式、通道顺序恒等、单采样）
        uint32_t apf_ = tv.parentTexture ? (uint32_t)tv.parentTexture.pixelFormat : (uint32_t)tv.pixelFormat; uint8_t swz_[4];
        if (R.rt.has_cview[k] && R.rt.cview[k].set_format && !(nvn_fmt_to_mtl(R.rt.cview[k].format, &apf_, swz_) && apf_)) return fbr(FBR_VIEW);
        MTLTextureSwizzleChannels tsw = tv.swizzle;
        if (!swz_ident_for(tv.pixelFormat, tsw)) return fbr(FBR_SWIZZLE);   // 恒等，或只在格式缺的分量上补 0 / 0 / 1（见 swz_ident_for）
        if ((tv.parentTexture && (tv.parentRelativeLevel || tv.parentRelativeSlice)) || tv.pixelFormat != (MTLPixelFormat)apf_ || tv.mipmapLevelCount != 1 || tv.sampleCount != 1) return fbr(FBR_VIEW); }
    uint8_t fbmask = (uint8_t)((g_fbt.on ? g_fbt.fbmask : 0) | (1u << k)), lmap[8]; memset(lmap, 0xff, 8);
    for (int c = 0; c < 8; c++) if (fs->rf.color_mask >> c & 1) lmap[c] = (uint8_t)c;   // 输出不搬位置：第 c 个颜色写附件 c
    id<MTLFunction> fn = bf_fn(fs, fx, fbmask, lmap);
    if (!fn) return fbr(FBR_NO_FN);
    if (pre && fbc_limit()) return 0;   // 双画检查要开着的遍：遍未开的这一笔照 ④
    if (fbc_limit() && !g_fbc.forcing) {   // 双画检查：这一笔先按老路（③）画，⑤ 留到 draw_top 里第二遍
        uint64_t fr = atomic_load(&g_cur_frame); if (fr != g_fbc.frame) { g_fbc.frame = fr; g_fbc.quota = 0; }
        if (g_fbc.pending || g_fbt.on || g_fbc.quota >= (uint64_t)fbc_limit()) { g_fbc.pending = 0; return 0; }   // 多命中 / 超额：不比，照老路
        rp_end(); g_fbc.n = 0;
