            g_fbc.att[g_fbc.n] = at; g_fbc.ser[g_fbc.n] = R.rt.color[c]->serial; g_fbc.s0[g_fbc.n] = fbc_copy(at); if (!g_fbc.s0[g_fbc.n]) { g_fbc.n = 0; return 0; } g_fbc.n++; }
        g_fbc.pending = 1; g_fbc.quota++; memcpy(g_fbc.fx, fx, sizeof fx); g_fbc.fbmask = fbmask; memcpy(g_fbc.lmap, lmap, 8); g_fbc.fn = fn;
        return 0; }   // 调用方照 ③ 走（遍已结束）
    g_fbt.on = 1; memcpy(g_fbt.fx, fx, sizeof fx); g_fbt.fbmask = fbmask; memcpy(g_fbt.lmap, lmap, 8); g_fbt.fn = fn;
    if (++g_fb_l5 == 1) MLOG("same-pass feedback sampling: first on-chip read (frame %llu, shader %s slot %d reads attachment %d from the tile; the pass stays open)", (unsigned long long)atomic_load(&g_cur_frame), fs->key, reg, k);
    return 1;
}
// 双画检查（见 g_fbc）：老路画完的这一笔结果拷出，附件恢复成底，再按 ⑤ 画同一笔，两份逐字节比（GPU 做完后在提交回调里比）
static void draw_top(const p_draw *dw, const p_draw_idx *di) {
    draw(dw, di);
    if (!g_fbc.pending) return;
    g_fbc.pending = 0; rp_end();
    id<MTLTexture> r3[8]; int n = g_fbc.n;
    for (int a = 0; a < n; a++) { r3[a] = fbc_copy(g_fbc.att[a]); if (!r3[a]) return; }
    for (int a = 0; a < n; a++) enc_b_copy_texture(blit(), g_fbc.s0[a], 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(g_fbc.s0[a].width, g_fbc.s0[a].height, 1), g_fbc.att[a], 0, 0, MTLOriginMake(0, 0, 0));
    g_fbc.forcing = 1; draw(dw, di); g_fbc.forcing = 0; rp_end();
    for (int a = 0; a < n; a++) {
        id<MTLTexture> t = g_fbc.att[a], c = r3[a]; NSUInteger W = t.width, H = t.height, bpp = (NSUInteger)(att_bytes(t, 0) / (W * H)); if (!bpp) continue;
        id<MTLBuffer> b1 = [g_dev newBufferWithLength:W * H * bpp options:MTLResourceStorageModeShared], b2 = [g_dev newBufferWithLength:W * H * bpp options:MTLResourceStorageModeShared];
        if (!b1 || !b2) continue;
        dbl_keep(g_fbc.keep, b1); dbl_keep(g_fbc.keep, b2);
        enc_b_copy_texture_buffer(blit(), c, 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(W, H, 1), b1, 0, W * bpp, W * H * bpp);   // 经后端 blit()，不直写 MTL4 类型（mtl4_baseline）
        enc_b_copy_texture_buffer(blit(), t, 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(W, H, 1), b2, 0, W * bpp, W * H * bpp);
        unsigned long long ser = g_fbc.ser[a], pass = g_stat_pass, frame = atomic_load(&g_cur_frame); NSUInteger nb = W * H * bpp;
        [g_commit_blocks addObject:^{
            const uint8_t *x = b1.contents, *y = b2.contents; uint64_t dpx = 0, maxd = 0;
            for (NSUInteger k = 0; k < nb; k += bpp) if (memcmp(x + k, y + k, bpp)) { dpx++; for (NSUInteger q = 0; q < bpp; q++) { uint64_t dd = (uint64_t)abs((int)x[k + q] - (int)y[k + q]); if (dd > maxd) maxd = dd; } }
            if (dpx) { atomic_fetch_add(&g_fbc_diff, 1); MLOG("【红】 on-chip read double render: frame %llu pass %llu attachment ser=%llu on-chip vs pass-ended: differing pixels %llu / %lu (max per-byte difference %llu)", frame, pass, ser, (unsigned long long)dpx, (unsigned long)(nb / bpp), (unsigned long long)maxd); }
            else atomic_fetch_add(&g_fbc_same, 1);
            uint64_t tot = atomic_load(&g_fbc_same) + atomic_load(&g_fbc_diff);
            if (tot % 100 == 0) MLOG("on-chip read double render totals: identical %llu, different %llu", (unsigned long long)atomic_load(&g_fbc_same), (unsigned long long)atomic_load(&g_fbc_diff));
        }];
    }
    dbl_retire(g_fbc.keep);   // s0 / r3 / b1 / b2 持有到这次提交的 GPU 做完（排在上面各比对块之后）
    for (int a = 0; a < n; a++) { g_fbc.att[a] = nil; g_fbc.s0[a] = nil; } g_fbc.fn = nil;
}
// After a draw: the color slots it wrote now differ from memory until the pass ends (fb_prepare copies a hit on such a slot); the same write test as udc_note_draw
static void fb_note_draw(NvProg *pr) {
    uint32_t cm = pr && pr->sh[1] ? pr->sh[1]->rf.color_mask : 0;
    if (R.has_rt) for (int i = 0; i < R.rt.n && i < 8; i++) if ((cm >> i & 1) && ((S.chmask.mask >> (4 * i)) & 0xf)) g_fb_dirty[i] = 1;
}
static void fb_report(uint64_t frame) {   // every 300 frames: hits per layer and what the copies cost
    static uint64_t h0, a0, b0, c0, d0, y0;
    if (g_fb_hits == h0) return;
    static uint64_t e0, f0;
    MLOG("same-pass feedback sampling up to frame %llu: %llu draws sampled their own pass's attachment: ① narrowed view %llu, ② read memory as it was %llu, ③ pass ended first %llu, ④ snapshot %llu (%.1f MB copied), ⑤ read on-chip, pass kept %llu (of them before the pass drew the slot, read as loaded %llu; widen push dropped on %llu; widened canvas, game-size viewport %llu)",
         (unsigned long long)frame, (unsigned long long)(g_fb_hits - h0), (unsigned long long)(g_fb_l1 - a0), (unsigned long long)(g_fb_l2 - b0), (unsigned long long)(g_fb_l3 - c0),
         (unsigned long long)(g_fb_count - d0), (g_fb_bytes - y0) / 1048576.0, (unsigned long long)(g_fb_l5 - e0), (unsigned long long)(g_fb_l5ld - f0), (unsigned long long)g_fb_l5_unpush, (unsigned long long)g_fb_l5wd);
    h0 = g_fb_hits; a0 = g_fb_l1; b0 = g_fb_l2; c0 = g_fb_l3; d0 = g_fb_count; y0 = g_fb_bytes; e0 = g_fb_l5; f0 = g_fb_l5ld;
    {   // ⑤ 被拒的原因（这 300 帧），按次数排前 4
        static uint64_t r0[FBR_N]; uint64_t d[FBR_N], tot = 0; for (int i = 0; i < FBR_N; i++) { d[i] = g_fbr[i] - r0[i]; r0[i] = g_fbr[i]; tot += d[i]; }
        if (tot) { char line[512]; int at = 0;
            for (int n = 0; n < 4; n++) { int m = -1; for (int i = 0; i < FBR_N; i++) if (d[i] && (m < 0 || d[i] > d[m])) m = i; if (m < 0) break;
                at += snprintf(line + at, sizeof line - (size_t)at, "%s%s %llu", n ? ", " : "", g_fbr_name[m], (unsigned long long)d[m]); d[m] = 0; if (at >= (int)sizeof line) break; }
            MLOG("same-pass feedback sampling up to frame %llu: on-chip read refused %llu times: %s", (unsigned long long)frame, (unsigned long long)tot, line); } }
    {   static uint64_t q0[FB4_N]; char line[512]; int at = 0; uint64_t tot = 0;
        for (int i = 0; i < FB4_N; i++) { uint64_t d = g_fb4[i] - q0[i]; q0[i] = g_fb4[i]; tot += d; if (d) at += snprintf(line + at, sizeof line - (size_t)at, "%s%s %llu", at ? ", " : "", g_fb4_name[i], (unsigned long long)d); if (at >= (int)sizeof line) break; }
        if (tot) MLOG("same-pass feedback sampling up to frame %llu: ④ snapshots by case: %s", (unsigned long long)frame, line); }
    {   static uint64_t ev0; MLOG("same-pass feedback sampling up to frame %llu: snapshot pool keeps %.1f MB (cap %u MB), %llu released at the cap since the last report",
                                  (unsigned long long)frame, g_fbsnap_bytes / 1048576.0, FB_SNAP_CAP >> 20, (unsigned long long)(g_fbsnap_cap_evict - ev0)); ev0 = g_fbsnap_cap_evict; }
}
// Called before the draw opens its render pass: if a snapshot is needed, end the current render pass, copy the snapshot and register the substitution (used by this draw's argument encoding)
// #387 the depth snapshot of the pass's own depth attachment, kept while that depth stays unchanged: draws after the first that sample it read the same copy (one copy and
//   one pass break for a run of halo draws instead of one per draw). It goes stale when the depth or stencil may change: a draw writing depth or stencil to it, a depth / stencil
//   clear, a render-target change, a copy or buffer clear (storage may alias) and a new submission. Own storage (dsnap_storage), not fb_snap_shape's slots that other copies reuse in place
static struct { uint64_t ser; const void *mem; uint64_t size; __unsafe_unretained id<MTLTexture> src, base; __strong id<MTLTexture> use; int valid, stencil; } g_dsnap;   // stencil: the copy is read through a stencil view
static void dsnap_stale(void) { g_dsnap.valid = 0; }
static int dsnap_hits_tex(const tex_t *t) {
    if (!g_dsnap.valid) return 0;
    if (!t) return 1;
    if (t->serial == g_dsnap.ser) return 1;
