        if (!mtl_gpu_addr(e->ind, e->prim == DM_PRIM_MESH_TASKS ? 8 : e->itype < 0 ? 16 : 20, &mb, &mo, &rec)) continue;
        if (e->prim == DM_PRIM_MESH_TASKS) {   // NVN2 DrawMeshTasksIndirect: {count, first} → the indirect mesh arguments and the first workgroup after them (ixc_arrays); no index buffer
            if (rec & 3) continue;
