        rec_commit(g_cb, nil);
        rec_signal(g_mdi_ev, ++g_mdi_v); rec_drain();
    }
    if (![g_mdi_ev waitUntilSignaledValue:g_mdi_v timeoutMS:10000]) RED_ONCE(97, "indirect-count multi-draw: the GPU did not finish within 10 s; the count is read anyway");
    main_barrier_reset();
    if (g_m3) g_cb = rec_cb_new();
    else {
        g_cb = rec_cb_new();
        [g_cb beginCommandBufferWithAllocator:g_alloc4[g_alloc_cur]];
    }
    if (!g_mdi_waits++) MLOG("indirect-count multi-draw: first wait for the GPU-written count at frame %llu pass %llu", (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass);
}
static uint32_t mdi_count(uint64_t cnt) {
    if (cnt != g_mdi_addr || g_mdi_epoch != g_wr_epoch || g_mdi_sub != g_sub_serial) {
        if (g_mdi_epoch != g_wr_epoch || g_mdi_sub != g_sub_serial) { mdi_wait(); g_mdi_epoch = g_wr_epoch; g_mdi_sub = g_sub_serial; }
        uint32_t v = 0;
        const uint8_t *hc = nvn_host_ptr(cnt, 4); if (hc) memcpy(&v, hc, 4);
        else RED_ONCE(98, "indirect-count multi-draw: the count at %#llx is in an unmapped page of a sparse pool, nothing drawn", (unsigned long long)cnt);
        g_mdi_addr = cnt; g_mdi_count = v;
    }
    return g_mdi_count;
}
static int mdi_live(uint64_t cnt, int i) { return (uint32_t)i < mdi_count(cnt); }
// ---------- Indirect-count multi-draws masked on the GPU ----------
// The wait above held the submitting thread for the GPU at every GPU-driven pass: in Monster Hunter Rise's Kamura Village, 14 of the 20 ms a submission took on an iPhone were that wait
// (6 ms of work), and the game ran at 36–54 fps. Instead a compute pass copies each such draw's record into the frame arena, or zeros for a draw past the count, and the draw reads the copy:
// past the count it draws nothing, and the CPU never waits. As in ixc_run, a compute pass cannot run inside a render pass: at the first such draw with no copy yet, mdx_run copies it and every
// such draw after it in replay order up to the next write that could change a record or count (a dispatch, copy, fill or texture → buffer copy, which bump g_mdx_epoch; a uniform update only
// when it covers one: g_mdx_stop), so only a draw met inside an open render pass splits it. Copies are found by record and count address in an open-addressing table, valid for one g_mdx_tag
// (Kamura Village draws the same records with two counts between the same writes: keyed by the record alone, the second multi-draw found no copy and waited for the GPU each frame)
#define MDX_SLOTS 16384   // a power of two; a scan fills at most a quarter
typedef struct { uint64_t ind, cnt, out, tag; } mdx_ent;   // out: GPU address of the copy, 0 when the record or count is in no Metal buffer (those draws wait, mdi_live)
static const p_multi_draw *g_mdx_range;   // only while draw_multi replays a range through the GPU mask: mdx_run takes the range's later draws instead of looking ahead
static mdx_ent g_mdx[MDX_SLOTS]; static int g_mdx_n; static uint64_t g_mdx_tag = 1, g_mdx_ep = ~0ull, g_mdx_sub, g_mdx_runs, g_mdx_splits, g_mdx_draws, g_mdx_fast; static const uint8_t *g_mdx_stop;
static const char k_mdx_msl[] =
"#include <metal_stdlib>\nusing namespace metal;\n"
"struct mjob { device const uint *rec; device const uint *cnt; device uint *out; uint i, words; };\n"   // draw i's record (words long), its multi-draw's count, the copy (null: padding)
"kernel void mdx_mask(device const mjob *j [[buffer(0)]], uint t [[thread_position_in_grid]]) {\n"
"  mjob m = j[t]; if (!m.out) return; bool live = m.i < *m.cnt;\n"
"  for (uint k = 0; k < m.words; k++) m.out[k] = live ? m.rec[k] : 0u; }\n";
static int mdx_wanted(const p_draw *dw, const p_draw_idx *di) { return dw ? dw->mdi_cnt && !ixc_wanted(dw, NULL) : di->mdi_cnt && !ixc_wanted(NULL, di); }
static const uint8_t *g_mdx_pre_recs[64];
static int g_mdx_pre_n, g_mdx_pre_rem;
static uint64_t g_mdx_pre_ep = ~0ull, g_mdx_pre_sub;
static int g_mdx_pre_active;
static mdx_ent *mdx_slot(uint64_t ind, uint64_t cnt) {   // its entry in this tag, or the free slot for it
    for (uint64_t h = ((ind ^ cnt * 0xD6E8FEB86659FD93ull) * 0x9E3779B97F4A7C15ull) >> 50;; h = (h + 1) & (MDX_SLOTS - 1)) { mdx_ent *e = &g_mdx[h]; if (e->tag != g_mdx_tag || (e->ind == ind && e->cnt == cnt)) return e; }
}
static int mdx_find(uint64_t ind, uint64_t cnt, uint64_t *out) {   // → 1 when mdx_run has taken this draw (*out: its copy, or 0)
    if (g_mdx_ep != g_mdx_epoch || g_mdx_sub != g_arena_gen) return 0;
    const mdx_ent *e = mdx_slot(ind, cnt); if (e->tag != g_mdx_tag) return 0;
    *out = e->out; return 1;
}
typedef struct { mdx_ent *e; uint32_t i, words; } mdx_qent;
static int mdx_pipe(id<MTLComputePipelineState> *pso, id *ato) {
    static id<MTLComputePipelineState> ps; static id at; static int failed;
    if (failed) return 0;
    if (!at) { NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(k_mdx_msl) options:nil error:&e]; id<MTLFunction> f = [lib newFunctionWithName:@"mdx_mask"];
        ps = f ? [g_dev newComputePipelineStateWithFunction:f error:&e] : nil;
        at = ps ? rec_table(tab_new(1, 0, 0, &e)) : nil;
        if (!at) { failed = 1; MLOG("【红】 indirect-count multi-draw masking: cannot create the compute pipeline %s (those draws wait for the GPU)", e.localizedDescription.UTF8String); return 0; } }
    *pso = ps; *ato = at; return 1;
}
static void mdx_emit_q(mdx_qent *q, int nq, int prepass) {
    if (!nq) return;
    id<MTLComputePipelineState> ps; id at;
    if (!mdx_pipe(&ps, &at)) return;
    if (g_enc) { g_mdx_splits++; PD("M %llu indirect-count multi-draw masking: render pass split here", g_stat_pass); rp_end(); }
    if (prepass && g_nubd) ubd_land_compute();
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    typedef struct { uint64_t rec, cnt, out; uint32_t i, words; } mjob;
    int nj = (nq + 63) & ~63;
    id<MTLBuffer> ab; size_t ao = arena_alloc((size_t)nj * sizeof(mjob) + (size_t)nq * 32, &ab);   // the jobs (padded to whole threadgroups), then the copies 32 bytes apart
    mjob *j = (mjob *)((uint8_t *)ab.contents + ao); uint64_t og = ab.gpuAddress + ao + (uint64_t)nj * sizeof(mjob);
    memset(j, 0, (size_t)nj * sizeof(mjob));
    for (int k = 0; k < nq; k++) { mdx_ent *e = q[k].e; void *mb; uint64_t mo, rg, cg;
        if (!mtl_gpu_addr(e->ind, 4 * q[k].words, &mb, &mo, &rg) || !mtl_gpu_addr(e->cnt, 4, &mb, &mo, &cg)) continue;
        e->out = og + 32 * (uint64_t)k; j[k] = (mjob){rg, cg, e->out, q[k].i, q[k].words}; }
    id ce = enc_c_begin(NULL); enc_c_table(ce, at); tab_buf(at, ab, ao, 0); [ce setComputePipelineState:ps];
    enc_c_dispatch(ce, MTLSizeMake((NSUInteger)nj / 64, 1, 1), MTLSizeMake(64, 1, 1));
    enc_c_end(ce);
    args_dirty_all();
    g_mdx_draws += (uint64_t)nq;
    if (!g_mdx_runs++) MLOG("indirect-count multi-draw masking: first time, %d draws (their records are copied on the GPU, zeros past the count, before the render pass)", nq);
    else if (g_mdx_runs % 3600 == 0) MLOG("indirect-count multi-draw masking: %llu times, %llu draws (%llu encoded alone, mdx_next), render pass split %llu times; waits for the GPU-written count %llu",
                                          (unsigned long long)g_mdx_runs, (unsigned long long)g_mdx_draws, (unsigned long long)g_mdx_fast, (unsigned long long)g_mdx_splits, (unsigned long long)g_mdi_waits);
}
static void mdx_run(const p_draw *dw, const p_draw_idx *di) {
    id<MTLComputePipelineState> ps; id at;
    if (!mdx_pipe(&ps, &at)) return;
    if (g_mdx_ep != g_mdx_epoch || g_mdx_sub != g_arena_gen || g_mdx_n > MDX_SLOTS / 4) { g_mdx_tag++; g_mdx_n = 0; g_mdx_ep = g_mdx_epoch; g_mdx_sub = g_arena_gen; }
    enum { QMAX = MDX_SLOTS / 4 };
    static mdx_qent q[QMAX]; int nq = 0;
    uint64_t lo = ~0ull, hi = 0;   // the hull of the records and counts taken, for the uniform update check
    #define MDX_TAKE(IND, CNT, I, W) do { mdx_ent *e_ = mdx_slot((IND), (CNT)); if (e_->tag != g_mdx_tag && nq < QMAX) { *e_ = (mdx_ent){(IND), (CNT), 0, g_mdx_tag}; g_mdx_n++; \
        q[nq].e = e_; q[nq].i = (uint32_t)(I); q[nq++].words = (W); lo = MIN(lo, MIN((IND), (CNT))); hi = MAX(hi, MAX((IND) + 4 * (W), (CNT) + 4)); } } while (0)
    if (dw) MDX_TAKE(dw->ind, dw->mdi_cnt, dw->mdi_i, 4); else MDX_TAKE(di->ind, di->mdi_cnt, di->mdi_i, 5);
    if (g_mdx_range) {   // the range's later draws, in batches of at most QMAX (the next batch starts at the first draw this one left out)
        const p_multi_draw *m = g_mdx_range;
        for (int i = (dw ? dw->mdi_i : di->mdi_i) + 1; i < m->max && nq < QMAX; i++) MDX_TAKE(m->ind + (uint64_t)i * (uint64_t)m->stride, m->cnt, i, dw ? 4u : 5u);
    } else if (g_exec_next && g_ret_n <= 8) {   // later draws in replay order (current list → callers → the rest of this submission)
        fz_cursor cur = fz_cursor_from_exec();
        const uint8_t *p; op_hdr h; const void *a;
        for (int guard = 0; guard < 200000 && nq < QMAX && fz_next(&cur, &p, &h, &a); guard++) {
            if (h.op == OP_DISPATCH || h.op == OP_COPY_B2B || h.op == OP_CLEAR_BUF || h.op == OP_COPY_T2B) break;
            if (h.op == OP_UPDATE_UB) { uint64_t d, n; memcpy(&d, a, 8); memcpy(&n, (const uint8_t *)a + 8, 8);
                int hit = 0; for (int k = 0; d < hi && lo < d + n && k < nq && !hit; k++) { const mdx_ent *e = q[k].e; hit = (d < e->ind + 4 * q[k].words && e->ind < d + n) || (d < e->cnt + 4 && e->cnt < d + n); }
                if (hit) { g_mdx_stop = p; break; } continue; }
            p_draw dt; p_draw_idx it; const p_draw *d = h.op == OP_DRAW ? draw_rec(a, h.size, &dt) : NULL; const p_draw_idx *x = h.op == OP_DRAW_IDX ? draw_idx_rec(a, h.size, &it) : NULL;
            if (d && mdx_wanted(d, NULL)) MDX_TAKE(d->ind, d->mdi_cnt, d->mdi_i, 4);
            else if (x && mdx_wanted(NULL, x)) MDX_TAKE(x->ind, x->mdi_cnt, x->mdi_i, 5);
        }
    }
    #undef MDX_TAKE
    mdx_emit_q(q, nq, 0);
}
static void mdx_prepass(void) {
    g_mdx_pre_n = 0; g_mdx_pre_rem = 0;
    if (g_enc || g_defer_replaying || !g_exec_next || g_ret_n > 8) return;
    id<MTLComputePipelineState> ps; id at;
    if (!mdx_pipe(&ps, &at)) return;
    if (g_mdx_ep != g_mdx_epoch || g_mdx_sub != g_arena_gen || g_mdx_n > MDX_SLOTS / 4) { g_mdx_tag++; g_mdx_n = 0; g_mdx_ep = g_mdx_epoch; g_mdx_sub = g_arena_gen; }
    enum { QMAX = MDX_SLOTS / 4 };
    static mdx_qent q[QMAX]; int nq = 0;
    uint64_t lo = ~0ull, hi = 0;
    #define MDX_TAKE(IND, CNT, I, W) do { mdx_ent *e_ = mdx_slot((IND), (CNT)); if (e_->tag != g_mdx_tag && nq < QMAX) { *e_ = (mdx_ent){(IND), (CNT), 0, g_mdx_tag}; g_mdx_n++; \
        q[nq].e = e_; q[nq].i = (uint32_t)(I); q[nq++].words = (W); lo = MIN(lo, MIN((IND), (CNT))); hi = MAX(hi, MAX((IND) + 4 * (W), (CNT) + 4)); } } while (0)
    fz_cursor cur = fz_cursor_from_exec();
    const uint8_t *p; op_hdr h; const void *a;
    for (int guard = 0; guard < 200000 && nq < QMAX && fz_next_md(&cur, &p, &h, &a); guard++) {
        if (h.op == OP_SET_RT || h.op == OP_DISPATCH || h.op == OP_COPY_B2B || h.op == OP_CLEAR_BUF || h.op == OP_COPY_T2B || h.op == OP_SIGNAL_EVENT) break;
        if (h.op == OP_BARRIER) { int32_t bits; memcpy(&bits, a, 4); if (bits & NVN_BARRIER_ORDER_INDIRECT_DATA_BIT) break; continue; }
        if (h.op == OP_UPDATE_UB) {
            uint64_t d, n; memcpy(&d, a, 8); memcpy(&n, (const uint8_t *)a + 8, 8);
            int hit = 0; for (int k = 0; d < hi && lo < d + n && k < nq && !hit; k++) { const mdx_ent *e = q[k].e; hit = (d < e->ind + 4 * q[k].words && e->ind < d + n) || (d < e->cnt + 4 && e->cnt < d + n); }
            if (hit) { g_mdx_stop = p; break; }
            continue;
        }
        if (h.op == OP_MULTI_DRAW && h.size >= 8 + sizeof(p_multi_draw)) {
            const p_multi_draw *m = a;
            p_draw arr = {.prim = m->prim, .instances = 1, .ind = m->ind, .mdi_cnt = m->cnt};
            p_draw_idx idx = {.prim = m->prim, .itype = m->itype, .instances = 1, .ibuf = m->ibuf, .ind = m->ind, .mdi_cnt = m->cnt};
            int wanted = m->cnt && m->max > 0 && m->max <= MDX_SLOTS && m->stride && (m->itype < 0 ? mdx_wanted(&arr, NULL) : mdx_wanted(NULL, &idx));
            if (!wanted) continue;
            if (m->max > QMAX - nq) break;
            if (g_mdx_pre_n < (int)(sizeof g_mdx_pre_recs / sizeof *g_mdx_pre_recs)) g_mdx_pre_recs[g_mdx_pre_n++] = p;
            uint32_t w = m->itype < 0 ? 4u : 5u;
            for (int i = 0; i < m->max && nq < QMAX; i++) MDX_TAKE(m->ind + (uint64_t)i * (uint64_t)m->stride, m->cnt, i, w);
            continue;
        }
        p_draw dt; p_draw_idx it; const p_draw *d = h.op == OP_DRAW ? draw_rec(a, h.size, &dt) : NULL; const p_draw_idx *x = h.op == OP_DRAW_IDX ? draw_idx_rec(a, h.size, &it) : NULL;
        if (d && mdx_wanted(d, NULL)) MDX_TAKE(d->ind, d->mdi_cnt, d->mdi_i, 4);
        else if (x && mdx_wanted(NULL, x)) MDX_TAKE(x->ind, x->mdi_cnt, x->mdi_i, 5);
    }
    #undef MDX_TAKE
    g_mdx_pre_rem = g_mdx_pre_n;
    g_mdx_pre_ep = g_mdx_epoch; g_mdx_pre_sub = g_arena_gen;
    if (nq) mdx_emit_q(q, nq, 1);
}
// The draws of one multi-draw are recorded back to back with the same state, and only the first few are live: each one replayed right after the one before it (no op between them,
// the same open pass) is encoded alone, without the rest of draw's work, which cost a whole draw for each masked one (about 1.5 µs on an M4 Pro, 1,100 a frame in Kamura Village)
static struct { const uint8_t *next; const void *enc; uint64_t cnt, ig, il, pass; int i; MTLPrimitiveType mp; MTLIndexType it; } g_mdxc;
static void mdx_chain(uint64_t cnt, int i, MTLPrimitiveType mp, MTLIndexType it, uint64_t ig, uint64_t il) {
    const uint8_t *next = g_mdx_range ? g_exec_cur : g_exec_next;   // in a range every draw has the range's record as its place in the replay
    g_mdxc = g_defer_replaying || !next ? (typeof(g_mdxc)){0} : (typeof(g_mdxc)){next, (__bridge const void *)g_enc, cnt, ig, il, g_stat_pass, i, mp, it};
}
static int mdx_next(const p_draw *dw, const p_draw_idx *di) {
    uint64_t cnt = dw ? dw->mdi_cnt : di->mdi_cnt, out; int i = dw ? dw->mdi_i : di->mdi_i;
    if (!g_mdxc.next || g_mdxc.next != g_exec_cur || !g_enc || g_mdxc.enc != (__bridge const void *)g_enc || g_mdxc.pass != g_stat_pass || g_mdxc.cnt != cnt || g_mdxc.i + 1 != i
        || g_defer_replaying || passdump() || !mdx_find(dw ? dw->ind : di->ind, cnt, &out) || !out) return 0;
    // 同一笔多绘制的后续子绘制：上面的条件保证与前一条同编码器、同一遍、同计数、序号相连、中间没有别的指令——状态（程序、写掩码、深度模板）与第一条一样，
    //   第一条 udc_note_draw 的精确写入记账对它同样成立。原先这里的编码按「没有精确记账」处理、把本遍全部附件记成写过：免加载的附件（到遍结束不写、没读入）
    //   被当成写过、遍末写回没读入的片上内容，贴图成一块块的黑（#1468 Trine 5 标题页：G-buffer 一笔多绘制 5 张颜色附件，「lookahead wrong」wwhy=6）
    g_udc_precise = 1;
    if (dw) enc_r_draw_indirect(g_enc, g_mdxc.mp, out); else enc_r_draw_indexed_indirect(g_enc, g_mdxc.mp, g_mdxc.it, g_mdxc.ig, g_mdxc.il, out);
    g_stat_draw++; g_mdx_fast++; g_mdxc.next = g_mdx_range ? g_exec_cur : g_exec_next; g_mdxc.i = i;
    return 1;
}
// A large indirect-count multi-draw (OP_MULTI_DRAW; upstream reference implementation, MIT, c7ba23df): one record whatever the maximum. Through the GPU mask (mdx_run) in batches with a
//   table fresh for this range, no CPU wait. Coincident records (stride 0) need a different predicate at each index and the conversion paths (quads, fans, 8-bit indices) a resolved
//   count; beyond the mask table's capacity the count is read once too, so an INT_MAX maximum with a few live draws neither allocates nor encodes billions of masked draws
int nvn_be_multi_draw_range(void) { return 1; }   // hle_nvn.c records a large call as one OP_MULTI_DRAW (draw_multi replays it)
int nvn_be_buf_extent_consumer(void) { return 0; }   // Metal 回放不按地址查活缓冲长度：hle_nvn.c 不登记活缓冲（建删零开销）
static void draw_multi(const p_multi_draw *m) {
    if (!m->cnt || m->max <= 0) return;
    if (!g_mdx_pre_active) ubd_land();   // a deferred inline update can feed the count or any record in the range (already checked by mdx_prepass when pre-masked)
    p_draw arr = {.prim = m->prim, .instances = 1, .ind = m->ind, .mdi_cnt = m->cnt};
    p_draw_idx idx = {.prim = m->prim, .itype = m->itype, .instances = 1, .ibuf = m->ibuf, .ind = m->ind, .mdi_cnt = m->cnt};
    p_draw *dw = m->itype < 0 ? &arr : NULL; p_draw_idx *di = dw ? NULL : &idx;
    uint32_t n = (uint32_t)m->max;
    if (n <= MDX_SLOTS && m->stride && mdx_wanted(dw, di)) g_mdx_range = m;
    else { if (g_mdx_pre_active) ubd_land(); n = MIN(n, mdi_count(m->cnt)); arr.mdi_cnt = idx.mdi_cnt = 0; }   // the live draws only, as plain indirect draws
    { static int once; if (!once++) MLOG("indirect-count multi-draw of up to %d draws replayed as one range (%s)", m->max, g_mdx_range ? "masked on the GPU" : "the count read once"); }
    for (uint32_t i = 0; i < n; i++) {
        arr.mdi_i = idx.mdi_i = (int32_t)i;
        arr.ind = idx.ind = m->ind + (uint64_t)i * (uint64_t)m->stride;
        draw(dw, di);
    }
    g_mdx_range = NULL; g_mdxc.next = NULL;
}
// ---------- Indirect draw GPU baseInstance -> c0 + 0x644 copy ----------
// Switch shaders translated with QueryHasConstantBufferDrawParameters() == false read gl_BaseInstance from DRV0 c0 + 0x644.
// Indirect draws (DrawArraysIndirect / DrawElementsIndirect / MultiDraw*) leave baseInstance in GPU memory (ind + 12 or ind + 16);
// a compute pass before the render pass copies each upcoming indirect draw's word into its own DRV0 slice (Vulkan parity: rp_draw.c).
#define BINST_MAX 2048
typedef struct {
    const uint8_t *rec; int32_t mdi_i; uint64_t ind; uint8_t indexed, mask, used;
    ind_drv0_ent sl[2];
} binst_ent;
static binst_ent g_binst[BINST_MAX];
static int g_binst_n, g_binst_cur, g_binst_full;
static uint64_t g_binst_ep = ~0ull, g_binst_sub, g_binst_runs, g_binst_draws, g_binst_splits;
static uint8_t g_binst_mask;
static const uint8_t *g_binst_stop;
static binst_ent *g_ind_binst_ent;
static const char k_binst_msl[] =
"#include <metal_stdlib>\nusing namespace metal;\n"
"struct bjob { device const uint *src; device uint *dst; };\n"
"kernel void binst_copy(device const bjob *j [[buffer(0)]], uint t [[thread_position_in_grid]]) {\n"
"  bjob b = j[t]; if (!b.dst) return; *b.dst = *b.src; }\n";
static int ind_binst_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_IND_BINST"); v = !(e && !strcmp(e, "0")); } return v; }
static uint8_t binst_need(NvProg *pr) {
    uint8_t need = 0;
    for (int st = 0; st < 2; st++) if (pr && pr->sh[st] && pr->sh[st]->rf.drv_read[0]) need |= (uint8_t)(1u << st);
    return need;
}
static binst_ent *binst_take(const p_draw *dw, const p_draw_idx *di, uint8_t need) {
    if (g_binst_ep != g_binst_epoch || g_binst_sub != g_arena_gen) return NULL;
    uint64_t ind = dw ? dw->ind : di->ind; int32_t mi = dw ? dw->mdi_i : di->mdi_i; uint8_t ix = di != NULL;
    for (int i = g_binst_cur; i < g_binst_n; i++) {
        binst_ent *e = &g_binst[i];
        if (e->used) continue;
        if (e->rec != g_exec_cur || e->mdi_i != mi) continue;
        if (e->ind != ind || e->indexed != ix || (e->mask & need) != need) return NULL;
        g_binst_cur = i;
        return e;
    }
    return NULL;
}
static void sub_cut_pass(void);
static void binst_hoist(const p_draw *dw, const p_draw_idx *di, uint8_t need, int prepass) {
    static id<MTLComputePipelineState> ps; static id at; static int failed;
    if (failed) return;
    if (prepass) { if (g_enc || !g_binst_mask) return; }
    else { if (!need) return; g_binst_mask |= need; }
    if (!at) {
        NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(k_binst_msl) options:nil error:&e];
        id<MTLFunction> f = lib ? [lib newFunctionWithName:@"binst_copy"] : nil;
        ps = f ? [g_dev newComputePipelineStateWithFunction:f error:&e] : nil;
        at = ps ? rec_table(tab_new(1, 0, 0, &e)) : nil;
        if (!at) { failed = 1; MLOG("【红】 indirect draw baseInstance copy: cannot create compute pipeline %s", e.localizedDescription.UTF8String); return; }
    }
    if (!prepass && g_enc) {
        sub_cut_pass();
        if (g_enc) { g_binst_splits++; PD("M %llu indirect baseInstance copy: render pass split here", g_stat_pass); rp_end(); }
    }
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    g_binst_n = 0; g_binst_cur = 0; g_binst_full = 0; g_binst_ep = g_binst_epoch; g_binst_sub = g_arena_gen; g_binst_stop = NULL;
    uint64_t lo = ~0ull, hi = 0;
    #define BINST_TAKE(REC, MI, IND, IX) do { \
        if (g_binst_n < BINST_MAX) { \
            uint64_t sz_ = (IX) ? 20ull : 16ull; \
            binst_ent *e_ = &g_binst[g_binst_n++]; memset(e_, 0, sizeof *e_); \
            e_->rec = (REC); e_->mdi_i = (MI); e_->ind = (IND); e_->indexed = (IX); e_->mask = g_binst_mask; \
            if ((IND) < lo) lo = (IND); if ((IND) + sz_ > hi) hi = (IND) + sz_; \
        } \
    } while (0)
    if (!prepass && (dw || di)) BINST_TAKE(g_exec_cur, dw ? dw->mdi_i : di->mdi_i, dw ? dw->ind : di->ind, di != NULL);
    if (!prepass && g_mdx_range) {
        const p_multi_draw *m = g_mdx_range;
        for (int i = (dw ? dw->mdi_i : di->mdi_i) + 1; i < m->max && g_binst_n < BINST_MAX; i++)
            BINST_TAKE(g_exec_cur, i, m->ind + (uint64_t)i * (uint64_t)m->stride, di != NULL);
    } else if (!g_defer_replaying && g_exec_next && g_ret_n <= 8) {
        fz_cursor cur = fz_cursor_from_exec();
        const uint8_t *p; op_hdr h; const void *a;
        for (int guard = 0; guard < 200000 && g_binst_n < BINST_MAX && fz_next_md(&cur, &p, &h, &a); guard++) {
            if (h.op == OP_DISPATCH || h.op == OP_COPY_B2B || h.op == OP_CLEAR_BUF || h.op == OP_COPY_T2B || h.op == OP_SIGNAL_EVENT) break;
            if (h.op == OP_BARRIER) { int32_t bits; memcpy(&bits, a, 4); if (bits & NVN_BARRIER_ORDER_INDIRECT_DATA_BIT) break; continue; }
            if (h.op == OP_UPDATE_UB) {
                uint64_t d, n; memcpy(&d, a, 8); memcpy(&n, (const uint8_t *)a + 8, 8);
                int hit = 0;
                if (d < hi && lo < d + n) {
                    for (int k = 0; k < g_binst_n; k++) {
                        uint64_t sz = g_binst[k].indexed ? 20ull : 16ull;
                        if (d < g_binst[k].ind + sz && g_binst[k].ind < d + n) { hit = 1; break; }
                    }
                }
                if (hit) { g_binst_stop = p; break; }
                continue;
            }
            if (h.op == OP_MULTI_DRAW && h.size >= 8 + sizeof(p_multi_draw)) {
                const p_multi_draw *m = a;
                if (m->cnt && m->max > 0 && m->max <= MDX_SLOTS && m->stride) {
                    uint8_t ix = m->itype >= 0;
                    for (int i = 0; i < m->max && g_binst_n < BINST_MAX; i++)
                        BINST_TAKE(p, i, m->ind + (uint64_t)i * (uint64_t)m->stride, ix);
                }
                continue;
            }
            p_draw dt; p_draw_idx it;
            const p_draw *d = h.op == OP_DRAW ? draw_rec(a, h.size, &dt) : NULL;
            const p_draw_idx *x = h.op == OP_DRAW_IDX ? draw_idx_rec(a, h.size, &it) : NULL;
            if (d && d->ind) BINST_TAKE(p, d->mdi_i, d->ind, 0);
            else if (x && x->ind) BINST_TAKE(p, x->mdi_i, x->ind, 1);
        }
    }
    #undef BINST_TAKE
    g_binst_full = (g_binst_n >= BINST_MAX);
    if (!g_binst_n) return;
    if (g_nubd) ubd_land_compute();
    typedef struct { uint64_t src, dst; } bjob;
    int max_jobs = g_binst_n * 2;
    int nj = (max_jobs + 63) & ~63;
    id<MTLBuffer> ab; size_t ao = arena_alloc((size_t)nj * sizeof(bjob), &ab);
    bjob *jobs = (bjob *)((uint8_t *)ab.contents + ao);
    memset(jobs, 0, (size_t)nj * sizeof(bjob));
    __unsafe_unretained id<MTLBuffer> rbufs[BINST_MAX], wbufs[BINST_MAX * 2];
    int nrb = 0, nwb = 0, job_n = 0;
    for (int k = 0; k < g_binst_n; k++) {
        binst_ent *e = &g_binst[k];
        void *mb; uint64_t mo, ig;
        if (!mtl_gpu_addr(e->ind, e->indexed ? 20 : 16, &mb, &mo, &ig) || (mo & 3)) continue;
        uint64_t src_gpu = ig + (e->indexed ? 16ull : 12ull);
        if (g_m3) {
            __unsafe_unretained id<MTLBuffer> sb = (__bridge id<MTLBuffer>)mb;
            int seen = 0; for (int i = 0; i < nrb; i++) if (rbufs[i] == sb) { seen = 1; break; }
            if (!seen && nrb < BINST_MAX) rbufs[nrb++] = sb;
        }
        for (int st = 0; st < 2; st++) {
            if (!(e->mask >> st & 1)) continue;
            __unsafe_unretained id<MTLBuffer> db; size_t doff = arena_alloc_u(DRV_SIZE, &db);
            uint8_t *cpu = g_cur_arena->cpu + doff; uint64_t gpu = g_cur_arena->gpu + doff;
            e->sl[st] = (ind_drv0_ent){db, doff, gpu, cpu};
            jobs[job_n++] = (bjob){src_gpu, gpu + 0x644};
            if (g_m3) {
                int seen = 0; for (int i = 0; i < nwb; i++) if (wbufs[i] == db) { seen = 1; break; }
                if (!seen && nwb < BINST_MAX * 2) wbufs[nwb++] = db;
            }
        }
    }
    if (!job_n) { g_binst_n = 0; g_binst_full = 0; return; }
    int disp_groups = (job_n + 63) / 64;
    id ce = enc_c_begin(NULL); enc_c_table(ce, at); tab_buf(at, ab, ao, 0); [ce setComputePipelineState:ps];
    if (g_m3) {
        for (int i = 0; i < nrb; i++) [(id<MTLComputeCommandEncoder>)ce useResource:rbufs[i] usage:MTLResourceUsageRead];
        for (int i = 0; i < nwb; i++) [(id<MTLComputeCommandEncoder>)ce useResource:wbufs[i] usage:MTLResourceUsageWrite];
    }
    enc_c_dispatch(ce, MTLSizeMake((NSUInteger)disp_groups, 1, 1), MTLSizeMake(64, 1, 1));
    enc_c_end(ce);
    args_dirty_all();
    g_binst_draws += (uint64_t)g_binst_n;
    if (!g_binst_runs++) MLOG("indirect draw baseInstance copy: first time, %d draws (%d copies queued before the render pass)", g_binst_n, job_n);
    else if (g_binst_runs % 3600 == 0) MLOG("indirect draw baseInstance copy: %llu times, %llu draws, render pass split %llu times",
                                           (unsigned long long)g_binst_runs, (unsigned long long)g_binst_draws, (unsigned long long)g_binst_splits);
}
static void binst_run(const p_draw *dw, const p_draw_idx *di, uint8_t need) { binst_hoist(dw, di, need, 0); }
static void binst_prepass(void) {
    if (!ind_binst_on() || !g_binst_mask || g_enc || g_defer_replaying || !g_exec_next || g_ret_n > 8) return;
    if (g_binst_ep == g_binst_epoch && g_binst_sub == g_arena_gen && !(g_binst_full && (g_binst_n == 0 || g_binst[g_binst_n - 1].used))) return;
    binst_hoist(NULL, NULL, g_binst_mask, 1);
}
// S2Arm: draws the game issued that were dropped (docs/设计_双轨.md §11.3 picture check, graphics/nvn/host/pic_watch.inc): feat = a feature the host lacks (geometry capture limits, transform
// feedback it cannot capture, DrawTransformFeedback), err = no render pipeline, the pass did not begin, no program. Benign skips (rasterizer discard, both faces culled, empty scissor) are not counted
static _Atomic uint64_t g_bad_feat, g_bad_err;
void nvn_be_bad_draw_feat(void) { atomic_fetch_add_explicit(&g_bad_feat, 1, memory_order_relaxed); }
void mtl_bad_draws(uint64_t *feat, uint64_t *err) { *feat = atomic_load_explicit(&g_bad_feat, memory_order_relaxed); *err = atomic_load_explicit(&g_bad_err, memory_order_relaxed); }
#define BAD_ERR() atomic_fetch_add_explicit(&g_bad_err, 1, memory_order_relaxed)
// ---------- Transform feedback ----------
// A draw under rasterizer discard rasterizes nothing; with feedback active it captures its vertex shader's outputs into the bound feedback buffers. Pokémon Legends: Z-A skins its characters
// so: a vertex-only skinning program writes positions (12 bytes a vertex) and packed normal / tangent bits (4 bytes each), and the character draws read those buffers as vertex streams.
// Metal has no feedback stage: the shader's main0_tf entry point (dmsh_build.py vs_tf) runs in a pipeline with rasterization off, in an encoder of its own with no attachments (the game draws
// these while its frame target is bound; a pass of that target would load and store it for nothing), and stores the outputs at TF_SLOT + b. Each draw writes from the buffer's current offset on.
// Only plain array draws are captured (all this game makes); the encoder's barriers order the writes before the draws that read them
enum { TF_SLOT = 8 };   // = dmsh_build.py TF_SLOT
static void *tf_pso_ptr(NvShader *vs);   // borrowed, as pso_get_vs_ptr: g_pso holds what it returns
#define tf_pso(vs) ((__bridge id<MTLRenderPipelineState>)tf_pso_ptr(vs))
static void *tf_pso_ptr(NvShader *vs) {
    pso_key k; static const uint32_t cf[8]; pso_key_fill(&k, vs, nil, cf, 0, 0, 1, 0); k.fsfn = TF_MARK;
    __unsafe_unretained id<MTLRenderPipelineState> cached = hm_get_id(&g_pso, &k);
    if (cached) return (__bridge void *)cached;
    if (hm_get_id(&g_pso_fail, &k)) return NULL;
    NSError *e = nil; id<MTLRenderPipelineState> ps = [g_dev newRenderPipelineStateWithDescriptor:pso_desc(&k, vs, nil, nil, 0) error:&e];
    if (!ps) { MLOG("【红】 failed to create the transform feedback pipeline (vertex %s): %s", vs->key, e.localizedDescription.UTF8String); hm_put_id(&g_pso_fail, &k, NSNull.null); return NULL; }
    hm_put_id(&g_pso, &k, ps); pb_built_r(&k);
    return (__bridge void *)ps;
}
// Instanced draws capture one instance at a time (the feedback stage writes instance j's vertices after instance j - 1's). Indexed draws capture each index in draw order: the
// vertex function runs over the index range [lo, hi] into scratch (store slot = vertex id - lo), and a gather kernel (tf_gather) copies the records in index order into the
// feedback buffers; Metal gives a vertex function no ordinal of its index and may share one invocation among repeated indices, so the index list cannot drive the stores itself
static void tf_draw(NvProg *pr, const p_draw *dw, const p_draw_idx *di) {
    __unsafe_unretained NvShader *vs = pr ? pr->sh[0] : nil;
    if (!S.tf_on) { PD("Z %llu draw skipped: rasterizer discard (vertex %s%s)", g_stat_pass + !g_enc, vs ? vs->key : "-", shader_writes(vs) ? ", writes storage" : ""); return; }
    if (S.tf_gpu) { nvn_be_bad_draw_feat(); RED_ONCE(126, "transform feedback: a vertex shader capture after a geometry shader capture in the same Begin (vertex %s): the offset is on the GPU only, not captured", vs ? vs->key : "-"); return; }
    if (!vs || !vs->tf_fn) { nvn_be_bad_draw_feat(); RED_ONCE(100, "transform feedback with vertex shader %s, which has no capture entry point: nothing captured", vs ? vs->key : "-"); return; }
    int prim = dw ? dw->prim : di ? di->prim : 0;
    if ((!dw && !di) || (dw && (dw->ind || dw->mdi_cnt)) || (di && (di->ind || di->mdi_cnt)) || prim == 6 || prim == 7) {
        nvn_be_bad_draw_feat(); RED_ONCE(101, "transform feedback draw that is indirect or a fan / quad list (vertex %s): not captured", vs->key); return; }
    int count = dw ? dw->count : di->count; uint32_t inst = (uint32_t)MAX(dw ? dw->instances : di->instances, 1), base_inst = (uint32_t)(dw ? dw->base_instance : di->base_instance);
    if (count <= 0) return;
    // indexed: the indices on the CPU (as the geometry capture reads them), their range
    uint32_t *order = NULL, lo = 0, hi = 0; int64_t first = dw ? dw->first : 0;
    if (di) {
        int isz = 1 << di->itype;
        const uint8_t *hib = NULL;
        if (di->itype < 0 || di->itype > 2 || !(hib = nvn_host_ptr(di->ibuf, (uint64_t)count * isz)) || !(order = malloc((size_t)count * 4))) {
            free(order); nvn_be_bad_draw_feat(); RED_ONCE(122, "transform feedback indexed draw (vertex %s): index buffer not readable, not captured", vs->key); return; }
        uint32_t ri = S.restart.index & (isz == 1 ? UINT8_MAX : isz == 2 ? UINT16_MAX : UINT32_MAX); lo = UINT32_MAX;
        for (int i = 0; i < count; i++) { uint32_t v = 0; memcpy(&v, hib + (size_t)i * isz, isz);
            if (S.restart.on && v == ri) { free(order); nvn_be_bad_draw_feat(); RED_ONCE(123, "transform feedback indexed draw with primitive restart (vertex %s): not captured", vs->key); return; }
            order[i] = v; lo = MIN(lo, v); hi = MAX(hi, v); }
        first = (int64_t)lo + di->base_vertex;
        if (first < 0 || (uint64_t)hi - lo + 1 > (64u << 20)) { free(order); nvn_be_bad_draw_feat(); RED_ONCE(124, "transform feedback indexed draw (vertex %s): vertex range out of bounds, not captured", vs->key); return; }
    }
    uint32_t span = di ? hi - lo + 1 : (uint32_t)count;   // vertices the vertex function runs over per instance
    if (m3_origin_on() && (first < 0 || first > INT32_MAX || (uint64_t)count * inst > UINT32_MAX || (uint64_t)span * inst > UINT32_MAX)) {
        free(order); nvn_be_bad_draw_feat(); RED_ONCE(124, "transform feedback: vertex or instance range exceeds the capture index domain, not captured"); return;
    }
    uint64_t gpu[4] = {0}, tmp[4] = {0};
    id<MTLBuffer> scratch[4] = {nil}, target[4] = {nil}; size_t scratch_off[4] = {0}; uint64_t target_off[4] = {0};
    for (int b = 0; b < 4; b++) {
        if (!vs->tf_stride[b]) continue;
        uint64_t n = (uint64_t)count * inst * vs->tf_stride[b], at = S.tf[b].addr + S.tf_off[b]; void *mb; uint64_t mo;
        if (!S.tf[b].addr || S.tf_off[b] + n > S.tf[b].size || !mtl_gpu_addr(at, n, &mb, &mo, &gpu[b])) {
            free(order); nvn_be_bad_draw_feat(); RED_ONCE(102, "transform feedback buffer %d of vertex %s is unbound, too small or in no memory pool (%#llx + %llu of %llu): not captured", b, vs->key, (unsigned long long)S.tf[b].addr, (unsigned long long)(S.tf_off[b] + n), (unsigned long long)S.tf[b].size);
            return; }
        uint64_t prefix = (uint64_t)first * vs->tf_stride[b];
        if (di || (m3_origin_on() && mo < prefix)) {
            id<MTLBuffer> tb; scratch_off[b] = arena_alloc_origin((size_t)span * inst * vs->tf_stride[b], prefix, &tb); scratch[b] = tb;
            tmp[b] = scratch[b].gpuAddress + scratch_off[b]; target[b] = (__bridge id<MTLBuffer>)mb; target_off[b] = mo;
        }
    }
    static id<MTLComputePipelineState> gather;
    if (di && !gather) { NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(k_tf_gather_msl) options:nil error:&e];
        if (lib) gather = [g_dev newComputePipelineStateWithFunction:[lib newFunctionWithName:@"tf_gather"] error:&e];
        if (!gather) { free(order); nvn_be_bad_draw_feat(); RED_ONCE(125, "transform feedback gather kernel: %s", e.localizedDescription.UTF8String); return; } }
    __unsafe_unretained id<MTLRenderPipelineState> ps = tf_pso(vs);
    if (!ps) { free(order); return; }
    rp_end(); ubd_land();   // the deferred inline updates first: this draw comes before draw's conflict check (ubd_conflict) and writes its capture buffers
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    MTL4RenderPassDescriptor *d = pass_desc(); d.renderTargetWidth = 1; d.renderTargetHeight = 1; d.defaultRasterSampleCount = 1;
    id<MTL4RenderCommandEncoder> en = enc_r_begin(d);
    enc_r_pso(en, ps);
    p_draw range = {.prim = prim, .first = (int32_t)first, .count = (int32_t)span, .instances = (int32_t)inst, .base_instance = (int32_t)base_inst};
    bind_vbufs(en, vs, &range, NULL);
    vconv_bind(en, vs, 1, &range, NULL);
    wd_drop(); args_dirty_all(); encode_args(en, vs, 0, 1);   // 宽屏不改写只产出数据的绘制（widen_glue.inc wd_drop）
    for (uint32_t j = 0; j < inst; j++) {
        for (int b = 0; b < 4; b++) if (vs->tf_stride[b]) {   // vertex v of instance j stores at v × stride: the pointer starts first × stride before instance j's records
            uint64_t base = tmp[b] ? tmp[b] + (uint64_t)j * span * vs->tf_stride[b] : gpu[b] + (uint64_t)j * count * vs->tf_stride[b];
            enc_r_vbuf(en, TF_SLOT + b, base - (uint64_t)first * vs->tf_stride[b]); }
        if (inst > 1 || base_inst) enc_r_draw_instanced(en, MTLPrimitiveTypePoint, (NSUInteger)first, span, 1, base_inst + j);
        else enc_r_draw(en, MTLPrimitiveTypePoint, (NSUInteger)first, span);
    }
    m4_end(en);
    if (di) {   // records in draw order: entry j·count + i is instance j's capture of index i (slot j·span + index − lo in scratch)
        uint64_t total = (uint64_t)count * inst; id<MTLBuffer> mb_; size_t mo_ = arena_alloc((size_t)total * 4, &mb_); uint32_t *map = (uint32_t *)((uint8_t *)mb_.contents + mo_);
        for (uint32_t j = 0; j < inst; j++) for (int i = 0; i < count; i++) map[(size_t)j * count + i] = j * span + order[i] - lo;
        id<MTL4ComputeCommandEncoder> ce = enc_c_begin(NULL); enc_c_pso(ce, gather);
        for (int b = 0; b < 4; b++) if (vs->tf_stride[b]) {
            nvn_tf_gather jb = {tmp[b], gpu[b], mb_.gpuAddress + mo_, vs->tf_stride[b] / 4u, (uint32_t)total};
            id<MTLBuffer> jbb; size_t jo = arena_alloc(sizeof jb, &jbb); memcpy((uint8_t *)jbb.contents + jo, &jb, sizeof jb);
            enc_c_args(ce, jbb.gpuAddress + jo, 0); enc_c_dispatch(ce, MTLSizeMake((total + 63) / 64, 1, 1), MTLSizeMake(64, 1, 1)); }
        enc_c_end(ce);
    }
    else for (int b = 0; b < 4; b++) if (scratch[b]) {
        uint64_t n = (uint64_t)count * inst * vs->tf_stride[b], at = S.tf[b].addr + S.tf_off[b];
        // blit_buf waits for the render fence on Metal 3 and orders later readers.
        enc_b_copy_buffer(blit_buf(0, 0, at, at + n), scratch[b], scratch_off[b], target[b], target_off[b], n);
    }
    for (int b = 0; b < 4; b++) if (vs->tf_stride[b]) { uint64_t n = (uint64_t)count * inst * vs->tf_stride[b]; pend_add(S.tf[b].addr + S.tf_off[b], n, 4); S.tf_off[b] += n; }
    free(order);
    args_dirty_all(); g_enc_pso = nil; g_enc_dss = nil; g_ed.ok = 0;
    { static int once; if (!once++) MLOG("transform feedback: first capture (vertex %s, %d vertices)", vs->key, count); }
    { static int once; if ((di || inst > 1) && !once++) MLOG("transform feedback: first %s capture (vertex %s, %d %s × %u instances)", di ? "indexed" : "instanced", vs->key, count, di ? "indices" : "vertices", inst); }
    PD("T %llu tf capture vs=%s first=%lld count=%d instances=%u indexed=%d written %llu/%llu/%llu/%llu", g_stat_pass, vs->key, (long long)first, count, inst, di != NULL,
       (unsigned long long)S.tf_off[0], (unsigned long long)S.tf_off[1], (unsigned long long)S.tf_off[2], (unsigned long long)S.tf_off[3]);
}

#include "nvn_geometry.inc"
static void noload_witness(int i, int wwhy, int prec) {   // see g_nlw
    if (i < 0 || i >= SD_MAX) return;
    nl_wit *w = &g_nlw[i]; memset(w, 0, sizeof *w);
    w->pass = g_stat_pass; w->draw = g_stat_draw; w->wwhy = (uint8_t)wwhy; w->prec = (uint8_t)prec; w->geo = g_geo_program != nil; w->run = (uint8_t)g_gr.active; w->wd = g_wd; w->wdm = g_wd_mode;
    __unsafe_unretained NvProg *pr = g_geo_program ? g_geo_program : S.prog ? prog_peek(S.prog) : nil, *gp = S.prog ? prog_peek(S.prog) : nil;   // drawing program; the geometry stage is the bound program's
    snprintf(w->vs, sizeof w->vs, "%s", pr && pr->sh[0] ? pr->sh[0]->key : "-"); snprintf(w->fs, sizeof w->fs, "%s", pr && pr->sh[1] ? pr->sh[1]->key : "-");
    snprintf(w->gs, sizeof w->gs, "%s", gp && gp->sh[2] ? gp->sh[2]->key : "-");
}

// Lazy clears. A set of targets that gets only clears before the game sets other targets used to open a pass just to land them (rp_flush), storing the cleared attachments, and the next
// pass that attached them loaded them back. Breath of the Wild clears its G-buffer one target at a time (depth with the lighting target, then albedo, normals, the fourth), then attaches all
// five: four passes stored 27 MB of cleared memory at 1600x900 and the G-buffer pass loaded it again. Such clears now wait (g_lc): the next pass that attaches the same texture level and
// layer through the same view takes the clear as its load action. The rest land as before, in order, each in a pass of its own (lc_land), before anything else could see their textures: a
// draw whose program samples one, the pass of a draw that does not attach it (before that pass opens), and any operation other than targets, clears, state, uniform updates and buffer
// copies or fills, and the end of a command list (not of a sub-list it calls). A newer clear of the same subresource replaces an older one. Also on in TBDR mode (see ubd_on): hoisting takes the clear-only passes it proves, the rest wait here.
// DM_NVN_LAZY_CLEAR=0 turns it off
typedef struct { p_set_rt rt; uint8_t clear_c[8]; MTLClearColor cc[8]; uint8_t clear_d, clear_s; double cd; uint32_t cs; } lc_group;
enum { LC_MAX = 8 };
static lc_group g_lc[LC_MAX]; static int g_nlc;
static uint64_t g_lc_taken, g_lc_landed;   // clears a later pass took as its load action / clear-only passes still opened for them (the residency set line)
void nvn_be_lc_stats(uint64_t *taken, uint64_t *landed) { *taken = g_lc_taken; *landed = g_lc_landed; }
static int lc_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_LAZY_CLEAR"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_NVN_LAZY_CLEAR=0: clears with no draw open a pass of their own as before"); } return v; }
static int lc_same(const p_set_rt *a, int ka, const p_set_rt *b, int kb) {   // the same subresource through the same view (k = 8: depth / stencil)
    uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(a, ka, &s1, &l1, &x1); rt_sub(b, kb, &s2, &l2, &x2);
    if (!s1 || s1 != s2 || l1 != l2 || x1 != x2) return 0;
    int h1 = ka == 8 ? a->has_dview : a->has_cview[ka], h2 = kb == 8 ? b->has_dview : b->has_cview[kb];
    return h1 == h2 && (!h1 || !memcmp(ka == 8 ? &a->dview : &a->cview[ka], kb == 8 ? &b->dview : &b->cview[kb], sizeof(view_t)));
}
// Land every waiting clear, oldest first, each group in a pass of its own (rp_flush's way)
static void lc_land(void) {
    if (!g_nlc) return;
    if (g_enc) rp_end();
    int n = g_nlc; g_nlc = 0;
    typeof(R) save = R;
    for (int gi = 0; gi < n; gi++) { const lc_group *g = &g_lc[gi]; int any = g->clear_d || g->clear_s; for (int i = 0; i < 8; i++) any |= g->clear_c[i];
        if (!any || !g_cb) continue;
        R.rt = g->rt; R.has_rt = 1; memcpy(R.clear_c, g->clear_c, sizeof R.clear_c); memcpy(R.cc, g->cc, sizeof R.cc);
        R.clear_d = g->clear_d; R.clear_s = g->clear_s; R.cd = g->cd; R.cs = g->cs;
        rp_begin_ex(1); rp_end(); g_lc_landed++; }
    R = save;
}
// SetRenderTargets with clears pending and no draw since: the clears wait instead of opening a pass
static void lc_push(void) {
    if (g_nlc == LC_MAX) lc_land();
    lc_group *g = &g_lc[g_nlc];
    g->rt = R.rt; memcpy(g->clear_c, R.clear_c, sizeof g->clear_c); memcpy(g->cc, R.cc, sizeof g->cc); g->clear_d = R.clear_d; g->clear_s = R.clear_s; g->cd = R.cd; g->cs = R.cs;
    for (int gi = 0; gi < g_nlc; gi++) { lc_group *o = &g_lc[gi];   // older clears of the same subresources are overwritten
        for (int i = 0; i < 8; i++) if (o->clear_c[i]) for (int j = 0; j < 8; j++) if (g->clear_c[j]) { uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(&o->rt, i, &s1, &l1, &x1); rt_sub(&g->rt, j, &s2, &l2, &x2);
            if (s1 && s1 == s2 && l1 == l2 && x1 == x2) { o->clear_c[i] = 0; break; } }
        if ((o->clear_d || o->clear_s) && (g->clear_d || g->clear_s)) { uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(&o->rt, 8, &s1, &l1, &x1); rt_sub(&g->rt, 8, &s2, &l2, &x2);
            if (s1 && s1 == s2 && l1 == l2 && x1 == x2) { if (g->clear_d) o->clear_d = 0; if (g->clear_s) o->clear_s = 0; } } }
    g_nlc++;
    memset(R.clear_c, 0, sizeof R.clear_c); R.clear_d = R.clear_s = 0;
}
// Whether the program samples a texture with a waiting clear (a program with bindless or dynamic handles counts as sampling)
static int lc_sampled(NvProg *pr) {
    if (!pr) return 1;
    for (int st = 0; st < 5; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || sh->stage >= 6) continue;
        if (sh->rf.bindless || sh->rf.dyn) return 1;
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; uint64_t h;
            if (b->kind == NVN_RB_IMG) h = b->reg < 32 ? S.img[sh->stage][b->reg] : 0; else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) h = tex_slot_h(S.tex[sh->stage], S.img[sh->stage], b->reg); else continue;
            uint64_t ser = h ? h_ser(h) : 0; if (!ser) continue;
            for (int gi = 0; gi < g_nlc; gi++) { const lc_group *g = &g_lc[gi];
                for (int k = 0; k < 8; k++) if (g->clear_c[k] && g->rt.color[k] && g->rt.color[k]->serial == ser) return 1;
                if ((g->clear_d || g->clear_s) && g->rt.depth && g->rt.depth->serial == ser) return 1; } } }
    return 0;
}
// The draw about to open a pass: its attachments take the waiting clears of the same subresources (the newest one; the pass's own pending clear is newer still), the rest land first
static void lc_take(NvProg *pr) {
    if (lc_sampled(pr)) { lc_land(); return; }
    for (int gi = g_nlc - 1; gi >= 0; gi--) { lc_group *g = &g_lc[gi];
        for (int i = 0; i < 8; i++) if (g->clear_c[i])
            for (int j = 0; j < R.rt.n && j < 8; j++) if (R.rt.color[j] && !rt_dup_slot(&R.rt, j) && !nvn_fmt_bc(R.rt.color[j]->d.format) && lc_same(&g->rt, i, &R.rt, j)) {
                if (!R.clear_c[j]) { R.clear_c[j] = 1; R.cc[j] = g->cc[i]; }
                g->clear_c[i] = 0; g_lc_taken++; break; }
        if ((g->clear_d || g->clear_s) && R.rt.depth && lc_same(&g->rt, 8, &R.rt, 8)) {
            if (g->clear_d) { if (!R.clear_d) { R.clear_d = 1; R.cd = g->cd; } g->clear_d = 0; }
            if (g->clear_s) { if (!R.clear_s) { R.clear_s = 1; R.cs = g->cs; } g->clear_s = 0; }
            g_lc_taken++; } }
    lc_land();
}
// The operations a waiting clear can wait across: they neither read nor write textures
static int unb_keeps(uint32_t op) {   // pure state an open pass carries over to the targets set again (see unb_on); anything else lands a held unbind first
    switch (op) {
        case OP_SET_RT: case OP_VIEWPORTS: case OP_SCISSOR: case OP_DEPTH_RANGE: case OP_BIND_PROGRAM: case OP_BIND_STATE: case OP_BIND_VATTR: case OP_BIND_VSTREAM: case OP_BIND_VBUF:
        case OP_BIND_UBO: case OP_BIND_SSBO: case OP_BIND_TEX: case OP_BIND_TEX1: case OP_BIND_SAMP: case OP_BIND_IMG: case OP_STENCIL: case OP_POLY_OFFSET: case OP_BLEND_COLOR:
        case OP_ALPHA_REF: case OP_DEPTH_CLAMP: case OP_SET_PATCH_SIZE: case OP_VP_SWIZZLE: case OP_PRIM_RESTART: case OP_RAST_DISCARD: case OP_SET_TEX_POOL: case OP_SET_SAMP_POOL:
        case OP_JUMP: case OP_CALL: return 1;
        default: return 0;
    }
}
static int lc_keeps(uint32_t op) {
    switch (op) {
        case OP_SET_RT: case OP_CLEAR_COLOR: case OP_CLEAR_DS: case OP_DRAW: case OP_DRAW_IDX: case OP_BEGIN: case OP_JUMP: case OP_CALL:
        case OP_SCISSOR: case OP_BIND_PROGRAM: case OP_BIND_STATE: case OP_BIND_VATTR: case OP_BIND_VSTREAM: case OP_BIND_VBUF:
        case OP_BIND_UBO: case OP_BIND_SSBO: case OP_BIND_TEX: case OP_BIND_TEX1: case OP_BIND_SAMP: case OP_BIND_IMG: case OP_STENCIL:
        case OP_POLY_OFFSET: case OP_VIEWPORTS: case OP_DEPTH_RANGE: case OP_DEPTH_CLAMP: case OP_VP_SWIZZLE: case OP_BLEND_COLOR:
        case OP_TF_BIND: case OP_TF_STATE: case OP_RAST_DISCARD: case OP_PRIM_RESTART: case OP_SET_PATCH_SIZE: case OP_ALPHA_REF: case OP_BARRIER: case OP_SET_TEX_POOL: case OP_SET_SAMP_POOL: case OP_RENDER_COND:
        case OP_UPDATE_UB: case OP_COPY_B2B: case OP_CLEAR_BUF: return 1;
        default: return 0;
    }
}

// Depth-stencil state, stencil reference, viewport, scissor, cull / winding / fill / bias / depth clip, blend colour: everything a draw sets on its encoder besides the pipeline,
// the vertex buffers and the arguments. Shared by draw and the tessellation render pass (tess_draw ④, whose vertex stage is the domain shader): the same game state applies to both.
// → 0 when nothing of this draw can be drawn (empty scissor, both faces culled); the caller skips it.
// Gap family 34: an alpha-tested fragment variant (pso_key.at, fs_atms_fn) reads the reference at fragment slot 30 (Dsh.cs FsAlphaMs s2a_aref). The value is command-buffer state
//   (SetAlphaRef, OP_ALPHA_REF), written per draw through the argument table (the deferred encoder records table writes, no new encoder method); draws without the test bind nothing
static void alpha_ref_bind(id en, NvShader *fs) {
    int af = (int)S.color.alpha_func; if (!fs || !fs->has_atms || af < 1 || af > 7) return;
    __unsafe_unretained id<MTLBuffer> b; size_t o = arena_alloc_u(sizeof S.alpha_ref, &b); memcpy((uint8_t *)b.contents + o, &S.alpha_ref, sizeof S.alpha_ref);
    enc_r_args(en, MTLRenderStageFragment, b.gpuAddress + o, 30);
}
// Fragment depth vs a stored depth: a fragment shader that reads gl_FragCoord.z (json frag_z, component level) and samples a depth texture can compare the two
//   (self-peel style "z > depth an earlier pass wrote from the same geometry → drop"). On NVIDIA both come from one interpolator and match exactly; on Apple GPUs the
//   [[position]].z the fragment sees can be 1 ULP farther than what the fixed-function depth stored for the same triangle (~3% of pixels, a 2-pixel beat pattern along
//   the depth slope), so a zero-tolerance compare drops front-surface pixels and leaves a grid of isolated holes (measured: ~1300 of ~50k fog pixels). setDepthBias
//   moves [[position]].z too on Apple GPUs, so 1 unit toward passing restores the tie (measured: ~1300 → ~60, see the PR).
//   Scope: only draws that test but do not write depth (no depth buffer content changes), and only LESS / LEQUAL. Measured on Apple M1 (tests/t_nvn_fragz_bias.m):
//   every pixel moves at least 1 ULP of its own depth and at most one unit 2^(e - 23), e the exponent of the primitive's largest depth, so pixels in that top
//   binade move 1 ULP (2 if the triangle reaches exactly 1.0) and pixels far below it more ULPs (up to ~256 at z 0.002). With LESS / LEQUAL small z is near the
//   camera, where that is a negligible distance; with GREATER / GEQUAL (reverse Z) small z is far away and the same amount could show through, so those get none.
//   DM_NVN_FRAGZ_BIAS=<units> changes the amount, 0 turns it off.
static float fragz_bias_units(int fragz, int dt, int dw, int df, int has_depth, int samples_depth, const char *key) {
    static float fzb = -1e9f; if (fzb == -1e9f) { const char *e = getenv("DM_NVN_FRAGZ_BIAS"); fzb = e ? (float)atof(e) : 1.0f; if (e) MLOG("DM_NVN_FRAGZ_BIAS=%g: depth-test-only LESS / LEQUAL draws whose fragment shader reads gl_FragCoord.z and samples a depth texture get %g units of depth bias toward passing", fzb, fzb); }
    if (!fzb || !fragz || !dt || dw || !has_depth || !samples_depth || (df != NVN_DEPTH_FUNC_LESS && df != NVN_DEPTH_FUNC_LEQUAL)) return 0;
    static int once; if (!once) { once = 1; MLOG("fragment depth bias: first depth-test-only draw whose fragment shader reads gl_FragCoord.z and samples a depth texture (fs %s, func %d) gets %g units toward passing", key ? key : "?", df, fzb); }
    return -fzb;
}
// Does this draw's fragment shader have a depth-format texture bound (DEPTH16 .. DEPTH32F_STENCIL8; fmt_depth also counts STENCIL8)? For fragz_bias_units
static int fs_samples_depth(const NvShader *fs) {
    int tids[64]; int nt = 0;
    for (int i = 0; i < fs->rf.nb && nt < 64; i++) {
        const nvn_rbind *b = &fs->rf.b[i];
        if (b->kind == NVN_RB_TEX) {
            if (b->reg < NTEX) tids[nt++] = (int)(tex_slot_h(S.tex[1], S.img[1], b->reg) & 0xfffff);
        } else if (b->kind == NVN_RB_TEXU) {
            int n = b->n ? b->n : 1;
            for (int k = 0; k < n && nt < 64; k++) {
                uint32_t h = b->n ? ubo_handle(1, b->reg, 8 * k) : ubo_packed(1, b);
                if (g_handle_read_failed) break;
                tids[nt++] = ubo_tex_id(h);
            }
        }
    }
    if (!nt) return 0;
    int hit = 0;
    os_unfair_lock_lock(&g_rmu);
    for (int i = 0; i < nt; i++) {
        int tid = tids[i];
        int f = tid >= 0 && tid < g_ntreg && g_treg[tid].ok ? (int)g_treg[tid].t.d.format : 0;
        if (f >= NVN_FORMAT_DEPTH16 && f <= NVN_FORMAT_DEPTH32F_STENCIL8) { hit = 1; break; }
    }
    os_unfair_lock_unlock(&g_rmu);
    return hit;
}
static int draw_pass_state(id en, NvShader *fs) {   // en: the render encoder (typed id: enc_r_dss and friends take the Metal 4 type; naming it here would add an unguarded Metal 4 symbol, tools/avail_count.sh)
    static id<MTLDepthStencilState> cur_ds; static uint64_t cur_ds_pass;
    // Diagnostic DM_NVN_DEPTHOVR=fragment shader key prefix,...: those draws compare depth with ALWAYS, which tells "the depth test rejects every fragment" from "nothing rasterizes" (with DM_NVN_HILITE); unset = unchanged
    static char dko[8][24]; static int ndko = -1;
    if (ndko < 0) { ndko = 0; const char *e = getenv("DM_NVN_DEPTHOVR");
        for (const char *q = e; q && *q && ndko < 8; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) { size_t n = strcspn(q, ","); if (n > 23) n = 23; memcpy(dko[ndko], q, n); dko[ndko++][n] = 0; } }
    if (ndko) { int ovr = 0; for (int i = 0; i < ndko && fs; i++) ovr |= !strncmp(fs->key, dko[i], strlen(dko[i]));
        unsigned df0 = (unsigned)S.ds.df; if (ovr) S.ds.df = 8; cur_ds = dss_get(g_pass.hd, g_pass.hs); S.ds.df = df0; cur_ds_pass = g_pass.serial; g_dss_dirty = 0; }
    else if (g_dss_dirty || cur_ds_pass != g_pass.serial) { cur_ds = dss_get(g_pass.hd, g_pass.hs); cur_ds_pass = g_pass.serial; g_dss_dirty = 0; }
    if (cur_ds != g_enc_dss) { enc_r_dss(en, cur_ds); g_enc_dss = cur_ds; }
    if (!(g_ed.ok & ED_SREF) || g_ed.sref[0] != S.st_ref[0] || g_ed.sref[1] != S.st_ref[1]) {   // front and back references (audit gap family 36: the back one used to be dropped)
        enc_r_stencil_ref(en, S.st_ref[0], S.st_ref[1]); g_ed.sref[0] = S.st_ref[0]; g_ed.sref[1] = S.st_ref[1]; g_ed.ok |= ED_SREF; }
    // Viewport / scissor (clamped within the target size)
    NSUInteger tw = g_pass.tw, th = g_pass.th;
    { MTLViewport v = S.has_vp ? (MTLViewport){S.vp[0][0], S.vp[0][1], S.vp[0][2], S.vp[0][3], S.dr[0], S.dr[1]} : (MTLViewport){0, 0, tw / g_pass.rs, th / g_pass.rs, 0, 1};   // no viewport: the whole target, in canvas units (internal resolution)
      if (g_wd > 0) { float x = (float)v.originX, w = (float)v.width, r0 = x + w; s2a_widen_map_viewport(g_wd_mode, &x, &w); v.originX = x; v.width = w;
        { float y = (float)v.originY, h = (float)v.height; s2a_widen_map_viewport_y(g_wd_mode, &y, &h); v.originY = y; v.height = h; }   // narrower screen: more picture above and below (s2a_widen_ky > 1)
        if (x + w > (float)(tw / g_pass.rs) + 1.0f && x + w > r0 + 0.5f) RED_ONCE(113, "widen: viewport %.0f+%.0f past the target's storage width %lu (ser=%llu, storage not widened): the right part is clipped (first case)", x, w, (unsigned long)tw,
                                              (unsigned long long)(R.has_rt && R.rt.n > 0 && R.rt.color[0] ? R.rt.color[0]->serial : 0)); }   // S2Arm widen: the storage is narrower than the widened viewport (tex_widen could not widen it); up to a texel over is level rounding: 391 wide, level 2 is 97, 80 x k = 97.75; only past what the game's own viewport reached (Monster Hunter Rise draws a 156-wide viewport on a 78-wide target, widen off as well)
      if (g_pass.rs != 1.0) { v.originX *= g_pass.rs; v.originY *= g_pass.rs; v.width *= g_pass.rs; v.height *= g_pass.rs; }   // S2Arm internal resolution: canvas → storage (nvn_rscale.inc)
      if (atomic_load_explicit(&g_origin_ll, memory_order_relaxed)) { v.originY += v.height; v.height = -v.height; }   // lower-left origin (see g_origin_ll)
      // Viewport swizzle: NEGATIVE_Y negates clip y, the same as the viewport flipped about its centre; facing is decided after it on the GPU as in Metal, so the winding stays.
      // Other swizzles (axis exchanges, negated x / z / w) are no viewport change and are drawn unswizzled
      { uint32_t sw; memcpy(&sw, S.vp_sw[0], 4);
        if (sw == 0x100) { v.originY += v.height; v.height = -v.height; }
        else if (sw) RED_ONCE(108, "viewport swizzle %d,%d,%d,%d not implemented (drawn unswizzled)", S.vp_sw[0][0], S.vp_sw[0][1] ^ 2, S.vp_sw[0][2] ^ 4, S.vp_sw[0][3] ^ 6); }
      if (!(g_ed.ok & ED_VP) || memcmp(&g_ed.vp, &v, sizeof v)) { enc_r_viewport(en, v); g_ed.vp = v; g_ed.ok |= ED_VP; } }
    MTLScissorRect sc = {0, 0, tw, th};
    if (R.has_sc) {
        p_scissor rs = R.sc; if (g_wd > 0) { s2a_widen_map_scissor(g_wd_mode, &rs.x, &rs.w); s2a_widen_map_scissor_y(g_wd_mode, &rs.y, &rs.h); }   // S2Arm widen
        if (g_wd > 0 && wd_tr_on()) MLOG("S2Arm widen trace: frame %llu scissor %d,%d %dx%d -> %d,%d %dx%d mode %d", (unsigned long long)g_wd_frame, R.sc.x, R.sc.y, R.sc.w, R.sc.h, rs.x, rs.y, rs.w, rs.h, g_wd_mode);   // 11-02 怪猎对话框正文被切：剪刀原值 / 换算后对照（追踪行只打视口）
        long sx = rs.x, sy = rs.y, sw = rs.w, sh = rs.h; rs_rect(g_pass.rs, &sx, &sy, &sw, &sh);   // S2Arm internal resolution: canvas → storage
        long x0 = sx < 0 ? 0 : sx, y0 = sy <= 0 ? 0 : sy, x1 = sx + sw, y1 = sy + sh;
        if (x1 > (long)tw) x1 = tw; if (y1 > (long)th) y1 = th;
        if (x1 <= x0 || y1 <= y0) { PD("Z %llu draw skipped: empty scissor (%d,%d %dx%d, target %lux%lu)", g_stat_pass, rs.x, rs.y, rs.w, rs.h, (unsigned long)tw, (unsigned long)th); return 0; }
        sc = (MTLScissorRect){(NSUInteger)x0, (NSUInteger)y0, (NSUInteger)(x1 - x0), (NSUInteger)(y1 - y0)};
    }
    if (!(g_ed.ok & ED_SC) || memcmp(&g_ed.sc, &sc, sizeof sc)) { enc_r_scissor(en, sc); g_ed.sc = sc; g_ed.ok |= ED_SC; }
    if (S.poly.cull == NVN_FACE_FRONT_AND_BACK) { PD("Z %llu draw skipped: both faces culled", g_stat_pass); return 0; }
    { int cu = S.poly.cull == NVN_FACE_FRONT ? MTLCullModeFront : S.poly.cull == NVN_FACE_BACK ? MTLCullModeBack : MTLCullModeNone;
      // Front face: the game's own driver writes the API value into the front-face register and sets Maxwell's TriangleRastFlip once, in QueueInitialize, when the device's
      //   window origin is not upper-left at that moment (s2a_nvn_rast_flip, hle_nvn.c). Ryujinx keeps the register with the flip on and swaps it with the flip off
      //   (StateUpdater.UpdateFrontFace), and its Metal backend inverts it: Metal gets the inverse of the API value with the flip on, the API value with it off.
      //   Measured in the generic mode: Need for Speed Hot Pursuit Remastered (queue created before it set upper-left: flip on, front CW) and Diablo III (upper-left first:
      //   flip off, front CCW) both end at counter-clockwise. This used to follow the current window origin, the same thing for games that set it before creating the queue;
      //   Need for Speed got its front faces culled and drew car and track black (tests/t_nvn_winding.m)
      int wi = (S.poly.front == NVN_FRONT_FACE_CCW) != (s2a_nvn_rast_flip != 0) ? MTLWindingCounterClockwise : MTLWindingClockwise;
      int fi = S.poly.mode == NVN_POLYGON_MODE_LINE ? MTLTriangleFillModeLines : MTLTriangleFillModeFill, cl = !S.depth_clamp;   // depth clip off = SetDepthClamp
      float bi[3] = {0, 0, 0}; if (S.poly.offset_en & 4) { bi[0] = S.po.units; bi[1] = S.po.factor; bi[2] = S.po.clamp; }
      if (fs && fs->fragz && S.ds.dt && !S.ds.dw) bi[0] += fragz_bias_units(1, 1, 0, (int)S.ds.df, R.rt.depth != NULL, fs_samples_depth(fs), fs->key);   // see fragz_bias_units
      if (!(g_ed.ok & ED_CULL) || g_ed.cull != cu) { enc_r_cull(en, (MTLCullMode)cu); g_ed.cull = cu; g_ed.ok |= ED_CULL; }
      if (!(g_ed.ok & ED_WIND) || g_ed.wind != wi) { enc_r_winding(en, (MTLWinding)wi); g_ed.wind = wi; g_ed.ok |= ED_WIND; }
      if (!(g_ed.ok & ED_FILL) || g_ed.fill != fi) { enc_r_fill(en, (MTLTriangleFillMode)fi); g_ed.fill = fi; g_ed.ok |= ED_FILL; }
      if (!(g_ed.ok & ED_BIAS) || memcmp(g_ed.bias, bi, sizeof bi)) { enc_r_depth_bias(en, bi[0], bi[1], bi[2]); memcpy(g_ed.bias, bi, sizeof bi); g_ed.ok |= ED_BIAS; }
      if (!(g_ed.ok & ED_CLIP) || g_ed.clip != cl) { enc_r_depth_clip(en, cl); g_ed.clip = cl; g_ed.ok |= ED_CLIP; }
      if (!(g_ed.ok & ED_BLEND) || memcmp(g_ed.blend, S.blend_color, sizeof g_ed.blend)) { enc_r_blend_color(en, S.blend_color[0], S.blend_color[1], S.blend_color[2], S.blend_color[3]); memcpy(g_ed.blend, S.blend_color, sizeof g_ed.blend); g_ed.ok |= ED_BLEND; } }
    return 1;
}
// S2Arm tessellation: 曲面绘制（prim == 14 patches）
// 四段流程：①VS 捕获（光栅关的渲染遍跑 main0_gs，写 144 字捕获记录）+ 搬运核（按映射 / 规范布局搬成 TCS 输入） ②TCS（计算核）→曲面因子+域控制点 ③固定核（count/scan/emit）→域点+索引 ④渲染pass（TES顶点+fragment）
// ① 照 nvn_geometry.inc geo_draw：槽 13 绑捕获信息块 {输入缓冲地址, 0, first, span, first_instance, instances}（dmsh_geometry.py dm_geometry_capture），间接参数与索引在 CPU 上读（先等 GPU 写完），
//   索引去重排序后画点，第 i 个控制点 = 捕获里的 索引[i] − lo（nvn_builtin.h nvn_tess_index_plan）；搬运核 nvn_tess_gather 按这张表把控制点搬成规范布局（gal_tessxc.m gal_tess_canon）的连续缓冲，
//   因为捕获记录与 TCS 读的规范布局都是 576 字节却排布不同（位置在字 0 对字 128、通用位置在字 16+4L 对 4L），TCS 是离线翻好的核改不了读法
static inline void tess_skipped(void) { g_tess_skips++; g_tess_dom_skips[g_tess_dom]++; }
#define TESS_SKIP(...) do { tess_skipped(); static int n_; if (n_++ < 8) MLOG("【红】 " __VA_ARGS__); } while (0)
static void tess_stat_line(uint64_t frame) {   // 定期（nvn_be_mem_stat）：局里看得到曲面画了 / 跳过多少、各在哪个域；没有曲面绘制不打
    if (!g_tess_draws && !g_tess_skips) return;
    MLOG("tessellation up to frame %llu: drawn %llu (isolines %llu / triangles %llu / quads %llu, %llu patches), skipped %llu (isolines %llu / triangles %llu / quads %llu / undefined domain %llu / before the domain was known %llu)",
         (unsigned long long)frame, (unsigned long long)g_tess_draws, (unsigned long long)g_tess_dom_draws[0], (unsigned long long)g_tess_dom_draws[1], (unsigned long long)g_tess_dom_draws[2],
         (unsigned long long)g_tess_patches, (unsigned long long)g_tess_skips, (unsigned long long)g_tess_dom_skips[0], (unsigned long long)g_tess_dom_skips[1], (unsigned long long)g_tess_dom_skips[2],
